\section{Proof: Meta model ensemble is more robust than uniform ensemble}
\label{proof}


Let the input space be $X$ and the label space be $Y = [C] = \{1, \dots, C\}$. Consider an ensemble of $C$ experts $\mathcal{F} = \{f_c\}_{c=1}^C$, where each expert $f_c : X \to \mathbb{R}^C$ outputs a logit vector.

Let $\hat{x} \in X$ be a given input and $\mathcal{F}(\hat{x}) = \{f_1, \dots, f_k\} \subseteq \mathcal{F}$ be the subset of active experts.

\subsection*{Ensemble Methods}

\begin{itemize}
    \item \textbf{Vanilla Ensemble (VE)}: Uniform averaging of expert logits:
    \begin{equation}
        f_{\text{ve}}(\hat{x}) = \frac{1}{k} \sum_{c=1}^k f_c(\hat{x}).
    \end{equation}

    \item \textbf{Meta-Enhanced Ensemble (ME)}: Weighted combination via a meta model $M$:
    \begin{equation}
        f_{\text{me}}(\hat{x}) = \sum_{c=1}^k \alpha_c(\hat{x}) \cdot f_c(\hat{x}),
    \end{equation}
    where weights $\alpha_c(\hat{x}) \geq 0$ satisfy $\sum_{c=1}^k \alpha_c(\hat{x}) = 1$, and are learned to minimize predictive loss (e.g., cross-entropy).
\end{itemize}

\subsection*{Assumptions}

\begin{description}
    \item[Assumption 1 (Error Decomposition)] Each expert prediction can be decomposed as
    \begin{equation}
        f_c(\hat{x}) = f^*(\hat{x}) + \epsilon_c(\hat{x}) + \delta_c(\hat{x}),
    \end{equation}
    where $f^*(\hat{x})$ is the ideal predictor, $\epsilon_c(\hat{x}) \sim \mathcal{N}(0, \sigma_c^2 I)$ represents zero-mean independent noise, and $\delta_c(\hat{x})$ is the systematic bias vector. \textbf{Assume uncorrelated noise:} $\mathrm{Cov}(\epsilon_i, \epsilon_j) = 0$ for $i \neq j$.

    \item[Assumption 2 (Meta model Capacity)] The meta model $M$ can approximate the optimal conditional weighting:
    \begin{equation}
        \alpha_c(\hat{x}) \approx \mathbb{E}\left[ \alpha_c^*(\hat{x}) \middle| \hat{x} \right], \quad \text{where } \alpha_c^*(\hat{x}) \propto \frac{1}{\sigma_c^2 + \|\delta_c(\hat{x})\|^2}.
    \end{equation}
    This weighting corresponds to the \emph{mean squared error (MSE)} optimal combination, balancing both variance $\sigma_c^2$ and bias $\|\delta_c(\hat{x})\|^2$.
    In our theoretical analysis (Theorem~1), we focus on an idealized setting where weights are chosen to minimize prediction variance only:
    \[
    \alpha_c^* \propto \frac{1}{\sigma_c^2}.
    \]
    This variance-only objective simplifies the analysis and yields a lower bound on the ensemble’s prediction variance. Although it differs from the MSE-optimal weighting—--which accounts for both variance and bias—--both approaches share the principle of assigning greater weight to more reliable experts (those with lower variance or bias).
    Nonetheless, variance and MSE are not equivalent metrics, and minimizing variance alone does not necessarily minimize MSE. We adopt this idealized assumption primarily for analytical tractability and to gain theoretical insight into the benefits of meta-enhanced weighting.

\end{description}

\subsection*{Theorem: Robustness Superiority of Meta-Enhanced Ensemble}

\begin{theorem}
Under Assumptions 1 and 2, the meta-enhanced ensemble achieves lower expected prediction variance than the vanilla ensemble:
\begin{equation}
    \mathbb{E}_{\hat{x}} \left[ \mathrm{Var}(f_{\text{me}}(\hat{x})) \right] < \mathbb{E}_{\hat{x}} \left[ \mathrm{Var}(f_{\text{ve}}(\hat{x})) \right],
\end{equation}
with equality if and only if all experts are homogeneous, i.e., $\sigma_1^2 = \dots = \sigma_k^2$ and $\delta_1 = \dots = \delta_k$.
\end{theorem}

\begin{proof}
\textbf{Vanilla Ensemble (VE)} variance:
\begin{align}
    \mathrm{Var}(f_{\text{ve}}(\hat{x})) &= \mathrm{Var} \left( \frac{1}{k} \sum_{c=1}^k f_c(\hat{x}) \right) \\
    &= \frac{1}{k^2} \sum_{c=1}^k \mathrm{Var}(f_c(\hat{x})) = \frac{1}{k^2} \sum_{c=1}^k \sigma_c^2.
\end{align}

\textbf{Meta-Enhanced Ensemble (ME)} variance with optimal weights:
\begin{equation}
    \alpha_c^* = \frac{1 / \sigma_c^2}{\sum_{j=1}^k 1 / \sigma_j^2}, \quad
    \Rightarrow \quad \mathrm{Var}(f_{\text{me}}(\hat{x})) = \sum_{c=1}^k (\alpha_c^*)^2 \sigma_c^2 = \frac{1}{\sum_{c=1}^k 1 / \sigma_c^2}.
\end{equation}

By the inequality between the harmonic and arithmetic mean:
\begin{equation}
    \frac{1}{\sum_{c=1}^k 1 / \sigma_c^2} \leq \frac{1}{k} \left( \frac{1}{k} \sum_{c=1}^k \sigma_c^2 \right),
\end{equation}
with equality if and only if all $\sigma_c^2$ are equal.
\end{proof}

\subsection*{Lemma: Bias Bound of Meta-Enhanced Ensemble}

\begin{lemma}
When weights $\alpha_c(\hat{x})$ downweight high-bias experts, the bias of ME satisfies:
\begin{equation}
    \mathbb{E} \left[ \left\| \mathbb{E}[f_{\text{me}}(\hat{x})] - f^*(\hat{x}) \right\|^2 \right] \leq \max_c \|\delta_c(\hat{x})\|^2.
\end{equation}
\end{lemma}

\begin{proof}
By Jensen's inequality:
\begin{equation}
    \left\| \sum_{c=1}^k \alpha_c(\hat{x}) \delta_c(\hat{x}) \right\|^2 \leq \sum_{c=1}^k \alpha_c(\hat{x}) \|\delta_c(\hat{x})\|^2 \leq \max_c \|\delta_c(\hat{x})\|^2.
\end{equation}
\end{proof}

\subsection*{Corollary: MSE Comparison}

\begin{corollary}
If $\sum_{c=1}^k \alpha_c(\hat{x}) \|\delta_c(\hat{x})\|^2 \leq \left\| \frac{1}{k} \sum_{c=1}^k \delta_c(\hat{x}) \right\|^2$, then
\begin{equation}
    \mathrm{MSE}_{\text{me}} < \mathrm{MSE}_{\text{ve}}.
\end{equation}
\end{corollary}

\begin{proof}
MSE is the sum of variance and squared bias:
\begin{equation}
    \mathrm{MSE}(f) = \| \mathbb{E}[f] - f^* \|^2 + \mathrm{Var}(f).
\end{equation}
By Theorem and Lemma above, both components are smaller for ME.
\end{proof}

\subsection*{Discussion: Theoretical vs.\ Practical Objectives}

While our theory establishes that variance-optimal weights $\alpha_c^* \propto 1/\sigma_c^2$ minimize the ensemble’s prediction variance (Theorem 1), in practice we optimize the meta model end-to-end using the cross-entropy loss. On held-out validation samples, we measure the average trace of the logit covariance and observe a 15\% reduction in variance compared to the vanilla ensemble. This empirical variance suppression, in turn, drives down MSE—--since lower variance under a fixed bias bound directly improves mean---squared error. We also experimented with adding an explicit variance-regularization term to the loss; the resulting weight allocations and variance reductions closely match those obtained under pure cross-entropy training, indicating that classification training alone is sufficient to penalize high-variance experts.

In practice, this theoretical insight has been extensively validated in ensemble learning \cite{Breiman_1996_Bagging, Wolpert_1992_Meta, Seni_2010_Ensemble}. We adopt this principle in our approach and empirically demonstrate its effectiveness with strong results.


\section{Tricks for Meta Model Training}
\label{tricks}


To train the meta model \( M \), we first extract \( q \) representative prototypes \( \{ p_i^{(j)} \}_{j=1}^q \) from each client \( i \). Each prototype is passed through a frozen ensemble of expert classifiers \( \mathcal{F} = \{ f_1, \dots, f_K \} \), where each \( f_k \) is a linear classifier producing logits:
\begin{equation}
z_i^{(j,k)} = f_k(p_i^{(j)}), \quad z_i^{(j,k)} \in \mathbb{R}^C.
\end{equation}

The outputs from all \( K \) experts are concatenated into a matrix:
\begin{equation}
Z_i^{(j)} = [z_i^{(j,1)}; z_i^{(j,2)}; \dots; z_i^{(j,K)}] \in \mathbb{R}^{K \times C},
\end{equation}
which is then reshaped into a vector in \( \mathbb{R}^{KC} \) for each sample.

To improve representation capacity, we first map each vector \( Z_i^{(j)} \in \mathbb{R}^{KC} \) to a higher-dimensional space via a linear projection:
\begin{equation}
h_i^{(j)} = W_{\text{expand}} Z_i^{(j)} + b_{\text{expand}}, \quad h_i^{(j)} \in \mathbb{R}^{KC}.
\end{equation}

Next, we apply a lightweight Transformer \cite{Vaswani_2017_Transformer} to model the interaction between expert logits across class dimensions. Specifically, we reshape the batch of logits into a sequence and apply self-attention over the expert dimension. The output of the Transformer is:
\begin{equation}
T_i^{(j)} = \text{Transformer}(h_i^{(j)}),
\end{equation}
where attention is performed independently for each class across experts.

Finally, the Transformer output is aggregated across experts and projected back to class logits using a final linear layer:
\begin{equation}
\hat{y}_i^{(j)} = W_{\text{final}} T_i^{(j)} + b_{\text{final}}, \quad \hat{y}_i^{(j)} \in \mathbb{R}^C.
\end{equation}

To reduce overfitting, we maintain an exponential moving average (EMA) of all meta model parameters \( \theta \). The EMA update rule at step \( t \) is:
\begin{equation}
\theta_{\text{EMA}}^{(t+1)} = \beta \theta_{\text{EMA}}^{(t)} + (1 - \beta) \theta^{(t+1)},
\end{equation}
where \( \beta \in [0, 1) \) is the decay rate. During evaluation, the EMA version of the model is used.

\paragraph{Remarks on the Meta Model Design.}
Our meta model resembles a soft-gating network, but it is more fine-grained. While conventional soft-gating mechanisms may apply a single weight to the entire output of each expert, our meta model operates at the level of individual logits, allowing for more precise control over expert contributions.
In addition, we incorporate a hard-gating mechanism, where the global model \( f \) itself serves as the gating network to determine which experts are activated. This hard gating is not essential and does not always lead to significant improvements, but it has shown to be effective on certain datasets such as CIFAR-100, making it a viable optional strategy.


