    \item Using similar reasoning to $\cA_1$ (see \eqref{eq:40}), we can show that $\cA_{3} = o(1)$ and hence $\cA_{4} = 1-o(1)$; this is shown by noting that when $m' \leq k^{1 + \frac{\xi}{2}}$ it holds that $m'q' \leq \Theta(\frac{k}{n}k^{1 + \frac{\xi}{2}}) = o(\frac{k}{n}k^{1+\xi})$.
    \item We can then deduce (similar to \eqref{eq:44}) that  $M' \geq k^{1 +\frac{\xi}{2}}$ with probability $1-o(1)$.
 %    \jon{Should this ``...which we do...'' be moved to the first dot point? 
 % i.e., more relevant to \eqref{eq:40} than to \eqref{eq:44}?}
    \item Since $k^{1 +\frac{\xi}{2}} = \omega(k)$, we observe that having at least $k^{1 +\frac{\xi}{2}}$ masked items implies having at least $\frac{1}{2}k^{1+\frac{\xi}{2}}$ masked non-defectives when $k$ is large enough.
    % We can then use this to show there are at least $\frac{1}{2}k^{1+\frac{\xi}{2}}$ masked non-defectives in the same manner as before (while still assuming at most $n^\xi$ tests per item).
    \item Finally, we drop the assumption that each item appears in at most $n^\xi$ tests; this is done by noting that Lemma \ref{lem5} still holds when ``number of masked items'' is replaced by ``number of masked items appearing in at most $n^{\xi}$ tests'' (see \cite[Procedure 3.1, Step 1]{bay2022optimal}) and using the same reasoning as Case 1.
\end{itemize}

