% As before, we wish to show that $\cA_{3} =o(1)$. We then employ the same methods used in the previous case to upper bound {\bf (copied above)}.

% Hence, by the multiplicative Chernoff bound, the probability that $M_1' \geq \frac{k}{4n}k^{1+\xi}$ decays to zero. 
%  As before, this implies $\cA_{4} = 1 - o(1)$. Using this, we can then lower bound the probability that $M' \geq k^{1 + \frac{\xi}{2}}$ by $1 - o(1)$, which we can then use to show there are at least $\frac{1}{2}k^{1 + \frac{\xi}{2}} = \omega(k)$ masked non-defective items by $1 - o(1)$ in the same manner as before when each item is in at most $n^{\xi}$ tests.  As noted earlier, we can drop the latter assumption using the same argument as that of the previous case (in particular, Lemma \ref{lem5} still holds when ``number of masked items'' is replaced by ``number of masked items appearing in at most $n^{\xi}$ tests'').}

\medskip
\noindent \textbf{\underline{Putting it All Together}}
\medskip

\noindent We have established that there are $\omega(k)$ masked non-defectives with high probability, and at least one masked defective (see Lemmas \ref{lem4} and \ref{lem5}).  We proceed to use this to bound $\bP(\suc) \coloneqq \bP(\hat{S} \supseteq S)$, where $\hat{S}$ is the output of an arbitrary decoding algorithm. To do so, we first recall a fact from \cite{coja2020optimal}.

\begin{lemma} \emph{\hspace*{-3px}\cite[Fact 3.1]{coja2020optimal}} \label{lem3}
    For a given test matrix $\sfX$ and outcome vector $\bfy$, let $\cV(\sfX, \bfy) \subseteq \cS$ be the collection of satisfying sets, i.e. the collection of $s \in \cS$ that would give rise to the test outcome $\bfy$ when using the test matrix $\sfX$. Then, under the combinatorial prior, it holds that $(S \mid \sfX, \bfy) \sim \mathrm{Unif}(\cV(\sfX, \bfy))$.
\end{lemma}
Lemma \ref{lem3} states that the posterior distribution of $S$ given the test outcomes and testing matrix is uniform over the sets that could have led to the observed outcome. This fact, in conjunction with the previously established high probability bounds on the number of masked items, allows us to bound $\bP(\suc)$ by showing that any estimate of size $(1 + \eta^{+})k$ with contains the true defective set with low probability over the posterior distribution of $S$.

Let $\cT(\sfX, \bfy) \subseteq \cV(\sfX, \bfy)$ be the satisfying sets that are a subset of $\hat{S}$, and further let $\widetilde{\cT}(\sfX, \bfy) \subseteq \cT(\sfX, \bfy)$ be the set of subsets $S'$ for which all of the following conditions hold:
\begin{itemize}
    \item[(i)] $S'$ is a satisfying set;
    \item[(ii)] $S'$ is a subset of $\hat{S}$;
    \item[(iii)] When the items in $S'$ are defective and the remaining items are non-defective, there is at least $1$ masked defective and at least $\frac{1}{2}k^{1+\frac{\xi}{2}}$ masked non-defectives.
\end{itemize}
Note that we use $\frac{1}{2}k^{1+\frac{\xi}{2}}$ in condition (iii) because it is the smaller of the two bounds we derived when we choose $\xi$ to be sufficiently small (the other bound is $\frac{n}{2k}k^{\frac{\gamma}{2}}$ with $k = o(\sqrt n)$, and we will only need this stronger bound later when proving the second part of the theorem). Accordingly, the calculations presented in the previous part of the proof imply that the true defective set $S$ satisfies
\begin{equation}
    \bP(S \notin \widetilde{\cT}(\sfX,\bfy)) = o(1).
\end{equation}
Accordingly, we we can write the success probability as follows:
\begin{align}
    \label{eq:55} \bP(\suc) &= \sum_{\sfX, \bfy} P_{\sfX \bfY}(\sfX, \bfy) \bP(\suc \mid \sfX, \bfy) \\
    \label{eq:56} &= \sum_{\sfX, \bfy} P_{\sfX \bfY}(\sfX, \bfy)\sum_{s \in \cT(\sfX, \bfy)} \bP(S = s \mid \sfX, \bfy) \\
    \label{eq:57} &= \sum_{\sfX, \bfy} P_{\sfX \bfY}(\sfX, \bfy)\sum_{s \in \widetilde{\cT}(\sfX, \bfy)} \bP(S = s \mid \sfX, \bfy)  + o(1) \\
    \label{eq:58} &= \sum_{\sfX, \bfy} P_{\sfX \bfY}(\sfX, \bfy) \frac{\abs{\widetilde{\cT}(\sfX, \bfy)}}{\abs{\cV(\sfX, \bfy)}} + o(1),
\end{align}
where \eqref{eq:58} follows from Lemma \ref{lem3}. 

Now suppose that for a given $(\sfX, \bfy)$ the decoder's estimate $\hat{S} = \hat{S}(\sfX, \bfy)$ satisfies $\abs{\widetilde{\cT}(\sfX, \bfy)} = N$.  If $N=0$ then the fraction in \eqref{eq:58} is trivially 0, so we henceforth assume that $N > 0$. 
%
% An upper bound on $\bP(\suc \mid \sfX, \bfy) = \frac{N}{\abs{\cV(\sfX, \bfy)}}$ can then be derived depending on the value of $N$.
% \begin{itemize}
%     \item If $N = 0$ then the success probability is trivially 0.
%     \item If $1 \leq N \leq k \log ^{\frac{1}{4}}n$, then pick an arbitrary plausible set, say $S_{1}$. Then, conditioned on $K$, the number of implausible $S_{1}' \in \cV(\sfX, \bfy)$ (i.e. sets such that $S_{1}' \not \subseteq \hat{S}$) is at least $\frac{1}{2}k \sqrt{\log n}$, since swapping out an individual masked defective item $i \in S_{1}$ with each of the at least $\frac{1}{2}k\sqrt{\log n}$ masked non-defectives leads to a distinct satisfying set. Thus, this implies that $\abs{\cV(\sfX, \bfy)} \geq \frac{1}{2}k\sqrt{\log n} + N$. Therefore, $\frac{N}{\abs{\cV(\sfX, \bfy)}} \leq \frac{N}{\frac{1}{2} k\sqrt{\log n} + N} \leq \frac{1}{\frac{1}{2}\log^{\frac{1}{4}}n+1} = o(1)$.
% \end{itemize}
% The only case left to deal with is the case $N \geq k\log^{\frac{1}{4}}n$, which requires a slightly more involved argument, since for sufficiently large $N$ the above approach provides too loose of a bound. H
%
We refer to the elements of $\widetilde{\cT}(\sfX, \bfy)$ as being \emph{plausible} for $\hat{S}$, and the elements of $\cV(\sfX, \bfy) \setminus \widetilde{\cT}(\sfX, \bfy)$ as being \emph{implausible}.  The number of plausible sets is $N$, and we will show that $\frac{\abs{\widetilde{\cT}(\sfX, \bfy)}}{\abs{\cV(\sfX, \bfy)}} = o(1)$ by arguing that the number of implausible sets is $\omega(N)$.

Denote the plausible sets by $S_1,\dotsc,S_N$ (the dependence on $(\sfX, \bfy)$ is left implicit), and note that by definition $|S_i|=k$.  We first argue that for every plausible set, there are many implausible sets obtained by swapping out a single element.  Specifically, swapping out one masked defective item (in $S_i$) with one masked non-defective item in $[n] \setminus \hat{S}$ produces an implausible set, because being plausible requires being a subset of $\hat{S}$.  Note that $S_i \subseteq \hat{S}$, so combining $|\hat{S}| = (1+\eta^+)k$ and $|S_i| = k$ gives that there are at most $\eta^- k$ masked non-defectives in $\hat{S}$, and hence at least  $\frac{1}{2}k^{1+\frac{\xi}{2}} - \eta^+k$ masked non-defectives in $[n] \setminus \hat{S}$ (see the definition of $\widetilde{\cT}$).  Thus, there are at least $\frac{1}{2}k^{1+\frac{\xi}{2}} - \eta^+k$ ways of performing the swap described above. For convenience, we apply $\eta^+ = k^{o(1)}$ to simplify $\frac{1}{2}k^{1+\frac{\xi}{2}} - \eta^+k \geq \frac{1}{4}k^{1+\frac{\xi}{2}}$ for sufficiently large $k$, and work with this simpler lower bound.

When we apply this argument to each plausible set $S_1,\dotsc,S_N$, some care is needed because their associated $N$ implausible sets  may overlap.  To upper bound the \emph{total} number of implausible sets, we identify a sufficiently large subset $\{S_i\}_{i=1}^{N'}$ for some $N' < N$ whose associated implausible sets (as constructed above) have no overlap.  For brevity, we refer to $S_i$'s associated implausible sets as the \emph{neighbors} of $S_i$.  Importantly, while the sets $S_i$ will typically have \emph{multiple} masked defectives, we designate a \emph{single} one (say, the one with the smallest index) to be the one that gets swapped out in the previous paragraph.

Then, we claim that in order for two plausible $S_i$ and $S_j$ to share a common neighbor, the following conditions must all hold:
\begin{itemize}
    \item $|S_i \setminus S_j| = |S_j \setminus S_i| = 1$;
    \item The unique element of $S_i \setminus S_j$ is the designated masked defective for $S_i$;
    \item The unique element of $S_j \setminus S_i$ is the designated masked defective for $S_j$.
\end{itemize}
The first condition is required because if $|S_i \setminus S_j| \ge 2$, then it will be impossible to swap out both of these 2 (or more) items (the neighbors only consist of performing a single swap), and similarly if $|S_j \setminus S_i| \ge 2$.  The two remaining conditions are required because if the element of $S_i \setminus S_j$ is not the designated defective, it is not allowed to be swapped out from $S_i$ (similarly for $S_j$).

Then, we consider the following greedy construction analogous to the Gilbert-Varshamov construction \cite{gilbert1952comparison}:
%owever, we can augment the preceding argument by considering the number of distinct $S_{i}' \in \cV(\sfX, \bfy)$ which can be formed by swapping out a single masked defective for a masked non-defective for \emph{several} $i \in \{1,2,\dots, N\}$. However, doing this naively may lead to overlap in the implausible sets, which may lead to double counting some of the sets. We note however, that if for $i \neq j$ it holds that $\abs{S_{i} \setminus S_{j}} \geq 2$, then their implausible sets must be distinct, since we are only swapping out one masked defective item from each plausible set. Thus, we can lower bound the number of implausible sets by considering only plausible sets with a minimum pairwise set difference of 2. We construct a set of these pairwise minimum set difference items using a greedy GV-type construction \cite{gilbert1952comparison} as follows:
\begin{enumerate}
    % \item For each $i \in \{1,2,\dots, N\}$ designate a single masked defective item to swap out with the masked non-defectives.
    \item Start with the empty set.
    \item Choose an arbitrary $i \in \{1,2, \dots, N\}$, add $S_i$ to the set being constructed, and then remove $S_i$ from further consideration along with all other $ \{S_j\}_{j \ne i} $ that satisfy the three dot points above.
    \item Repeat step 2 with the remaining plausible sets, and continue until there are no plausible sets remaining.
\end{enumerate}
We claim that for each $S_i$ chosen, the number of $S_j$ ($j \ne i$) removed is at most $\eta^+ k$, where we recall that $\eta^{+} = k^{o(1)}$.  This is because $S_i$ and $S_j$ necessarily share $k-1$ defectives in common, and there is only one choice for the item in $S_i \setminus S_j$ (it must be $S_i$'s designated defective) and at most $\eta^+ k$ choices for the item in $S_j \setminus S_i$ (it must be an element of $\hat{S} \setminus S_i$, where $|\hat{S}|=(1+\eta^+)k$ and $|S_i|=k$).

Thus, the above procedure extracts at least $\frac{N}{\eta^{+}k + 1}$ plausible sets, all of which have pairwise disjoint collections of implausible sets. As we already argued, each such collection contains at least $\frac{1}{4}k^{1+\frac{\xi}{2}}$ implausible sets, implying that $\abs{\cV(\sfX, \bfy)} \geq \frac{N}{\eta^{+}k + 1}\frac{1}{4} k^{1+\frac{\xi}{2}} + N$.  Since $\eta^+ = k^{o(1)}$, this implies that $\frac{\abs{\widetilde{\cT}(\sfX, \bfy)}}{\abs{\cV(\sfX, \bfy)}} \leq \frac{N}{\frac{N}{\eta^{+}k + 1}\frac{1}{4} k^{1+\frac{\xi}{2}} + N} = \frac{1}{\Omega\big(k^{\frac{\xi}{2} - o(1)}\big)} = o(1)$.  Substituting this into \eqref{eq:58}, we obtain $\bP(\suc) = o(1)$ as claimed. 

\medskip
\noindent \textbf{\underline{Establishing the Second Part of the Theorem}}
\medskip

\noindent When $\theta \in \big(\frac{\log 2}{1+\log 2}, \frac{1}{2}\big)$, we have established the stronger claim that there are $\omega(\frac{n}{k})$ masked non-defective items with high probability (rather than only $\omega(k)$).  We claim that this implies the same result when $\eta^{+} = \Omega(k^{\lambda})$ for $\lambda \in [0, \frac{1}{\theta}-2)$ (rather than only $\eta^{+} = k^{o(1)}$).  This is because under such a choice, we have (via $k = \Theta(n^{\theta})$) that the number of possible swaps with items not in $\hat{S}$ is at least $\frac{n}{2k}k^{\frac{\gamma}{2}} - \eta^+k = \Theta(\frac{n}{k}k^{\frac{\gamma}{2}})$, and that $\frac{(n/k)k^{\frac{\gamma}{2}}}{\eta^{+}k} \to \infty$, which implies $\frac{\abs{\widetilde{\cT}(\sfX, \bfy)}}{\abs{\cV(\sfX, \bfy)}} = o(1)$ by the same reasoning as that above. \qed

