\subsection{Concentration Inequalities} \label{app:bino}
Here we provide statements of some standard concentration inequalities (e.g., see \cite[Ch. 2]{concentration}) that we use throughout the paper. Letting $X_{1}, X_{2}, \dots, X_{n}$ be a sequence of i.i.d.~Bernoulli($\mu$) random variables, we have the following:
\begin{itemize}
    \item (Chernoff Bound for Binomial RVs) For any $\delta > 0$, we have 
    \begin{equation}
        \label{eq:chernoff_large} \bP\left(\sum_{i=1}^{n}X_{i} \geq (1+\delta)n\mu\right) \leq \exp\Big(-n\mu\big((1+\delta)\log(1+\delta)-\delta\big)\Big),
    \end{equation}
    and for any $\delta \in (0,1]$, we have
    \begin{equation}
        \label{eq:chernoff_small} \bP\left(\sum_{i=1}^{n}X_{i} \leq (1-\delta)n\mu\right) \leq \exp\Big(-n\mu\big((1-\delta)\log(1-\delta)+\delta\big)\Big).
    \end{equation}
    \item (Weakened Chernoff Bound for Binomial RVs) For any $\delta > 0$, we have 
    \begin{equation}
        \label{eq:weakchernoff_large} \bP\left(\sum_{i=1}^{n}X_{i} \geq (1+\delta)n\mu\right) \leq \exp\Big(-\frac{\delta^{2}}{3}n\mu\Big),
    \end{equation}
    and for any $\delta \in (0,1]$, we have
    \begin{equation}
        \label{eq:weakchernoff_small} \bP\left(\sum_{i=1}^{n}X_{i} \leq (1-\delta)n\mu\right) \leq \exp\Big(-\frac{\delta^{2}}{2}n \mu\Big).
    \end{equation}
\end{itemize}

\subsection{Two-Sided Approximate Recovery Rate  with Smaller Distortion} \label{sec:two_sided}
% \emph{(}\hspace*{-3px}\texorpdfstring{\emph{\cite[Theorem 3]{scarlett2016phase}}}{TEXT}\emph{)}
% when \texorpdfstring{$\beta = \Omega(k^{-\lambda(\frac{1}{\theta}-1)})$}{TEXT} for \texorpdfstring{$\lambda \in [0,\frac{1}{2})$}{TEXT}.} \label{sec:two_sided}

Here we outline the proof that algorithm in the algorithm in \cite{scarlett2016phase} still succeeds for two-sided approximate recovery when $\beta = \Omega(k^{-\lambda(\frac{1}{\theta}-1)})$ and $\lambda \in \big[0,\frac{1}{2}\big)$, as opposed to only constant $\beta \in (0,1)$.  We note that a variant of this idea (with $\beta = \Theta(k^{\gamma})$ for $\gamma \in (0,1)$) has been analyzed in \cite{scarlett2018noisy}, but the details differ slightly since they consider the noisy case.

%We note that the algorithm only fails if there is no $s' \in S$ with $\max\{\abs{S \setminus s'}, \abs{s' \setminus S}\} \leq \beta k$ such that \eqref{eq:12} holds for all partitions $(s'_{\mathrm{dif}}, s'_{\mathrm{eq}})$ with $\abs{s'_{\mathrm{dif}}} > \beta k$, or if there exists some $s'' \in \cS$ with $\max\{\abs{S \setminus s''}, \abs{s'' \setminus S}\} > \beta k$ for which the above condition holds. 
Recall the condition in \eqref{eq:12} defining the decoder, and let $T I(\tau)$ be the mean of $\imath^{T}\left(\sfX_{\sdif} ; \bfy \mid  \sfX_{\seq}\right)$.  (Here $I(\tau)$ is a conditional mutual information, but the precise definitions of $\imath^{T}$ and $I(\tau)$ are not needed for our purposes.)  
The following condition on the number of tests is stated in \cite[Eqn.~3.37]{scarlett2016phase} for parameters $\delta_1$ and $\{\delta_{2,\tau}\}_{\tau = \beta k + 1}^{k}$:
\begin{equation}
    \label{eq:T_bound} T \geq \frac{\log{n-k \choose \tau}+\log \big(\frac{k}{\delta_{1}}{k \choose \tau}\big)}{I(\tau)(1-\delta_{2, \tau})}.
\end{equation}
Letting $\cE$ denote the failure event for two-sided approximate recovery, \cite[Eqn.~3.38]{scarlett2016phase} states that if \eqref{eq:T_bound} holds for all $\tau = \beta k+1,\dots, k$, then the error probability is upper bounded as follows:
\begin{align} \label{eq:two_sided_error}
    \bP(\cE) \leq \sum_{\tau =\beta k+1}^{k}{k \choose \tau} \psi_{\tau}(T, \delta_{2, \tau}) + \delta_1,
\end{align}
where $\psi_{\tau}: \bZ \times \bR \to \bR$ comes from a concentration inequality given in \cite[Eqn. 3.45]{scarlett2016phase}, and is defined by
\begin{align}
   \psi_{\tau}(T, \delta_{2, \tau}) =
    \begin{cases}
        \exp\Big(-T \frac{\tau}{2k}\log 2 \big((1 -\delta_{2}^{(1)}) \log(1 - \delta_{2}^{(1)}) + \delta_{2}^{(1)}\big)(1 - \xi)\Big) & \tau \leq \frac{k}{\log k} \\
         2\exp\left(-\frac{(\delta_{2}^{(2)}I(\tau))^{2}T}{4(8+\delta_{2}^{(2)}I(\tau))}\right) & \tau > \frac{k}{\log k}       
    \end{cases} \label{eq:psi_def}
\end{align}
where $\xi > 0$ is arbitrarily small.

We apply \eqref{eq:two_sided_error} with $\delta_1 = \frac{1}{k}$, so that the second term is insignificant.  As for each $\delta_{2, \tau}$, this is set to $\delta_{2, \tau} = \delta_{2}^{(1)}$ for $\tau \leq \frac{k}{\log k}$, and to $\delta_{2, \tau} = \delta_{2}^{(2)}$ for $\tau > \frac{k}{\log k}$, where $\delta_{2}^{(1)}$ and $\delta_{2}^{(2)}$ will be specified shortly. We can then split the summation in \eqref{eq:two_sided_error} as follows:
\begin{align}
    \bP(\cE) &\leq \sum_{\tau = \beta k + 1}^{\frac{k}{\log k}}{k \choose \tau}\psi_{\tau}(T,\delta_{2}^{(1)}) +\sum_{\tau = \frac{k}{\log k} + 1}^{k}{k \choose \tau}\psi_{\tau}(T, \delta_{2}^{(2)}) + \frac{1}{k}. \label{eq:two_sums}
\end{align}
We can directly use part of the analysis in \cite[Appendix B]{scarlett2016phase}, showing that (i) \eqref{eq:T_bound} is satisfied for all $\tau= \beta k + 1,\dots, k$, and (ii) the second sum in \eqref{eq:two_sums} tends to $0$ for arbitrarily small $\delta_{2}^{(2)} > 0$, as long as $T \geq \big(k \log_{2}\frac{n}{k}\big)(1+\epsilon)$.  Hence, to show that $\bP(\cE) \to 0$, it suffices to show that the first sum in \eqref{eq:two_sums} also decays to zero. Note that if $\beta k + 1 > \frac{k}{\log k}$ then the sum is empty and is trivially zero, so henceforth we assume this is not the case. We proceed to bound this first sum as follows via \eqref{eq:psi_def}:
\begin{align}
    \label{eq:sum_bound_1}\cA_{} &\coloneqq \sum_{\tau = \beta k + 1}^{\frac{k}{\log k}}{k \choose \tau}\psi_{\tau}(T,\delta_{2}^{(1)}) \\
    \label{eq:sum_bound_2} &= \sum_{\tau = \beta k + 1}^{\frac{k}{\log k}}{k \choose \tau}\exp\Big(-T \frac{\tau}{2k}\log 2 \big((1 -\delta_{2}^{(1)}) \log(1 - \delta_{2}^{(1)}) + \delta_{2}^{(1)}\big)(1 - \xi)\Big) \\
    \label{eq:sum_bound_3} &\leq k\underset{\beta k + 1 \leq \tau\leq \frac{k}{\log k}}{\max} {k \choose \tau}\exp\Big(-T\frac{\tau}{2k}\log 2\big((1 - \delta_{2}^{(1)}) \log(1 - \delta_{2}^{(1)}) + \delta_{2}^{(1)}\big)(1 - \xi)\Big) \\
     \label{eq:sum_bound_4} &=\underset{\beta k+1 \leq \tau \leq \frac{k}{\log k}}{\max} \exp\Big(\log k + \log {k \choose \tau} - T \frac{\tau}{2k}\log 2 \big((1 - \delta_{2}^{(1)})\log(1 - \delta_{2}^{(1)})+ \delta_{2}^{(1)}\big)(1 - \xi)\Big) \\
    & \leq \underset{\beta k+1 \leq \tau \leq \frac{k}{\log k}}{\max} \exp\Big(\log k + \log{k \choose \tau} - \label{eq:sum_bound_5} T\frac{\tau}{2k}\cdot\frac{\log 2}{1+\epsilon'}\Big),
\end{align}
where \eqref{eq:sum_bound_5} follows by taking $\delta_{2}^{(1)}$ to be arbitrarily close to $1$ and introducing $\epsilon'  > 0$ that can be made arbitrarily small (as a function of $\xi$ and $\delta_{2}^{(1)}$). In order for $\cA_{} \to 0$, we require that the exponent in \eqref{eq:sum_bound_5} approaches $-\infty$.  For this to happen, it suffices that the following holds for all $\tau \in \big\{\beta k + 1,\dotsc,\frac{k}{\log k}\big\}$:
% is negative. Using this condition and rearranging for $T$, we require for all $\tau \in \big[\beta k, \frac{k}{\log k}\big]$ that
\begin{align}
   \label{eq:test_bound} T \geq \left(\log k + \log {k \choose \tau}\right)\frac{2k}{\tau\log 2 }(1 + 2\epsilon').
\end{align}
Since $\tau = o(k)$, we can write $\log {k \choose \tau} = \big(\tau\log\frac{k}{\tau}\big)\big(1+o(1)\big)$, and substituting this into \eqref{eq:test_bound} gives
\begin{align}
    \label{eq:test_bound_2.1} T &\geq \Big(\log k + \Big(\tau \log \frac{k}{\tau}\Big)\big(1+o(1)\big)\Big)\frac{2k}{\tau\log 2}(1+2\epsilon') \\
   \label{eq:test_bound_2.2} & = \frac{2}{\log 2}\Big(k \log \frac{k}{\tau}\Big)(1+2\epsilon')\big(1+o(1)\big) \\
   \label{eq:test_bound_2.3} &= 2 \Big( k \log_{2}\frac{k}{\tau}\Big)(1+2\epsilon')\big(1+o(1)\big).
\end{align}
Observe that the strictest requirement on $T$ is when $\tau = \beta k$. Substituting this into \eqref{eq:test_bound_2.3} and recalling that $\beta = \Omega(k^{^{-\lambda(1-\theta)}})$ and $k = \Theta(n^{\theta})$, the bound simplifies to
\begin{align}
    \label{eq:test_bound_2.4} T &\geq 2k \big(\log_{2}k^{\lambda(\frac{1}{\theta}-1)}\big)(1+2\epsilon')\big(1+o(1)\big) \\ 
    \label{eq:test_bound_2.5} &= 2\lambda k\Big(\log_{2}\frac{n}{k}\Big)(1+2\epsilon')\big(1+o(1)\big).
\end{align}
By the assumption $\lambda \in [0,\frac{1}{2})$, this condition on $T$ is satisfied when $T = (k\log_{2}\frac{n}{k})(1+\epsilon)$ for arbitrarily small $\epsilon > 0$.  Having established that $\bP(\cE) \to 0$ under this condition, the proof is complete. \qed
