%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Equality (\ref{eqn:slambdaintegration}) along with inequality (\ref{eqn:n1}), imply that for $M>M_4$,
\begin{equation}\label{ineq:fromlnsdifferencetosdifferences}
\frac{1}{\ln s}\!-\!\frac{1}{\ln s'}\geq \lambda(s)(s'\!-\!s-\ve |s'\!-\!s|/8) \;\; \forall s ,s'\geq M \mbox{ with } \gamma^{-1} s\leq s'\leq \gamma s.
\end{equation}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\textbf{Bounding the payoff from below:}
Now, we will prove that for $M>\max (M_1,M_2,M_3,M_4)$, where:
\begin{itemize}
  \item $M_1$ ensures that the difference  $v_{\lambda_{i+1}}-v_{\lambda_i}$ is small (see Lemma~\ref{lem:variationv}),
  \item $M_2$ guarantees that $v_{\lambda(s)}(z) \geq v(z) - \varepsilon/8$ (see~\eqref{eqn:vlambdav}),
  \item $M_3$ ensures that $\frac{\ln \gamma \ln \gamma s}{\ln s}$ is sufficiently small (see~\eqref{eqn:Mlarge enotgh1}),
  \item $M_4$ guarantees that 
$|\lambda(s)-\lambda(s')|<{\ve} \lambda(s)/8$ whenever $s'\in[\gamma^{-1}s,\gamma s]$ (see~\eqref{eqn:n1}),
\end{itemize} 
the strategy $\s=\s_{\ve,M,\lambda}$ obeys inequality~\eqref{ine:uniforme}.

Let $\mcF_i$ denote the algebra of the play up to stage $i$, including the sequence of memories $s_1,\ldots,s_i$ and the state $z_i$.

Recall that $\ve<1/4$ and $0\leq r\leq 1$. Therefore, $|x_i-v_{_{\lambda_i}}(z_{i+1})+\ve/2|\leq  1+\ve/2<9/8$. Therefore,
the definition of the conditional probabilities of $s_{i+1}$, given $s_i,x_i,z_{i+1}$ implies that for every $(\overline{m}_t)$-based strategy $\tau$ of Player 2, we have
\begin{eqnarray}E_{\s,\tau} (|s_{i+1}- s_i|\mid \mcF_i)&\leq & E_{\s} (|x_i-v_{_{\lambda_i}}(z_{i+1})+\ve/2| \mid s_i,x_i,z_{i+1})<9/8.
\end{eqnarray}

The definition of the conditional probabilistic law of $s_{i+1}$ has three implications.
First,
(by using $\ve<1/4$ and therefore $-1<x_i-v_{_{\lambda_i}}(z_{i+1})+{\ve/2}<2$)%, and $\gamma-1<1/3$ and %therefore $1-\gamma^{-1}<1/3$)
\begin{equation}\label{eqn:n3}
P(s_{i+1}\neq s_i \mid \mcF_i)\leq \frac{2}{s_i(\gamma-1)}. % \mbox{ and } E((s_{i+1}- s_i)_+ \mid \mcF_i)\leq 2,
\end{equation}

 Second,
as $E(x_i-v_{_{\lambda_i}}(z_{i+1})+{\ve/2}\mid \mcF_i)=E(s_{i+1}-s_i\mid \mcF_i)$ on $s_i>M$ and  $E({x_i-v_{_{\lambda_i}}(z_{i+1})} +  {\ve/2}\mid \mcF_i)  \geq E(s_{i+1}-s_i\mid \mcF_i)-1$ on $s_i=M$,
\begin{equation}\label{eqn:3n}E(x_i-v_{_{\lambda_i}}(z_{i+1}) \mid \mcF_i)\geq -{\ve/2}+E (s_{i+1}-s_i\mid \mcF_i)-1_{\{s_i=M\}}.
\end{equation}

As $\s$ plays at stage $i$ an optimal strategy in the $\lambda_i$-discounted game,
$E(\lambda_i x_i +(1-\lambda_i)\,v_{_{\lambda_i}} (z_{i+1}) \mid \mcF_i)\geq v_{_{\lambda_i}} (z_{i})$, and therefore,
\begin{equation}\label{eqn:1}
E(v_{_{\lambda_i}} (z_{i+1})-v_{_{\lambda_i}} (z_{i})+\lambda_i (x_i-v_{_{\lambda_i}}(z_{i+1})) \mid \mcF_i)\geq 0.
\end{equation}

By (\ref{eqn:n2}) and (\ref{eqn:n3}),
\begin{eqnarray*}E\left(\|v_{_{\lambda_{i+1}}}-v_{_{\lambda_{i}}}\|\mid \mcF_i\right)&\leq & E(\frac{2}{s_i(\gamma-1)}\;\left|\frac{\ve(\gamma -1)}{\ln s_i}-\frac{\ve(\gamma -1)}{\ln s_{i+1}}\right|\mid \mcF_i)\\
&=& E\left(\frac{2\ve |\ln s_{i+1}-\ln s_i|}{s_i\ln s_i \ln s_{i+1}}\mid \mcF_i\right)
\leq E\left(\frac{2\ve \ln \gamma}{s_i\ln s_i \ln s_{i+1}}\mid \mcF_i\right)\\
&=&E\left(\frac{2\ve \ln \gamma \ln s_i}{s_i\ln^2\!s_i \ln s_{i+1}}\mid \mcF_i\right)=2\ve \lambda_iE\left(\frac{\ln \gamma \ln s_i}{ \ln s_{i+1}}\mid \mcF_i\right).
\end{eqnarray*}
  Therefore, by using inequality (\ref {eqn:Mlarge enotgh1}), %$| \frac{\ln \gamma \ln s_i}{\ln s_{i+1}}|<2^{-4}$,
  we deduce that
\begin{equation}\label{ineq:vlambdachange} E(v_{_{\lambda_{i}}}(z_{i+1})-v_{_{\lambda_{i+1}}}(z_{i+1})\mid \mcF_i)\geq -\ve \lambda_i/16.\end{equation}

By adding inequalities (\ref{eqn:3n}) and (\ref{ineq:vlambdachange}), we have
\begin{eqnarray*}E(x_i-v_{_{\lambda_{i+1}}}(z_{i+1}) \mid \mcF_i)&\geq& -\ve/2 +E (s_{i+1}-s_i\mid \mcF_i) - 1_{\{s_i=M\}}-\ve \lambda_i/16\\ &\geq&  -9\ve/16 +E (s_{i+1}-s_i\mid \mcF_i) - 1_{\{s_i=M\}}.\end{eqnarray*}
%

As the expectation is the expectation of the conditional expectation, we deduce that
%
\[E\,x_i \geq E\,v_{_{\lambda_{i+1}}}(z_{i+1}) -9\ve/16 +E (s_{i+1}-s_i) - E\,1_{\{s_i=M\}}.\]


Summing these inequalities over $i=1,\ldots,n$, using the inequality $s_{n+1}-s_1\geq 0$, and dividing by $n$, we deduce that
\begin{equation}\label{eqn:preparetouniform}E\frac1n\sum_{i=1}^nx_i \geq E\frac1n\sum_{i=1}^nv_{_{\lambda_{i+1}}}(z_{i+1})-9\ve/16 - E\frac1n\sum_{i=1}^n1_{\{s_i=M\}}.
\end{equation}

\begin{lem}\label{lem:3}
\begin{eqnarray}\;\;\label{eqn:15}E\frac1n\sum_{i=1}^nv_{_{\lambda_{i+1}}}(z_{i+1})&\geq &v(z_1)-\ve/8,
\text{ and }\\
\label{eqn:16}\;\;\;\;\;\;-E\frac1n\sum_{i=1}^n1_{\{s_i=M\}}&\geq & \frac{-9}{n\ve \lambda(M)}\;\geq\; -\ve/8 \hspace{1.8cm} \forall n\geq \frac{72}{\ve^2 \lambda(M)}.
\end{eqnarray}
\end{lem}

Before proving the lemma, we show that the lemma along with inequality (\ref{eqn:preparetouniform}) shows that $\s$  satisfies inequality (\ref{ine:uniforme}). Indeed, summing inequalities
(\ref{eqn:preparetouniform}), (\ref{eqn:15}), and (\ref{eqn:16}), and cancelling terms that appear in both sides of the sum of the inequalities, we have that
\[E\frac1n\sum_{i=1}^nx_i \geq v(z_1)-\frac{9\ve}{16}-\frac{\ve}{8}-\frac{\ve}{8}>v(z_1)-\ve \hspace{2cm} \forall n\geq \frac{72}{\ve^2 \lambda(M)},\]
which proves that $\s$ satisfies inequality (\ref{ine:uniforme}) with $n_\ve= \frac{72}{\ve^2 \lambda(M)}$.

\smallskip
Now we turn to the proof of Lemma \ref{lem:3}.
\begin{proof}
Define $Y_i=v_{_{\lambda_i}}(z_i)-\frac{1}{\ln s_i}$. Recall that we write $E$ for $E_{\s,\tau}$ for short.

In the following chain of an equality and inequalities,
equality (\ref{ineq:Ytovs}) follows from the definition of $Y_i$; inequality (\ref{ineq:tosdifferences}) follows by adding to the right hand side of equality (\ref{ineq:Ytovs}) inequality (\ref{ineq:vlambdachange}); inequality (\ref{ineq:tolambdas}) follows from inequality (\ref{ineq:fromlnsdifferencetosdifferences}); inequality (\ref{ineq:tolambdasaddition}) follows from the inequality $E(|s_{i+1}-s_i|\mid \mcF_i)\leq 2$;
inequality (\ref{ineq:tolambdaxv}) follows from the definition of the conditional distribution of $s_{i+1}$ given $(s_i, x_i, z_{i+1})$; and inequality (\ref{ineq:usingbasicineq}) follows from inequality (\ref{eqn:1}).

\begin{eqnarray}\nonumber  & &E(Y_{i+1}-Y_i\mid \mcF_i)\\
\label{ineq:Ytovs}&= &E(v_{_{\lambda_{i+1}}}(z_{i+1})-v_{_{\lambda_i}}(z_i)+\frac{1}{\ln s_i}-\frac{1}{\ln s_{i+1}}\mid \mcF_i)\\
\label{ineq:tosdifferences}&\geq & E(v_{_{\lambda_{i}}}(z_{i+1})-v_{_{\lambda_i}}(z_i)+\frac{1}{\ln s_i}-\frac{1}{\ln s_{i+1}}\mid \mcF_i)-\ve\lambda_i/16\\
\label{ineq:tolambdas}     &\geq & E(v_{_{\lambda_{i}}}(z_{i+1})-v_{_{\lambda_i}}(z_i)+\lambda_i(s_{i+1}-s_i-\ve|s_{i+1}-s_i|/8)\mid \mcF_i)\\
\nonumber & & -\ve\lambda_i/16\\
\label{ineq:tolambdasaddition}
&\geq & E(v_{_{\lambda_{i}}}(z_{i+1})-v_{_{\lambda_i}}(z_i)+\lambda_i(s_{i+1}-s_i)\mid \mcF_i)-5\ve\lambda_i/16\\
\label{ineq:tolambdaxv}    &\geq & E(v_{_{\lambda_{i}}}(z_{i+1})-v_{_{\lambda_i}}(z_i)+\lambda_i(x_i-v_{_{\lambda_i}}(z_{i+1}))\mid \mcF_i)+3\ve\lambda_i/16\\
\label{ineq:usingbasicineq}&\geq & 3\ve\lambda_i/16\geq \ve \lambda_i/8~.
\end{eqnarray}

By taking expectation we deduce that for every $j\geq 1$, we have $E Y_{j+1}-EY_j\geq 0$. Summing these inequalities over $j=1,\ldots,i$, we deduce that $EY_{i+1}\geq Y_1$.
As $v_{_{\lambda_{i+1}}}(z_{i+1})\geq Y_{i+1}$, which follow from the definition of $Y_i$,  and $Y_1\geq v(z_1)-\ve/8$, which follow from inequality (\ref{eqn:vlambdav}), we have, $E\,v_{_{\lambda_{i+1}}}(z_{i+1})\geq v(z_1)-\ve/8$ $\forall i\geq 1$, and hence inequality (\ref{eqn:15}) follows.

The above chain of inequalities shows that
\[E(Y_{i+1}-Y_i\mid \mcF_i)\geq \ve \lambda_i/8, \text{ and hence } EY_{i+1}-EY_i\geq E(\ve \lambda_i/8).\]
Summing these inequalities over $i=1,\ldots,n$ and using the inequalities $1 \geq Y_i$ and $Y_1\geq v(z_1)-\ve/8\geq -\ve/8$, we have
\[1\geq EY_{n+1}\geq Y_1+E\sum_{i=1}^n\ve \lambda_i/8\geq -\ve/8+E\sum_{i=1}^n\ve \lambda_i/8.\]
Therefore,
\begin{equation}\label{eqn:25}
9\geq E\sum_{i=1}^n\ve \lambda_i\geq \ve \lambda(M)E\sum_{i=1}^{n}1_{\{s_i=M\}}.
\end{equation}
From inequality (\ref{eqn:25}), we deduce that \[E\sum_{i=1}^{n}1_{\{s_i=M\}}\leq \frac{9}{\ve \lambda (M)}.\] Dividing by $n$, we obtain
\[E\frac1n\sum_{i=1}^{n}1_{\{s_i=M\}}\leq \frac{9}{n\ve \lambda(M)}\leq \frac{\ve}{8} \hspace{1cm} \forall n\geq \frac{72}{\ve^2\lambda(M)},\]
which establishes inequality (\ref{eqn:16}).
\end{proof}

