\section{The Big Match with a clock and a finite public memory}
Our result about the limitations of bounded public memory is shown for the Big Match, the influential example of a stochastic game introduced by Gillette~\cite{gil57} we described in the introduction. Recall that this game has a single nonabsorbing state, in which each player has two actions.

The two actions of player 1 are labeled $A$ (the absorbing action) and $C$ (the continuing and safe action). The two actions of player 2 are labeled 0 for the action with $r(C,0)=1$ (and thus $r(A,0)=0^*$, denoting that the game transitions to an absorbing state with payoff~0) and $1$ for the action with $r(C,1)=0$ (and thus $r(A,1)=1^*$, denoting that the game transitions to an absorbing state with payoff~1).

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

For a strategy pair $\s$ of player 1 and $\tau$ of player 2, let $\gamma_n(\s,\tau)$ denote the expected average payoffs to Player 1 over the first $n$ stages, under the the distribution induced by $\s$ and $\tau$:
\[\gamma_n(\s,\tau):=E_{\s,\tau}\frac1n\sum_{t=1}^nr_t.\]

\begin{thm}\label{thm:limsupEworthless}
For every positive integer $M$, memory process $(m_t)_{t=1}^\infty$ in ${\mathcal M}_M$, $\delta>0$, and an $(m_t)$-based strategy $\s$ of player 1, there is a strategy $\tau$ of player 2, such that
\begin{equation}\label{eqn:limsupEworthless}\limsup_{n\to\infty}\gamma_n(\s,\tau)\leq \delta.
\end{equation}
Moreover, such a strategy $\tau$ can be chosen as a mixture of finitely many, not necessarily distinct, pure $(m_t)$-based strategies, each selected with equal probability.
\end{thm}

\begin{corollary}\label{cor:liminfEworthless}For every positive integer $M$, memory process $(m_t)_{t=1}^\infty$ in ${\mathcal M}_M$, $\delta>0$, and an $(m_t)$-based strategy $\s$ of player 1, there is a pure $(m_t)$-based strategy $\tau$ of player 2, such that
\begin{equation}\label{eqn:liminfEworthless} \liminf_{n\to\infty}\gamma_n(\s,\tau)\leq \delta.
\end{equation}
\end{corollary}
\begin{proof}[Proof of Corollary \ref{cor:liminfEworthless}]
Let $\tau$ be the uniform mixture of the finitely many pure $(m_t)$-based strategies $\tau^i$, $i=1,\ldots,k$, of player 2 such that (\ref{eqn:limsupEworthless}) holds.
Then, $\frac1k\sum_{i=1}^k\gamma_n(\s,\tau^i)=\gamma_n(\s,\tau)$. As (\ref{eqn:limsupEworthless}) holds and
\[\frac1k\sum_{i=1}^k\liminf_{n\to\infty} \gamma_n(\s,\tau^i)\leq \liminf_{n\to\infty}\frac1k\sum_{i=1}^k \gamma_n(\s,\tau^i)\leq\limsup_{n\to\infty} \gamma_n(\s,\tau),\]
there is $i$ such that $\liminf_{n\to\infty}\gamma_n(\s,\tau^i)\leq \delta$.
\end{proof}

The proof of Theorem \ref{thm:limsupEworthless} is obtained by defining a sequence of (not necessarily distinct) $(m_t)$-based strategies $\tau^i$ of player 2,
such that (\ref{eqn:limsupEworthless}) holds for any strategy $\tau$ that is mixture of sufficiently many of the strategies $\tau^i$. The next lemma states the properties of the sequence of $(m_t)$-based strategies $\tau^i$ of player 2 that are used in the proof of (\ref{eqn:limsupEworthless}).

\begin{lem}\label{lem:Xstrategies}For every positive integer $M$ and ever memory process $(m_t)_{t=1}^\infty$ in ${\mathcal M}_M$, $\delta>0$,  and an $(m_t)$-based strategy $\s$ of player 1, there is a sequence $\tau^i$, $i\in \mathbb{N}$, of  pure $(m_t)$-based strategies of player 2 and a sequence $n_i$ of positive integers, such that
\begin{equation}\label{eqn:fewbadtauinew}
\forall t\geq n_i,\;\;\; \sum_{i=1}^\infty1_{\{r^i_t\geq \delta\}}1_{\{t\geq n_i\}}\leq M+1, \;\;\;\mbox{ where }\;r^i_t:=E_{\s,\tau^i}r_t.
\end{equation}
\end{lem}

\begin{proof}[Proof of Lemma \ref{lem:Xstrategies}]
Let $(m_t)_{t=1}^\infty$ be a memory process in ${\mathcal M}_M$, $M$ a positive integer, and let $\s$ be an $(m_t)$-based strategy of player 1.
We use the symbols $[M]$ %and $X$ also
to denote the sets $\{1,\ldots,M\}$. % and $\{1,\ldots X\}$ respectively.
A pure $(m_t)$-based strategy $\tau$ of player 2 is a function from $\mathbb{N}\times [M]$ to $\{0,1\}$. We identify the pure $(m_t)$-based strategy $\tau$ with the set $1_\tau$, which consists of all pairs $(t,m)$ such that $\tau(t,m)=1$. That is,
\[1_\tau:=\{(t,m): t\geq 1, 1\leq m\leq M, \mbox{ and } \tau(t,m)=1\}.\]

{\bf The properties of the strategies $\tau^i$.}

The set of strategies $\tau^i$, $1\leq i$, will satisfy the following properties.

\begin{equation}\label{property:monotonicity}
\tau^i(t,m)\leq \tau^{i+1}(t,m) \;\;\;\forall (t,m)\in \mathbb{N}\times [M],
\end{equation}
and
$\forall i\in \mathbb{N} \;\;\exists n_i \mbox{ s.t. } \forall t\geq n_i$,
\begin{equation}\label{property:existenceofdesiredm}
% E_{\s,\tau^i}r_t=
 r^i_t\geq \delta \implies \exists m \mbox{ s.t. } 0=\tau^i(t,m)<\tau^{i+1}(t,m)=1.
\end{equation}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

{\bf The definition of $\tau^i$.}
We define $\tau^i$ (as a function of the strategy $\s\in \mcM_M$) by induction on $i$. The definition will imply that
\begin{equation}\label{eqn:sumsigmataui}\sum_{(t,m)\in \tau^i}\s(t,m)[A]<\delta/3.
\end{equation}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Set $T_*:=\inf \{t: i_t=A\}$, and if no absorbing action is played (i.e., if $\{t: i_t=A\}$ is the empty set), we set $T_*=\infty$.
$T_*$ is a stopping time whose distribution depends on the strategies  of player 1 and player 2. The event that the play of the game is absorbed at $1^*$, respectively at $0^*$, is denote by $1^*$, respectively $0^*$.

The expectation w.r.t. the probability $P_{\s,\tau}$ is denoted by $E_{\s,\tau}$.

Given a probability $P$ on plays, the $P$-probability of the event $1^*$, respectively $0^*$, is denoted by $P(1^*)$, respectively $P(0^*)$.
That is, ${P}(1^*):={P}(T_*=t<\infty, i_t=A, j_t={1})$ and ${P}(0^*)={P}(T_*=t<\infty, i_{t}=A, j_{t}=0)$.

Let ${P}(t,m)={P}(T_*\geq t \mbox{ and } m_t=m)$, and let $P_i$ denote the probability distribution induced by $\s$ and $\tau^i$, i.e., $P_i:=P_{\s,\tau^i}$.

Note that $P_i(1^*)=\sum_{(t,m)\in \tau^i}P_i(t,m)\s(t,m)[A]\leq \sum_{(t,m)\in \tau^i}\s(t,m)[A]$. Hence, if $\tau^i$ satisfies property (\ref{eqn:sumsigmataui}), then $P_i(1^*)<\delta/3$.

{\bf Definition of $\tau^1$.}
\[\tau^1(t,m)=0\;\; \forall (t,m).\]
Note that $\tau^1$ satisfies property (\ref{eqn:sumsigmataui}).

{\bf Inductive definition of $\tau^{i+1}$.}
Assume that $\tau^i$ is an $(m_t)$-based strategy (of player 2) that satisfies property (\ref{eqn:sumsigmataui}).
Set ${P}(1^*_{<t}):={P}(T_*=s<t, i_s=A, j_s=1)$ and ${P}(0^*_{>t}):={P}(T_*=s>t, i_s=A, j_s=0)$. Note that
\begin{eqnarray*}r^i_t&=&P_i(1^*_{\leq t})+\sum_{m: (t,m)\notin \tau^i} P_i (t,m)\sigma(t,m)[C]\\
&\leq &P_i(1^*_{\leq t})+\sum_{m: (t,m)\notin \tau^i} P_i (t,m)\\
&<&\delta/3+\sum_{m: (t,m)\notin \tau^i} P_i (t,m)(1_{\{P_i (t,m)\geq \delta/(3M)\}}+1_{\{P_i (t,m)< \delta/(3M)\}})\\ %1_{\tau^i(t,m)=0}
&<&2\delta/3+\sum_{m: (t,m)\notin \tau^i} 1_{\{P_i (t,m)\geq \delta/(3M)\}}. %1_{\tau^i(t,m)=0}
\end{eqnarray*}
The first inequality follows from the inequality $\sigma(t,m)[C]\leq 1$.
The second inequality follows from the inequality $P_i(1^*_{<t})<\delta/3$ and the equality $1=1_{\{P_i (t,m)\geq \delta/(3M)\}}+1_{\{P_i (t,m)< \delta/(3M)\}}$. Finally, the third inequality follows from the inequalities $\sum_m P_i(t,m)1_{\{P_i(t,m)<\delta/(3M)\}}< \sum_m \delta/(3M)=M\delta/(3M)=\delta/3$ and
$P_i(t,m)1_{\{P_i(t,m)\geq \delta/(3M)\}}\leq 1_{\{P_i(t,m)\geq \delta/(3M)\}}$.

Therefore,
\[r^i_t\geq \delta \implies \sum_{m: (t,m)\notin \tau^i} 1_{\{P_i (t,m)\geq \delta/(3M)\}}>\delta/3.\]
Therefore, for every $t$ such that $r^i_t\geq \delta$, there is $m(t)\in M$ such that $(t,m(t))\notin \tau^i$ and $P_i(t,m(t))\geq \delta/(3M)$.

Set $T_{n,\delta}:=\{(t,m(t)): t\geq n \mbox{ and } r^i_t\geq \delta\}$.

\begin{eqnarray*}\sum_{(t,m(t))\in T_{n,\delta}}\frac{\delta}{3M}\,\s(t,m(t))[A]&\leq& \sum_{(t,m(t))\in T_{n,\delta}}P_i(t,m(t))\s(t,m(t))[A]\\
&\leq & P_i(0^*_{>n})\to_{n\to\infty} 0.
\end{eqnarray*}
Therefore, as $\sum_{(t,m)\in \tau^i}\s(t,m)[A]<\delta/3$, there exists $n_i$ such that \[\sum_{(t,m)\in \tau^i}\s(t,m)[A]+\sum_{(t,m(t))\in T_{n_i,\delta}}\s(t,m(t))[A]<\delta/3.\]

Let $\tau^{i+1}=\tau^i\cup T_{n_i,\delta}$. The pure $(m_t)$-based strategy $\tau^{i+1}$ satisfies condition (\ref{eqn:sumsigmataui}). Note that $T_{n_i,\delta}$ may be the empty set, and in this case $\tau^{i+1}=\tau^i$.

Let $X\subset \mathbb{N}$ with $\infty>|X|>(M+1)/\delta$ and set $t_X=\max_{j\leq i\in X} n_j$. Fix $t>t_X$. For all $i,j\in X$ with $i<j$ and $r^i_t\geq \delta$, there is $m\in M$ with $(m,t)\in \tau^{i+1}\setminus \tau^i\subseteq \tau^j\setminus \tau^i$. As the number of memories is $M$, there are at most $M+1$ elements $i\in X$ with $r^i_t\geq \delta$.
This completes the proof of Lemma \ref{lem:Xstrategies}.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:limsupEworthless}]
Fix  a positive integer $M$, a memory process $(m_t)_{t=1}^\infty$ in ${\mathcal M}_M$, $\delta>0$, and an $(m_t)$-based strategy $\s$ of player 1.

Let $\tau^i$, $1\leq i$, be a sequence of pure $(m_t)$-based strategies of player 2, such that for any finite set $X\subset \mathbb{N}$, there is a positive integer $t_\delta$, such that
\begin{equation}\label{eqn:fewbadtaui}
 \forall t\geq t_\delta, \;\;\;|\{i\in X: E_{\s,\tau^i}r_t:=r^i_t>\delta\}|=\sum_{i=1}^\infty1_{\{r^i_t\geq \delta\}}\leq M+1.
\end{equation}
The existence of the such a sequence of strategies $\tau^i$,  $1\leq i<\infty$, that satisfy (\ref{eqn:fewbadtaui}) is guaranteed by Lemma \ref{lem:Xstrategies}.

Fix a finite set $X\subset \mathbb{N}$ with $|X|>(M+1)/\delta$. Let $\tau$ be the uniform mixture of the strategies $\tau^i$, $i\in X$. For every $t$, $r^i_t \leq 1_{\{r^i_t\geq \delta\}}+\delta$, and therefore,
\[\forall t\geq t_\delta, \;\;\;E_{s,\tau}r_t=\frac{1}{|X|}\sum_{i\in X} r^i_t\leq \frac{1}{|X|} \sum_{i\in X}(1_{\{r^i_t\geq \delta\}}+\delta)\leq \frac{M+1}{|X|}+\delta<2\delta.\]
Hence, if $n $ is sufficiently large so that $ t_\delta/n\leq \delta$, then
\[\gamma_n(\s,\tau)=E_{\s,\tau}\frac1n\sum_{t=1}^nr_t\leq \frac{t_\delta}{n}+2\delta<3\delta,\]
which completes the proof of the theorem.
\end{proof}
