\section{CTSR nonlinear functions}
\label{funciones}

The CTSR nonlinear functions are defined in equations \eqref{eqfnonlinear}-\eqref{eqhnonlinear}. The functions $f(\mathbf{x,u})$ are defined in the following way, according to the case study:

\subsection*{\textbf{Case 1: 1 reactor}} Let $f(\mathbf{x,u}) = [f_{1} \ f_{2} \ f_{3} \ f_{4} \ f_{5}]^{T} \in \mathbb{R}^{5\times 1}$ with
\begin{align}
f_{1} &= \frac{F_0 C_{A,0} - F_{i} C_{A,1} - k_i V C_{A,1} C_{B,1}}{V}, \\
f_{2} &= \frac{F_0 C_{B,0} - F_{i} C_{B,1} - k_i V C_{A,1} C_{B,1}}{V}, \\
f_{3} &= \frac{k_i V C_{A,1} C_{B,1} - F_{i} C_{C,1}}{V}, \\
f_{4} &= \frac{F_{i}}{V} (T_{\text{in},A} \!-\! T_1) - \frac{\Delta H}{\rho c_p} k_i C_{A,1} C_{B,1} + \frac{UA}{\rho c_p V} (T_{j,1} - T_1), \\
f_{5} &= \frac{F_j}{V_j} (T_{j,\text{in}} - T_{j,1}) - \frac{UA}{\rho_j c_{p_j} V_j} (T_{j,1} - T_1).
\end{align}

\subsection*{\textbf{Case 2: 2 reactors}} Let $f(\mathbf{x,u}) = [f_{1} \ f_{2} \ f_{3} \ \ldots \ f_{10}]^{T} \in \mathbb{R}^{10\times 1}$ with
\begin{align}
f_{6} &= \frac{F_{i} C_{A,1} - v C_{A,2} - k_i V C_{A,2} C_{B,2}}{V}, \\
f_{7} &= \frac{F_{i} C_{B,1} - v C_{B,2} - k_i V C_{A2} C_{B,2}}{V}, \\
f_{8} &= \frac{k_i V C_{A,2} C_{B,2} - F_{i} C_{C,2}}{V}, \\
f_{9} &= \frac{F_{i}}{V} (T_1 - T_2) - \frac{\Delta H}{\rho c_p} k_i C_{A,2} C_{B,2} + \frac{UA}{\rho c_p V} (T_{j,2} - T_2), \\
f_{10} &= \frac{F_j}{V_j} (T_{j,\text{in}} - T_{j,2}) - \frac{UA}{\rho_j c_{p_j} V_j} (T_{j,2} - T_2).
\end{align}

\subsection*{\textbf{Case 3: 3 reactors}} Let $f(\mathbf{x,u}) = [f_{1} \ f_{2} \ f_{3} \ \ldots \ f_{15}]^{T} \in \mathbb{R}^{15\times 1}$ with
\begin{align}
f_{11} &= \frac{F_{i} C_{A,2} - F_{i} C_{A,3} - k_i V C_{A,3} C_{B,3}}{V}, \\
f_{12} &= \frac{F_{i} C_{B,2} - F_{i} C_{B,3} - k_i V C_{A,3} C_{B,3}}{V}, \\
f_{13} &= \frac{k_i V C_{A,3} C_{B,3} - F_{i} C_{C,3}}{V}, \\
f_{14} &= \frac{F_{i}}{V} (T_2 - T_3) - \frac{\Delta H}{\rho c_p} k_i C_{A,3} C_{B,3} + \frac{UA}{\rho c_p V} (T_{j,3} - T_3), \\
f_{15} &= \frac{F_j}{V_j} (T_{j,\text{in}} - T_{j,3}) - \frac{UA}{\rho_j c_{p_j} V_j} (T_{j,3} - T_3).
\end{align}

\section{Extended Luenberger observer (ELO)}
\label{ELO}
The Luenberger observer estimates the state using the nonlinear dynamics of the system and a correction term based on the observation error:
\begin{equation}
\label{eq8}
\mathbf{\hat{\mathbf{x}}}_{k+1}=f(\mathbf{\hat{\mathbf{x}}}_{k},\mathbf{u}_{k}) + \mathbf{L} (\mathbf{y}_{k} - \hat{\mathbf{y}}_{k}),
\end{equation}
where $\mathbf{L}$ is the Luenberger observer gain, $\hat{\mathbf{y}}_{k} $ is the estimated output vector, and $\mathbf{y}_{k}$ is the measured output vector defined in Table \ref{tab_observability}. The Luenberger observer can be seen as a deterministic version of the Kalman filter when noise statistics are not considered.

\section{Extended Kalman Filter (EKF)}
\label{EKF}

The EKF operates recursively and constantly refines its estimate based on incoming measurements. It uses a local linearization of the nonlinear equations around the current operating point. It consists of two main stages: the prediction stage and the update stage.
\begin{enumerate}
\item Prediction Stage
\begin{align}\label{eq8b}
\hat{\mathbf{x}}_{k \mid k-1} &= f\left( \hat{\mathbf{x}}_{k-1 \mid k-1}, \mathbf{u}_{k-1} \right), \\
\hat{\mathbf{P}}_{k \mid k-1} &= \mathbf{F}_{k-1} \hat{\mathbf{P}}_{k-1 \mid k-1} \mathbf{F}_{k-1}^{T} + \mathbf{Q}.
\end{align}

\item Update Stage 
\begin{align}\label{eq8c}
\mathbf{K}_{k} &= \hat{\mathbf{P}}_{k \mid k-1} \mathbf{H}_{k}^{T} \left( \mathbf{H}_{k} \hat{\mathbf{P}}_{k \mid k-1} \mathbf{H}_{k}^{T} + \mathbf{R} \right)^{-1}, \\
\hat{\mathbf{x}}_{k \mid k} &= \hat{\mathbf{x}}_{k \mid k-1} + \mathbf{K}_{k} \left( \mathbf{y}_{k} - h(\hat{\mathbf{x}}_{k \mid k-1}) \right), \\
\hat{\mathbf{P}}_{k \mid k} &= \hat{\mathbf{P}}_{k \mid k-1} - \mathbf{K}_{k} \mathbf{H}_{k} \hat{\mathbf{P}}_{k \mid k-1},
\end{align}
\end{enumerate}
where
\begin{align}
\mathbf{F}_{k} = \left. \frac{\partial f(\mathbf{x}_k, \mathbf{u}_{k})}{\partial \mathbf{x}_k} \right|_{\mathbf{x}_k = \hat{\mathbf{x}}_{k\mid k}}, \quad
\mathbf{H}_{k} = \left. \frac{\partial h(\mathbf{x}_k)}{\partial \mathbf{x}_k} \right|_{\mathbf{x}_k = \hat{\mathbf{x}}_{k \mid k-1}},
\end{align}

\section{Unscented Kalman Filter (UKF)}
\label{UKF}

The UKF, for its part, uses the Unscented Transformation method for estimation. It generates a set of sigma points around the current estimate and propagates them through the nonlinear functions to more accurately capture system statistics. This provides a more accurate approximation for nonlinear systems without requiring derivatives. The general framework for UKF is based on the unscented transformation, in which a random variable $\mathbf{x} \sim \mathcal{N}(\mathbf{x}; \mathbf{m}, \bm{\Gamma})$, is transformed through a nonlinear function $\mathbf{y} = g(\mathbf{x})$. The basic idea is to choose a fixed number of sigma points that capture the mean and covariance of the original distribution of $\mathbf{x}$. The sigma points can be calculated using:
\begin{align}
\hat{\bm{\mathcal{X}}}_{i}&=\mathbf{m}, \ i=0 , \\  
\hat{\bm{\mathcal{X}}}_{i}&=\mathbf{m} \! + \! \sqrt{(n \! + \!\lambda)} \left [ \!\sqrt{\bm{\Gamma}} \right ]_{i}, \ i=1,\dots,L , \\ 
\hat{\bm{\mathcal{X}}}_{i}&=\mathbf{m} \! - \! \sqrt{(n \! + \!\lambda)} \left [ \!\sqrt{\bm{\Gamma}} \right ]_{i}, \ i=L+1,\dots,2L  ,
\end{align}
where $L$ is the length of $\mathbf{m}$. The scaling parameter $\lambda=\alpha ^{2}(L+\kappa)-L$ depends on the constant $\alpha$ and $\kappa$. $\alpha$ determines the spread of the sigma points around $\mathbf{m}$, and is usually set to $1\times 10^{-4}\leq \alpha \leq 1$. The constant $\kappa$ is usually set to 0. $ \left [ \sqrt{\bm{\Gamma}} \right ]_{i}$ is the $i_{th}$ column of the matrix $\sqrt{\bm{\Gamma}}$. For implementation, the parameters $\alpha$, $\beta$, and $\kappa$ are defined in Table \ref{tab_paramObserver}.

\begin{enumerate}
\item Prediction Stage: Form of the sigma points:
\begin{align}
\hat{\bm{\mathcal{X}}}_{i,k-1}&\!=\! \hat{\mathbf{x}}_{k-1}, \ i=0,  \\  
\hat{\bm{\mathcal{X}}}_{i,k-1}&\!=\! \hat{\mathbf{x}}_{k-1} \! + \! \sqrt{(n \! + \!\lambda)}  \left [ \!\!\sqrt{\mathbf{P}_{k-1}} \right ]_{i}, \ i \! = \! 1,\dots,L , \\ 
\hat{\bm{\mathcal{X}}}_{i,k-1}&\!=\! \hat{\mathbf{x}}_{k-1} \! - \! \sqrt{(n \! + \!\lambda)} \left [ \!\!\sqrt{\mathbf{P}_{k-1}} \right ]_{i}, \ i \!= \! L+1,\dots,2L  .
\end{align}

Propagate the sigma points through the dynamic model and $\hat{\mathbf{P}}_{k \mid k-1}$:
\begin{align}
\hat{\bm{\mathcal{X}}}_{i,k \mid k-1} & \! = \! f \left (\hat{\bm{\mathcal{X}}}_{i,k-1},\mathbf{u}_{k-1}  \right ), \ i=0,1,...,2L.
\end{align}

Compute the mean $\hat{\mathbf{x}}_{k \mid k-1}$ and the predicted covariance: 
\begin{align}
\hat{\mathbf{x}}_{k \mid k-1} & \! = \! \sum_{i=1}^{2L} W_{i}^{(m)}\hat{\bm{\mathcal{X}}}_{i,k \mid k-1}, \\
\hat{\mathbf{P}}_{k \mid k-1} & \! = \! \sum_{i=1}^{2L} W_{i}^{(c)}\left [ \hat{\bm{\mathcal{X}}}_{i,k \mid k-1} \!-\! \hat{\mathbf{x}}_{k \mid k-1} \right ]\left [ \hat{\bm{\mathcal{X}}}_{i,k \mid k-1} \!-\! \hat{\mathbf{x}}_{k \mid k-1} \right ]^{T} \!\!+\! \mathbf{Q} ,
\end{align}
where 
\begin{align}
W_{i}^{(c)} &= W_{i}^{(m)} = \frac{1}{\left [ 2(L+\lambda ) \right ]}, \ i=1,...2L,\\
W_{0}^{(c)} &=  \frac{\lambda}{(L+\lambda )}+(1-\alpha ^{2}+\beta ) , \ i=0, \\
W_{0}^{(m)} &=  \frac{\lambda}{(L+\lambda )} , \ i=0,
\end{align}

\item Update: Form of the sigma points:
\begin{align}
\hat{\bm{\mathcal{X}}}_{i,k }&=\hat{\mathbf{x}}_{k \mid k-1}, \ i=0,  \\  
\hat{\bm{\mathcal{X}}}_{i,k }&=\hat{\mathbf{x}}_{k \mid k-1} \! + \! \sqrt{(n \! + \!\lambda)}\left [ \!\!\sqrt{\mathbf{P}_{k \mid k-1}} \right ]_{i}, \ i=1,\dots,L  ,\\ 
\hat{\bm{\mathcal{X}}}_{i,k }&=\hat{\mathbf{x}}_{k \mid k-1} \! - \! \sqrt{(n \! + \!\lambda)}\left [ \!\!\sqrt{\mathbf{P}_{k \mid k-1}} \right ]_{i}, \ i=L+1,\dots,2L .
\end{align}

Propagate sigma points through the measurement model:
\begin{align}
\mathbf{z}_{i,k \mid k}&= h(\hat{\bm{\mathcal{X}}}_{i,k}), \  i=0,1,...,2L.
\end{align}

Compute the predicted mean $\hat{\mathbf{z}}_{k \mid k}$, the predicted covariance of the measurement $\mathbf{P}_{\mathbf{z}\mathbf{z}}$, and the cross-covariance of the state and the measurement $\mathbf{P}_{\mathbf{x}\mathbf{z}}$:
\begin{align}
\hat{\mathbf{z}}_{k \mid k}&= \sum_{i=0}^{2L}W_{i}^{(m)}\mathbf{z}_{i,k \mid k}, \\
\mathbf{P}_{\mathbf{z}\mathbf{z}} & \! = \! \sum_{i=0}^{2L}W_{i}^{(c)}\left [ \mathbf{z}_{i,k \mid k} \!-\! \hat{\mathbf{z}}_{k \mid k} \right ]\!\left [ \mathbf{z}_{i,k \mid k} \!-\! \hat{\mathbf{z}}_{k \mid k} \right ]^{T} \!\!+\! \mathbf{R}, \\ 
\mathbf{P}_{\mathbf{x}\mathbf{z}} & \! = \! \sum_{i=0}^{2L}W_{i}^{(c)} \!\left [ \hat{\bm{\mathcal{X}}}_{i,k \mid k} - \hat{\mathbf{x}}_{k \mid k} \right ] \left [ \mathbf{z}_{i,k \mid k} - \hat{\mathbf{z}}_{k \mid k} \right ]^{T}.
\end{align}

Compute the filter gain $\mathbf{K}_{k}$, the filtered state mean $\hat{\mathbf{x}}_{k \mid k}$ and the covariance $\hat{\mathbf{P}}_{k \mid k}$:
\begin{align}
\mathbf{K}_{k} & \! = \! \mathbf{P}_{\mathbf{x}\mathbf{z}}\mathbf{P}_{\mathbf{z}\mathbf{z}}^{-1},\\ 
\hat{\mathbf{x}}_{k \mid k}& \! = \! \hat{\mathbf{x}}_{k \mid k-1} +  \mathbf{K}_{k}\left ( \mathbf{y}_{k}  - \hat{\mathbf{z}}_{k \mid k}\right ), \\ 
\hat{\mathbf{P}}_{k \mid k}& \! = \! \hat{\mathbf{P}}_{k \mid k-1} -  \mathbf{K}_{k}\mathbf{P}_{\mathbf{z}\mathbf{z}}\mathbf{K}_{k}^{T}.
\end{align}
\end{enumerate}

\section{Quadrature Kalman Filter (QKF)}
\label{CKF}

The Quadrature Kalman Filter (QKF) uses the third-order quadrature principle to approximate integrals over Gaussian distributions (Gauss–Hermite numerical integration rule). This is achieved by evaluating the nonlinear functions at cubature points, specifically distributed, to capture the properties of the distributions. The QKF equations are divided into prediction and update stages, similar to other nonlinear Kalman filters such as the EKF and UKF. But unlike the UKF, where the sigma points are generated, the QKF presents an additional stage where the cubature points are generated and transformed. The number of dimensions $\mathcal{N}$, and the weights $\omega$ are defined in Table \ref{tab_paramObserver}.

\begin{enumerate} %[leftmargin=*] %[wide, labelwidth=!, labelindent=0pt]
\item Prediction Stage

For a Gaussian distribution in $n$-dimensions $\mathcal{N}\left ( \hat{\mathbf{x}}_{k-1},\hat{\mathbf{P}}_{k-1} \right )$ with the associated weights $\omega _{l=1}^{n}$ the cubature points are:
\begin{equation}  
\mathcal{\bm{\mathcal{X}}}_{i,k-1}=\hat{\mathbf{x}}_{k-1}+\sqrt{n\hat{\mathbf{P}}_{k-1}}\xi_{i}, \ i =1,...,2n,
\end{equation}
where $\sqrt{n\hat{\mathbf{P}}_{k-1}}$ is the weighted square root of the covariance matrix scaled by $n$, and $\xi_{i}$ are Gauss–Hermite quadrature points with weights $\omega _{l}$.

Propagate the cubature points through the dynamic model:
\begin{equation}
\bm{\mathcal{X}}_{i,k\mid k-1}^{*}=f(\bm{\mathcal{X}}_{i,k-1},\mathbf{u}_{k-1}) \ i =1,...,n,
\end{equation}
where $f(\mathcal{\bm{\mathcal{X}}}_{i,k-1},\mathbf{u}_{k-1})$ is the nonlinear function that describes the dynamics of the system.

Compute the mean and the predicted covariance:
\begin{align}
\hat{\mathbf{x}}_{k \mid k-1} & \! = \! \dfrac{1}{2n} \sum_{i=1}^{2n} \bm{\mathcal{X}}_{i,k \mid k-1}^{*}. \\ 
\hat{\mathbf{P}}_{k \mid k-1} & \! = \! \dfrac{1}{2n}\sum_{i=1}^{2n}\left [ \bm{\mathcal{X}}_{i,k \mid k-1}^{*} \!-\! \hat{\mathbf{x}}_{k \mid k-1} \right ]\left [ \bm{\mathcal{X}}_{i,k \mid k-1 }^{*} \!-\! \hat{\mathbf{x}}_{k \mid k-1} \right ]^{T} \!+\! \mathbf{Q}.
\end{align}
\item Update

Form the cubature points:
\begin{align}
\bm{\mathcal{X}}_{i,k}^{*} & = \hat{\mathbf{x}}_{k \mid k-1} + \sqrt{n\hat{\mathbf{P}}_{k \mid k-1}}\xi_{i}, \ i =1,...,2n.
\end{align}

Propagate sigma points through the measurement model:
\begin{align}
\mathbf{z}_{i,k \mid k} & = h(\bm{\mathcal{X}}_{i,k}^{*}) \ i=1,...,2n.
\end{align}

Compute the predicted mean, the predicted covariance of the
measurement, and the cross-covariance of the state and the measurement
\begin{align}
\hat{\mathbf{z}}_{k \mid k} &= \frac{1}{2n}\sum_{i=1}^{2n}\mathbf{z}_{i,k \mid k}, \\ 
\hat{\mathbf{P}}_{\mathbf{z}\mathbf{z}} &= \frac{1}{2n}\sum_{i=1}^{2n}\left [ \mathbf{z}_{i,k \mid k} - \hat{\mathbf{z}}_{k \mid k} \right ]\left [ \mathbf{z}_{i,k \mid k} - \hat{\mathbf{z}}_{k \mid k} \right ]^{T} + \mathbf{R},\\ 
\hat{\mathbf{P}}_{\mathbf{x}\mathbf{z}} &= \frac{1}{2n}\sum_{i=1}^{2n}\left [ \bm{\mathcal{X}}_{i,k \mid k}^{*} -\hat{\mathbf{x}}_{k\mid k} \right ]\left [ \mathbf{z}_{i,k \mid k} - \hat{\mathbf{z}}_{k \mid k} \right ]^{T}.
\end{align}

Compute the filter gain $\mathbf{K}_{k}$, the filtered state mean $\hat{\mathbf{x}}_{k \mid k}$ and the covariance $\hat{\mathbf{P}}_{k \mid k}$:
\begin{align}
\mathbf{K}_{k} &= \mathbf{P}_{\mathbf{x}\mathbf{z}}P_{\mathbf{z}\mathbf{z}}^{-1}, \\
\hat{\mathbf{x}}_{k\mid k}&= \hat{\mathbf{x}}_{k \mid k-1} +  \mathbf{K}_{k}\left ( \mathbf{y}_{k}  - \hat{\mathbf{z}}_{k \mid k}\right ), \\
\hat{\mathbf{P}}_{k\mid k}&= \hat{\mathbf{P}}_{k \mid k-1} -  \mathbf{K}_{k}\mathbf{P}_{\mathbf{z}\mathbf{z}}\mathbf{K}_{k}^{T}.
\end{align}

\end{enumerate}

\section{Particle Filter (PF)}
\label{PF}

A particle filter is a simulation-based estimation method that uses a set of samples or "particles" to approximate the probability distribution of a nonlinear and/or non-Gaussian system. The Particle Filter (PF) shares several similarities with the EKF, UKF, and QKF. Its approach also has key differences, requiring no linearization or sigma points; instead, it uses particle-based simulations. The number of particles $N$ is defined in Table \ref{tab_paramObserver}.

The main steps that describe its operation are presented below:
\begin{enumerate}
\item Particle initialization Stage: Draw $N$ particles $\mathbf{x}_{i,0} \sim p(\hat{\mathbf{x}}_{1})$ and set $w_{i,0}=1/N$ for $i=1,2,…,N$.
\item Draw samples from the importance distributions
\begin{align}
    \mathbf{x}_{i,k} & \sim p(\mathbf{x}_{k}\mid \mathbf{x}_{i,k-1}),  \qquad i=1,…,N .
\end{align}
\item Calculate new weights according to:
\begin{align}
    w_{i,k} \propto p(\mathbf{y}_{k}\mid \mathbf{x}_{i,k}),  \qquad i=1,…,N ,
\end{align}
and normalize them to sum to unity. The state estimation $\hat{\mathbf{x}}{k\mid k}$ and its corresponding estimation error covariance $\mathbf{P}{k\mid k}$ are performed as the weighted average of the particles:
\begin{align}
    \hat{\mathbf{x}}_{k\mid k} &=  \sum_{i=1}^{N} w_{i,k}\mathbf{x}_{i,k},\\
    \mathbf{P}_{k\mid k} &=  \sum_{i=1}^{N} w_{i,k}(\mathbf{x}_{i,k}-\hat{\mathbf{x}}_{k\mid k})(\mathbf{x}_{i,k}-\hat{\mathbf{x}}_{k\mid k})^{T}.
\end{align}

\item Do resampling.

\end{enumerate}
