\[
\underbrace{\begin{bmatrix}
2 & 4 & 3 & 1\\
3 & 1 & 0 & 3\\
4 & 5 & 2 & 2
\end{bmatrix}}_{\text{transport matrix}}
\qquad
\bigl[\texttt{gbs\_cnt}=2,\; \texttt{haps\_cnt}=1\bigr]
\]

