\textit{Good examples (top‑3):}
\begin{itemize}
  \item \textbf{State}: $[2,4,3,1,\,3,1,0,3,\,4,5,2,2,\,2,1]$, \textbf{Action}: \{\texttt{FASTER},\;\texttt{t1}\}, \textbf{Reward}: $+1.05$
  \item \textbf{State}: $[3,4,3,1,\dots]$, \textbf{Action}: \{\texttt{IDLE},\;\texttt{t1}\}, \textbf{Reward}: $+0.92$
