We now have the following {\colb{Locality Condition}} \cite{Gibson2010}, that is used to prove the existence of a \ptas.


\begin{lemma}[\textbf{{Locality Condition} \cite{Gibson2010}}]:
	There exists a planar bipartite graph $G = (\mathcal{L} \cup \mathcal{O}, E)$  such that for every object $X \in \mathcal{R}$, there exists an edge between $L \in \mathcal{L}$ and $O \in \mathcal{O}$ where both $L$ and $O$ are dominators of $X$. (Note that the definition of dominator is essentially different in \cite{Gibson2010}).
	\label{locality_condition_def} 

\end{lemma}


%We first show that how locality condition leads the following lemma. Next we show that how a graph is  constructed that satisfies the locality condition. 


\begin{lemma}[\cite{Gibson2010}] \label{lemma_ptas_dds}
If the set of disks  $\mathcal{L} \cup \mathcal{O}$ satisfies the locality condition then  $|\mathcal{L}| \leq (1 + \epsilon) |\mathcal{O}|$ for $\epsilon = O(\frac{1}{\sqrt{t}})$.
\end{lemma}

\begin{proof}
We first note that the proof is in similar lines to the proof of Theorem \ref{ptas_dis_disks} (also similar to \cite{Chan2012}, \cite{Mustafa2010}, and \cite{Gibson2010}). Further, we adopt the terminologies used in the proof of Theorem \ref{ptas_dis_disks} and Lemma \ref{planar_sepa_lemma}. 

Assume that the set of disks  $\mathcal{L} \cup \mathcal{O}$ satisfies the locality condition.
%given in Lemma \ref{locality_condition_def}.
Further, let $G = (V, E)$ be any planar graph as in the locality condition with $V = \mathcal{O} \cup \mathcal{L}$. Let $r = t /(c_2+c_3)$ (note that $t$ is the local search parameter). We note that $|V_i \cup N(V_i)| \leq c_2 r + c_3 \sqrt{r} \leq t$. Since the \mdds~problem is a minimization problem and $\mathcal{L}$ is local optimum, we note that $|\mathcal{L}_i| \leq |\mathcal{O}_i| + |N(V_i)|$, otherwise an improvement is possible for the local solution $\mathcal{L}$ by replacing the disks in $\mathcal{L}_i$ with disks in $\mathcal{O}_i \cup N(V_i)$. By using the similar arguments in Theorem \ref{ptas_dis_disks}, we can obtain  $|\mathcal{L}| \leq \bigl(1 + O(1/\sqrt{t}) \bigr) |\mathcal{O}|$.\end{proof}

\subsection{Analysis of the algorithm}


In the following, we construct a graph $G = (V, E)$ which satisfies the locality condition given in Lemma \ref{locality_condition_def}.  Our construction of $G$ is inspired by the results in \cite{Madireddy2016}. Partition the set $\mathcal{R}$ into two sets $\mathcal{R}_1$ and $\mathcal{R}_2$ as follows:  
\begin{enumerate}
	\item $\mathcal{R}_1$ is the collection of disks in $\mathcal{R}$ such that for every disk  $D \in \mathcal{R}_1$ there exists  at least one point $p\in \mathcal{P}$ that is  covered by  $D$ and is also covered by  at least one disk in  $\mathcal{L}$ as well as  at least one disk in $\mathcal{O}$. 
	\item $\mathcal{R}_2 = \mathcal{R} \setminus \mathcal{R}_1$. 
\end{enumerate}

For every disk  $X \in \mathcal{L} \cup \mathcal{O}$, we consider a vertex in the graph $G$ at $\mathsf{cen}(X)$. The edge set $E$ is constructed in two phases, i.e., $E = E_1 \cup E_2$. The edge-sets $E_i$ (for $i=1 \text{ and } 2$) ensure that the locality condition is satisfied for the disks in $\mathcal{R}_i$. For a set of points $\{a, x_1, x_2, \ldots, x_k, b\}$, with $k \geq 1$ is an integer, the curve $\mathscr{C}(a, x_1, x_2, \ldots, x_k, b)$ connecting the points $a$ and $b$ is the chain of the segments $\seg(a,x_1), \seg(x_1, x_2), \seg(x_2, x_3), \ldots, \seg(x_{k-1}, x_k), \seg(x_k, b)$ such that no two of $\linebreak$ them  intersect except at the endpoints. 

\subsubsection{Phase I: Construction of the edge set $E_1$}


We first construct the $\mathsf{AWVD}$ (Additive Weighted Voronoi Diagram)  of the disks in $\mathcal{L} \cup \mathcal{O}$ as in Section \ref{ptas_mdis}.  For every disk $L \in \mathcal{L}$ and every disk $O \in \mathcal{O}$, we place an edge in $E_1$ with endpoints  $\mathsf{cen}(L)$ and $\mathsf{cen}(O)$ if and only if there exists a point $q$ in the plane, but not necessarily from $P$,  such that  $q$ is on the boundary of both $\mathsf{cell}(L)$ and $\mathsf{cell}(O)$. In particular, the edge is the curve $\mathscr{C}(\mathsf{cen}(L), q, \mathsf{cen}(O))$  (see Fig.  \ref{edgsetconstr_1} for an illustration). 





