\begin{lemma}\label{E_1_proof}
	The graph $G = (V, E_1)$ satisfies the locality condition for the disks in $\mathcal{R}_1$. 
\end{lemma}

\begin{proof}
Let $D$ be a disk in $\mathcal{R}_1$. Then there exists a point $p \in \mathcal{P}$ that is covered by $D$ as well as at least one disk in $\mathcal{L}$ and at least one disk in  $\mathcal{O}$. We consider that $p \in \mathsf{cell}(O)$ for some $O \in \mathcal{O}$ (when $p \in \mathsf{cell}(L)$ for some $L \in \mathcal{L}$, a similar argument can be given). Therefore, $\mathsf{\Phi}(O, p) \leq \mathsf{\Phi}(O^\prime, p) $ for all $O^\prime \in \mathcal{L} \cup  \mathcal{O}$.  Similarly, let $L \in \mathcal{L}$ be a disk such that $\mathsf{\Phi}(L, p) \leq \mathsf{\Phi}(L^\prime, p)$ for all $L^\prime \in \mathcal{L}$. Observe that disks  $O$ and  $L$  cover the point $p$. Otherwise, it contradicts that $D \in \mathcal{R}_1$. Now, there are two possible cases: 


	\begin{description}
		\item[Case (a)] Suppose that $\mathsf{\Phi}(O, p) = \mathsf{\Phi}(L, p)$. 
		%\item[Case (a)] \textbf{[\boldmath{ $\mathsf{\Phi}(O, p) = \mathsf{\Phi}(L, p)$}]:}
		Then, both $\mathsf{cell}(O)$ and $\mathsf{cell}(L)$ share a common point $p$ and hence  there exists an edge between $\mathsf{cen}(D)$ and $\mathsf{cen}(L)$ in $E_1$.

		\item [Case (b)] 
		%\textbf{[\boldmath{$\mathsf{\Phi}(O, p) < \mathsf{\Phi}(L, p)$}]:}
		Suppose that $\mathsf{\Phi}(O, p) < \mathsf{\Phi}(L, p)$.  Consider the segment $\seg(\mathsf{cen}(L),  p)$. Note that  $\seg(\mathsf{cen}(L),  p)$ may contain points belonging to several cells.  Let $x \in \seg(\mathsf{cen}(L), p)$ be a point on the boundary of $\mathsf{cell}(L)$. Let $D^\prime \in \mathcal{L} \cup \mathcal{O}$ be a disk such that $\mathsf{\Phi}(D^\prime, x) = \mathsf{\Phi}(L, x)$. We now show that $D^\prime$ is a disk in $\mathcal{O}$ and covers $p$. Recall the assumption that no three points in $\mathcal{P}$ and disk centers are collinear. Then we have,
		 $||\mathsf{cen}(D^\prime) -  p|| < ||p -  x|| + ||\mathsf{cen}(D^\prime) -  x||$, that implies $\mathsf{\Phi}(D^\prime, p) < ||p -  x|| + \mathsf{\Phi}(D^\prime,  x)$  $ = ||p -  x|| + \mathsf{\Phi}(L, x) = \mathsf{\Phi}(L, p)$. By Lemma \ref{properties_WVD}, we conclude that the disk $D^\prime$ covers the point $p$. Further, $D^\prime$ is a disk in $\mathcal{O}$, as otherwise, the choice of $L$ is wrong. Note that, both disks $D^\prime$ and $L$ are the dominators of $D$ and $\mathsf{\Phi}(D^\prime, x) = \mathsf{\Phi}(L, x)$. Thus, there exists an edge  between $\mathsf{cen}(D^\prime)$ and $\mathsf{cen}(L)$ in $E_1$. 
	\end{description} 
Therefore, the lemma is proved.  \end{proof}



\subsubsection{Phase II: Construction of the edge set $E_2$}
%\noindent \textbf{{Phase II (construction of the edge set \boldmath{$E_2$}):}}   
For every disk $D \in \mathcal{R}$, let $\mathcal{P}^D \subseteq \mathcal{P}$ be the set of points that are covered by the disk $D$. Let $\mathcal{O}_{D} \subseteq \mathcal{O}$ and $\mathcal{L}_D \subseteq \mathcal{L}$  be the sets of dominators of $D$.  Further, let  $\mathcal{P}_\mathcal{L}^D \subseteq \mathcal{P}^D$ be the set of points covered by at least one disk in $\mathcal{L}_D$ and $\mathcal{P}_\mathcal{O}^D \subseteq \mathcal{P}^D$ be the set of points covered by at least one disk in $\mathcal{O}_D$. Note that  sets  $\mathcal{P}_\mathcal{L}^D$ and $ \mathcal{P}_\mathcal{O}^D$ are non-empty and disjoint, i.e.,  $\mathcal{P}_\mathcal{L}^D \cap \mathcal{P}_\mathcal{O}^D = \emptyset$. Further, $\mathcal{L}_D \cap \mathcal{O}_D = \emptyset$.  

\begin{lemma} \label{intersection_of_linesegments}
Let $p_1 \in \mathcal{P}_\mathcal{L}^D$ and $p_2 \in \mathcal{P}_\mathcal{O}^D$ be two points for some $D \in \mathcal{R}_2$. Further, let $p_1^\prime  \in \mathcal{P}_\mathcal{L}^{D^\prime}$ and $p_2^\prime \in \mathcal{P}_\mathcal{O}^{D^\prime}$ be the two points such that $p_1 \neq p_1^\prime $ and $p_2 \neq p_2^\prime $ for some $D^\prime \in \mathcal{R}_2$.  If the segments $\seg(p_1, p_2)$ and $\seg(p_1^\prime,  p_2^\prime)$ intersect then $\{p_1,p_2\}\cap \mathcal{P}^{D^\prime}\neq \emptyset$ or  $\{p_1^\prime,p_2^\prime\}\cap \mathcal{P}^{D}\neq \emptyset$. 
%at least one of the following is true: (i) $p_1$ or $p_2$ is covered by disk $D^\prime$ and (ii) $p_1^\prime$ or $p_2^\prime$ is covered by disk $D$. 
\end{lemma}

\begin{proof}
  We note that the segment $\seg(p_1, p_2)$ is completely inside $D$ and $\seg(p_1^\prime,  p_2^\prime)$ is completely inside $D^\prime$. If $p_1$ and $p_2$ are not covered by $D^\prime$, then $\seg(p_1,  p_2)$ intersects the disk's boundary $D^\prime$ exactly two times. Similarly, if both $p_1^\prime $ and $p_2^\prime$ are not covered by the disk $D$, then $\seg(p_1^\prime,  p_2^\prime)$ intersects the boundary of the disk $D$ twice. Note that no point in $\mathcal{P}$  lies on the boundary of any disk in $\mathcal{R}$.  Thus, if the statement of the lemma is not true, then boundaries of both $D$ and $D^\prime$ intersect four times, which is impossible.   	 
\end{proof}




\begin{lemma} \label{segment_edge}
   Let  $D  \in  \mathcal{R}_2$ be a disk. Further, let $p_1 \in \mathcal{P}_\mathcal{L}^D$ and $p_2 \in \mathcal{P}_\mathcal{O}^D$ be two points covered by $D$. Then, there exists a  segment $\seg(x_1, x_2) \subseteq \seg(p_1, p_2)$ such that 
   \begin{enumerate} 
       \item $x_1$ is a boundary point of $\mathsf{cell}(L)$ for some $L \in \mathcal{L}_D$, 
       \item $x_2$ is a boundary point of $\mathsf{cell}(O)$ for some $O \in \mathcal{O}_D$, and 
       \item there exists no other dominator,  $X \in \mathcal{L}_D \cup \mathcal{O}_D$, of $D$ such that $\mathsf{cell}(X)$ covers a point from $\seg(x_1, x_2)$. 
   \end{enumerate}


  \label{exist_non_dominator}
\end{lemma}

\begin{proof}

Let $\seg(x_1, x_2)$ be a minimal portion of $\seg(p_1, p_2)$ such that $x_1 \in \mathsf{cell}(L)$ and $x_2 \in \mathsf{cell}(O)$ for some disks $L \in \mathcal{L}_D$ and $O \in \mathcal{O}_D$. We note that such $L$ and $O$ exist because $p_1 \in \mathcal{P}_\mathcal{L}^D$ and $p_2 \in \mathcal{P}_\mathcal{O}^D$. Suppose that there exists a disk $X \in \mathcal{L}_D$ (the case $X \in  \mathcal{O}_D$ is similar) that covers a point $x \in \seg(x_1, x_2)$. Then the choice of $\seg(x_1, x_2)$ is wrong since $\seg(x, x_2)$ is minimal than $\seg(x_1, x_2)$ and satisfies the first two conditions of the lemma. Hence, no such disk $X \in   \mathcal{L}_D$ exists. \hfill  
\end{proof}


For a disk $D \in \mathcal{R}_2$, we call a segment $\seg(x_1, x_2) \subseteq \seg(p_1, p_2)$, where $p_1 \in \mathcal{P}_\mathcal{L}^D$ and $p_2 \in \mathcal{P}_\mathcal{O}^D$, that satisfy the conditions in Lemma \ref{segment_edge} as \textit{\colb{edge-segment}} of $D$. Note that, in general, the segment  $\seg(x_1, x_2)$ connects the boundaries of two cells in  $\mathsf{AWVD}$; one cell corresponding to a disk in $\mathcal{L}$ and other cell is corresponding to a disk in $\mathcal{O}$. 

Let $\mathcal{S}$ be the set of all possible non-overlapping edge segments such that for each disk $D$ in $\mathcal{R}_2$ there exists an edge segment $\seg(x_1, x_2) \subseteq \seg(p_1, p_2)$ where $p_1 \in \mathcal{P}_\mathcal{L}^D$ and $p_2 \in \mathcal{P}_\mathcal{O}^D$. We note that such $\mathcal{S}$ exists due to Lemma \ref{intersection_of_linesegments}.   In the following, we describe the construction of the edge set $E_2$: 

\begin{description}
    \item [Step 1.] Let $\seg(x, x^\prime)$ be a segment in $\mathcal{S}$ such that $\seg(x, x^\prime) \subseteq \seg(p, p^\prime)$ where $p \in \mathcal{P}_\mathcal{L}^D$ and $p^\prime \in \mathcal{P}_\mathcal{O}^D$ for some disk $D \in \mathcal{R}_2$.

    \item [Step 2.] Let  $L \in \mathcal{L}_D$ and $O \in \mathcal{O}_D$ be the two disks such that $x \in \mathsf{cell}(L)$ and $x^\prime  \in \mathsf{cell}(O)$.  

    \item [Step 3.] Place an edge $\mathscr{C}(\mathsf{cen}(L), x, x^\prime, \mathsf{cen}(O))$ 	in  $E_2$. The segment $\seg(\mathsf{cen}(L), x)$ is completely inside $\mathsf{cell}(L)$, the  segment $\seg(x^\prime,  \mathsf{cen}(O))$ is completely inside $\mathsf{cell}(O)$, and  the segment $\seg(x, x^\prime)$  is completely inside the disk $D$. See Fig.  \ref{fig:step3} for an illustration. 
\end{description}


