\section{\texorpdfstring{\boldmath{\apx}}~-hardness Results} \label{apx_hard_results}



In this section, we present \apx-hardness results for the \mdis~and \mdds~problems.    First,  we  define a restricted version of the \mds~problem with set systems, the \spds~problem, and show that it is \apx-hard. We use the \spds~to prove Theorem \ref{apx_hardness_mdds}. The work is inspired by the results in \cite{Chan2014}.   



\begin{definition} [\boldmath{\spds}] Let $(\mathcal{U}, \mathcal{S})$ be a range space where $\mathcal{U} = \mathcal{A} \cup \mathcal{B}$, $\mathcal{A} = \{a_1, a_2, \ldots, a_n\}$, $\mathcal{B}  = \mathcal{B}^1 \cup \mathcal{B}^2 \cup \cdots \cup \mathcal{B}^6$, and  $\mathcal{B}^i = \{b_1^i, b_2^i, \ldots, b_m^i\}$ for $1 \leq i \leq 6$ such that $3m=  2n$. Further, $\mathcal{S}$ is a collection of $7m$ subsets of $\mathcal{U}$ such that
\begin{enumerate}

\item Every element in $\mathcal{U}$ is in exactly two sets in $\mathcal{S}$. 

\item For every $t$, ($1 \leq t \leq m$), there exist three integers $ 1 \leq i < j < k \leq n$ such that the sets $\{a_i, b_t^1\}$, $\{b_t^1, b_t^2\}$, $\{b_t^2, b_t^3\}$, $\{b_t^3, b_t^4, a_j\}$, $\{b_t^4, b_t^5\}$, $\{b_t^5, b_t^6\}$, and $\{b_t^6, a_k\}$ are in the collection $\mathcal{S}$. 
\end{enumerate}


The objective is to find a minimum size sub-collection $\mathcal{S}^\prime \subseteq \mathcal{S}$ such that for every $S \in \mathcal{S}$,  either $S \in \mathcal{S}^\prime$ or there exists a set $S^\prime \in \mathcal{S}^\prime$ such that $S \cap S^\prime \neq \emptyset$. 
	\label{special_3ds_def}
\end{definition}



We use the \colb{$L$-reduction} \cite{PAPADIMITRIOU1991}  to prove that the \spds~is \apx-hard. 
Let $X$ and $Y$ be two optimization problems. 
A polynomial-time computable function $f$ from $X$ to $Y$ is an $L$-reduction if there exist two positive constants $\alpha$ and $\beta$ (usually 1) such that  for each  instance $x$ of $X$ the following two conditions hold:

\begin{description}
    \item[C1:] $OPT(f(x)) \leq \alpha \cdot OPT(x)$ where $OPT(x)$ and $OPT(f(x))$ are the size of the optimal solutions of $x$ and $f(x)$,  respectively. 
    \item[C2:] For any given solution of  $f(x)$ with cost $C_{f(x)}$,  there exists a polynomial-time algorithm that finds a feasible solution of $x$ with cost $C_x$ such that $|C_x -OPT(x)| \leq \beta \cdot |C_{f(x)} - OPT(f(x))|$. 
\end{description}

\begin{lemma}\label{special_3ds_apx_hard}
\spds~is \apx-hard.  
\end{lemma}	

\begin{proof}
We prove the lemma by giving an $L$-reduction from an \apx-hard problem, dominating set on cubic graphs \cite{ALIMONTI}. Let $I_1$ be an instance of dominating set problem on a graph $G  = (V, E)$ with $V = \{v_1, v_2, \ldots, v_m\}$  and $E = \{e_1, e_2, \ldots, e_n\}$ such that the degree of every vertex in $V$ is exactly  three.  We now generate an instance $I_2$ of \spds~from $I_1$ as follows:
\begin{enumerate}

\item Let $\mathcal{A} = \{a_1, a_2, \ldots, a_n\}$ and $\mathcal{B} = \mathcal{B}^1 \cup \mathcal{B}^2 \cup \cdots \cup \mathcal{B}^6$ where $\mathcal{B}^i = \{b_1^i, b_2^i, \ldots, b_m^i\}$ for $i=1, 2, \ldots, 6$.
\item For a vertex   $v_t$    in $V$ ($1 \leq t \leq m$),  let $e_i, e_j,$ and $e_k$ ($1\leq i < j < k \leq n$) be the edges incident on $v_t$.  Then add seven sets $\{a_i, b_t^1\}$, $\{b_t^1, b_t^2\}$, $\{b_t^2, b_t^3\}$, $\{b_t^3, b_t^4, a_j\}$, $\{b_t^4, b_t^5\}$, $\{b_t^5, b_t^6\}$, and $\{b_t^6, a_k\}$ into $\mathcal{S}$. Do the same for every vertex in $V$. 

\end{enumerate}

Let $\mathcal{O}(I_1) \subseteq V$  be an optimal dominating set for the instance $I_1$. We now give a polynomial-time algorithm to find an optimal solution  $\mathcal{O}(I_2)$ for instance $I_2$ of the \spds~problem  from $\mathcal{O}(I_1)$. For every vertex $v_t \in V(G)$, do the following:
\begin{enumerate}
\item If $v_t$ is in $\mathcal{O}(I_1)$ then take the sets $\{a_i, b_t^1\}$, $\{b_t^3, a_j, b_t^4\}$, $\{b_t^6, a_k\}$ in $\mathcal{O}(I_2)$. 

\item If $v_t$ is not in $\mathcal{O}(I_1)$ then take the sets $\{b_t^2, b_t^3\}$, $\{b_t^4, b_t^5\}$ in $\mathcal{O}(I_2)$. 
\end{enumerate}

One can easily verify that  $\mathcal{O}(I_2)$ is an optimal dominating set for $I_2$ and $|\mathcal{O}(I_2)| = |\mathcal{O}(I_1)| + 2 m $.  Since $|\mathcal{O}(I_1)| \geq m/4$  we get $|\mathcal{O}(I_2)| \leq 9 \cdot  |\mathcal{O}(I_1)| $. 
	Similarly, for any given  feasible solution $\mathsf{F}_2 \subseteq \mathsf{S}$ of $I_2$, one can obtain a feasible solution  $\mathsf{F}_1 \subseteq V(G)$ of $I_1$ such that $|\mathsf{F}_1| \leq |\mathsf{F}_2| - 2m$. 

	Thus,  we conclude that the above reduction is an $L$-reduction \cite{PAPADIMITRIOU1991}  with $\alpha=9$ and $\beta=1$. Therefore, the \spds~problem is \apx-hard.  
 \end{proof}


\begin{theorem}\label{apx-hardness-theorem}
	The \mdds~problem is \apx-hard for the following classes of geometric objects.
	\begin{description} 

		\item[{\bf A1}]  Axis-parallel rectangles in $\mathbb{R}^2$, even when all rectangles have an upper-left corner inside a square with side length $\epsilon$ and lower-right corner inside a square with side length $\epsilon$ for an arbitrary small $\epsilon>0$.

		\item[{\bf A2}] Axis-parallel  ellipses in $\mathbb{R}^2$, even when all the ellipses  contain the origin. 

		\item[{\bf A3}] Axis-parallel strips in $\mathbb{R}^2$. 
		\item[{\bf A4}]   Axis-parallel rectangles in $\mathbb{R}^2$,  even when every pair of rectangles intersects either zero or four times. 
		\item[{\bf A5}] Downward shadows of  segments in the plane.


		\item[{\bf A6}]  Downward shadows of cubic polynomials in the plane. 

		\item[{\bf A7}] Unit ball in $\mathbb{R}^3$, even when the origin is inside every unit ball.

		\item[{\bf A8}] Axis-parallel cubes of similar size in $\mathbb{R}^3$ containing a common point.

		\item[{\bf A9}] Half-spaces in $\mathbb{R}^4$. 

		\item[{\bf A10}] Fat semi-infinite wedges in $\mathbb{R}^2$ with apices near the origin. 
	\end{description}
	\label{apx_hardness_mdds}
\end{theorem}

\begin{proof}
%{Proof of Theorem \ref{apx_hardness_mdds}.} 
The proof is essentially similar to the results in  \cite{Chan2014}. In the following, for a given instance of the \spds~problem, we give an encoding of the \mdds~problem for each class of objects. Let $(\mathcal{U}, \mathcal{S})$ be a range space where $\mathcal{U} = \mathcal{A} \cup \mathcal{B}$, $\mathcal{A} = \{a_1, a_2, \ldots, a_n\}$, and  $\mathcal{B}  = \mathcal{B}^1 \cup \mathcal{B}^2 \cup \cdots \cup \mathcal{B}^6$, where $\mathcal{B}^i = \{b_1^i, b_2^i, \ldots, b_m^i\}$, for $1 \leq i \leq 6$, with $3m=  2n$. Further, $\mathcal{S}$ is a collection of $7m$ subsets of $\mathcal{U}$ such that
\begin{enumerate}

\item Every element in $\mathcal{U}$ is in exactly two sets in $\mathcal{S}$. 

\item For every $t$, ($1 \leq t \leq m$), there exist three integers $ 1 \leq i < j < k \leq n$ such that the sets $\{a_i, b_t^1\}$, $\{b_t^1, b_t^2\}$, $\{b_t^2, b_t^3\}$, $\{b_t^3, b_t^4, a_j\}$, $\{b_t^4, b_t^5\}$, $\{b_t^5, b_t^6\}$, and $\{b_t^6, a_k\}$ are in the collection $\mathcal{S}$. 
\end{enumerate}



Similar to the \spsc~problem defined in \cite{Chan2014}, in the \spds~problem, we order the elements in $\mathcal{B}$ such that every set in $\mathcal{S}$ contains either two consecutive elements from $\mathcal{B}$, or one element from $\mathcal{A}$ and one element from $\mathcal{B}$, or one element from $\mathcal{A}$ and two consecutive elements from $\mathcal{B}$. In particular, in the below embedding, for every $t$ ($1\leq t \leq m$), the six points  $b_t^1, b_t^2, b_t^3, b_t^4, b_t^5, \text{ and } b_t^6$ are together in the same order. Further, similar to the \spsc~problem, in any instance of the \spds~problem,  every element in the ground set $\mathcal{U}$ is present in exactly two sets in $\mathcal{S}$ and a set in $\mathcal{S}$ contains at most three elements from $\mathcal{U}$.  

%One can encode any instance of the \spds~problem into the instances of the \mdds~problem for classes $\textbf{A1}$-$\textbf{A10}$ by following the similar procedure of obtaining the encoding of the corresponding classes $\textbf{A1}$-$\textbf{A10}$ from the \spsc~problem given in \cite{Chan2014}.
%set covers for the same classes of objects $\textbf{A1}$-$\textbf{A10}$ from the  \spsc~problem given in \cite{Chan2014}. 
