\section{Relation between Zernike Polynomials and Jacobi Polynomials}
\label{appendix-jac}
For the special case of $\beta=0$, $x=1-2\rho^2$ and $\alpha=m$, Jacobi Polynomials can be written using Equation \ref{jacobi},
\begin{equation}
    P_{n}^{m, 0}(1-2\rho^2) = \sum_{s=0}^{n} (-1)^s\binom{n+m}{n-s} \binom{n}{s} \rho^{2s}(1-\rho^2)^{n-s} \label{eq_jac}
\end{equation}
Now use the binomial theorem to expand $(1-\rho^2)^{n-s}$,
\begin{equation}
    (1-\rho^2)^{n-s} = \sum_{k=0}^{n-s} (-1)^k \binom{n-s}{k} \rho^{2k}
\end{equation}
Substitute this in eq \ref{eq_jac},
\begin{equation}
    P_{n}^{m, 0}(1-2\rho^2) = \sum_{s=0}^{n} (-1)^s \binom{n}{s} \binom{n+m}{n-s}  \rho^{2s} \sum_{k=0}^{n-s} (-1)^k \binom{n-s}{k} \rho^{2k}
\end{equation}
Now, rearrange the terms,
\begin{equation}
    P_{n}^{m, 0}(1-2\rho^2) = \sum_{s=0}^{n}\sum_{k=0}^{n-s} (-1)^{(s+k)} \binom{n+m}{n-s} \binom{n}{s} \binom{n-s}{k} \rho^{2(s+k)}
\end{equation}
Substitute $j=s+k$, hence $k=j-s$ ,
\begin{align}
    P_{n}^{m, 0}(1-2\rho^2) &= \sum_{s=0}^{n}\sum_{j-s=0}^{j-s=n-s} (-1)^{j} \binom{n+m}{n-s} \binom{n}{s} \binom{n-s}{j-s}\rho^{2j}\\
    P_{n}^{m, 0}(1-2\rho^2) &= \sum_{s=0}^{n}\sum_{j=s}^{n} (-1)^{j} \binom{n+m}{n-s} \binom{n}{s} \binom{n-s}{j-s}\rho^{2j}  
\end{align}
Here, we can change the order of summation, it is better to use table to find new limits,
\[
\begin{array}{c|cccccc}
  & 0 & 1 & 2 & \cdots & n-1 & n \\
\hline
s = 0 & \times & \times & \times & \cdots & \times & \times \\
s = 1 &       & \times & \times & \cdots & \times & \times \\
s = 2 &       &       & \times & \cdots & \times & \times \\
\vdots &       &       &       & \ddots & \vdots & \vdots \\
s = n-1 &       &       &       &       & \times & \times \\
s = n &       &       &       &       &       & \times \\
\end{array}
\]
Each \(\times\) represents a valid pair \((s, j)\). This can be re-written in terms of summation over $j$ first, then $s$,
\[
\begin{array}{c|cccccc}
  & 0 & 1 & 2 & \cdots & n-1 & n \\
\hline
j = 0 & \times &       &       &       &       &       \\
j = 1 & \times & \times &       &       &       &       \\
j = 2 & \times & \times & \times &       &       &       \\
\vdots &       &       &       & \ddots &       &       \\
j = n-1 & \times & \times & \times & \cdots & \times &       \\
j = n & \times & \times & \times & \cdots & \times & \times \\
\end{array}
\]
Since the \((s, j)\) pairs are the same, the nested summation can be written as,
\begin{equation}
    P_{n}^{m, 0}(1-2\rho^2) = \sum_{j=0}^{n} \rho^{2j}   \sum_{s=0}^{j} (-1)^{j} \frac{(n+m)!}
    {(n-s)!(m+s)!}\frac{n!}{s!(n-s)!}\frac{(n-s)!}{(j-s)!(n-j)!}
\end{equation}
\begin{equation}
    P_{n}^{m, 0}(1-2\rho^2) = \sum_{j=0}^{n} \rho^{2j}   \sum_{s=0}^{j} (-1)^{j} \frac{(n+m)!}{(n-s)!(m+s)!} \frac{j!}{s!(j-s)!} \frac{n!}{j!(n-j)!} 
\end{equation}
\begin{equation}
    P_{n}^{m, 0}(1-2\rho^2) = \sum_{j=0}^{n} (-1)^{j} \binom{n}{j} \rho^{2j}   \sum_{s=0}^{j}  \binom{n+m}{n-s} \binom{j}{s}  \label{eq_jacobi2simplify}
\end{equation}
Now, we need to use a property of the binomial coefficients. Consider,
\begin{equation}
    (1+x)^n = \sum_{k=0}^{n} \binom{n}{k}x^k 
\end{equation}

\begin{equation}
    \begin{split}
        (1+x)^{n+m}(1+x)^j =&  \left(\sum_{k=0}^{n+m} \binom{n+m}{k}x^k\right) \left(\sum_{k=0}^{j} \binom{j}{k}x^k\right) \\
        =& \left(\sum_{s=-m}^{n} \binom{n+m}{n-s}x^{n-s}\right) \left(\sum_{k=0}^{j} \binom{j}{k}x^k\right) 
    \end{split}
\end{equation}  

\begin{equation}
    (1+x)^{n+m+j} = \sum_{k=0}^{n+m+j} \binom{n+m+j}{k}x^k 
\end{equation}
For $x^\gamma$ coefficient, we have 
\begin{equation}
    \binom{n+m+j}{\gamma} x^{\gamma}= \sum_{k=0}^{\gamma} \binom{j}{k} \binom{n+m}{\gamma-k} x^{\gamma}
\end{equation}
In previous step, I used $n-s+k=\gamma$ and $s=n+k-\gamma$, hence $n-s=\gamma-k$. Now, let's substitute $\gamma=n$,
\begin{equation}
    \binom{n+m+j}{n} = \sum_{k=0}^{j} \binom{n+m}{n-k} \binom{j}{k}
\end{equation}
We can finally use this relation to simplify eq \ref{eq_jacobi2simplify},
\begin{equation}
    P_{n}^{m, 0}(1-2\rho^2) = \sum_{j=0}^{n} (-1)^{j}  \rho^{2j}  \binom{n}{j} \binom{n+m+j}{n}
\end{equation}
Lets's multiply last equation by $\rho^m$ and $(-1)^n$,
\begin{equation}
    (-1)^n\rho^mP_{n}^{m, 0}(1-2\rho^2) = \sum_{j=0}^{n} (-1)^{j+n}  \rho^{2j+m} \binom{n}{j} \binom{n+m+j}{n}
\end{equation}
Substitute $j=n-s$,
\begin{equation}
    (-1)^n\rho^mP_{n}^{m, 0}(1-2\rho^2) = \sum_{n-s=0}^{n-s=n} (-1)^{2n-s}  \rho^{2n+m-s}  \binom{n}{n-s} \binom{2n+m-s}{n}
\end{equation}
\begin{equation}
    (-1)^{\frac{l-m}{2}}\rho^mP_{\frac{l-m}{2}}^{m, 0}(1-2\rho^2) = 
    \sum_{s=0}^{(l-m)/2} (-1)^{s}  \rho^{l-2s}  \binom{\frac{l-m}{2}}{s} \binom{l-s}{\frac{l-m}{2}}
\end{equation}
\begin{equation}
    (-1)^{\frac{l-m}{2}}\rho^mP_{\frac{l-m}{2}}^{m, 0}(1-2\rho^2) = 
    \sum_{s=0}^{(l-m)/2} (-1)^{s} \cfrac{\frac{l-m}{2}!}{s!(\frac{l-m}{2}-s)!} \cfrac{(l-s)!}{\frac{l-m}{2}!(\frac{l+m}{2}-s)!} \rho^{l-2s}  
\end{equation}
\begin{equation}
    \begin{split}
        \mathcal{R}_l^{m} (\rho) 
        &= (-1)^{\frac{l-m}{2}}\rho^mP_{\frac{l-m}{2}}^{m, 0}(1-2\rho^2) \\
        &= \mathlarger{\mathlarger{\sum}}_{s=0}^{(l-m)/2} \frac{(-1)^s(l-s)!}{ s!\left( \cfrac{l+m}{2} - s\right)! \left( \cfrac{l-m}{2} - s\right)!}  \hspace{0.1cm} \rho^{l-2s} 
    \end{split}
\end{equation}
which is exactly equivalent to the radial part of the Zernike Polynomials.




\section{Validity of chosen precision in \texttt{mpmath}}
\label{appendix-mpmath}

The accuracy of different algorithms is tested using the \texttt{mpmath} package which allows arbitrary precision in Python. A user can set different decimal point precisions with the option \texttt{mpmath.mp.dps} that will change the number of significant digits used in \texttt{mpmath} functions such as \texttt{fsub()} for subtraction and \texttt{fadd()} for addition. The corresponding bit precision can be found using \texttt{mpmath.mp.prec} and the relation is shown in Figure \ref{bitwise}.

\begin{figure}
    \centering
    \includegraphics[width=0.55\linewidth]{appendix-figure-1.png}
    \caption{The corresponding bit precision of different \texttt{mpmath} decimal point precisions shown for range $[8,100]$. 64-bit precision can be achieved by setting \texttt{dps} to 18. The minimum value chosen for this figure \texttt{dps}=8 has 30-bit and the maximum value \texttt{dps}=100 has 336-bit precision.}
    \label{bitwise}
\end{figure}

We performed the direct polynomial evaluation of Zernike polynomials up to $n,m$=100 with different decimal point precisions and compared the difference with an excessively high value of 200 significant digits. Since the machine precision of 64 bits is aimed for the final result, we use the native Python subtraction operation for error calculation.

\begin{figure}
    \centering
    \includegraphics[width=0.55\linewidth]{appendix-figure-2.png}
    \caption{The maximum difference between Zernike polynomials up to $n,m$=100 calculated with lower \texttt{dps} and 200 \texttt{dps}, $\Tilde{Z}_{nm}(x)$. For the log scale, 0's are set to $2^{-53}$.}
    \label{prec-compare}
\end{figure}

After \texttt{mpmath.mp.dps}=54, the difference calculated with Python subtraction is 0. This corresponds to 153-bit precision. To be able to show the results on a log scale in Figure \ref{prec-compare}, we have set the 0 values to 64-bit machine precision that is $2^{-53}$. Although the required precision is 54 \texttt{dps}, we have chosen 100 \texttt{dps} for the results of this paper just to be on the safe side and to be able to use the same functions for higher mode numbers which require higher precision.


