\section{Preliminaries}\label{sec:prelim}

Let $X$ be a set. A function $\dist \colon X\times X \to \mathbb{R}_{\ge 0}$  is a \emph{distance} on $X$ if: 
% \begin{itemize}
% \item[(i)]
(i) $\dist$ is symmetric, that is,  for any $x, y \in X$, $\dist(x, y) = \dist(y, x)$, and  
% \item[(ii)] 
(ii) $\dist(x, x) = 0$ for all  $x\in X$.
% \end{itemize}
Then, $ (X, \dist)$ is called a \emph{distance space}. 
%For a subset of points  $Y\subset X$, the distance $\dist$ naturally induces the distance space $(Y, \dist)$.
% 
If, in addition $\dist$ satisfies a triange inequality: $\dist(x, z) \le \dist(x, y) + \dist(y, z)$, for any $x, y, z \in X$, then $\dist$ is called a semimetric on $X$. And if $\dist(x,y)=0$ only for $x=y$, then $\dist$ is called a \emph{metric}, and $ (X,\dist)$ a \emph{metric space}. 


More precisely, recall that 
for two points %(vectors)  
$p, q \in \mathbb{R}^d$, the Euclidean distance between $p$ and $q$ is  $\| p - q \|_2=\sqrt{\langle p,p\rangle+ \langle q,q\rangle - 2\langle p,q\rangle}$. 
We say that distance space $(X,\dist)$ is \emph{isometrically embeddable} into $\mathbb{R}^d$ if there is a map, called \emph{isometric embedding}, $\varphi \colon X\to \mathbb{R}^d$ such that 
$\dist(x,y)=\|\varphi(x)-\varphi(y)\|_2$
%$\dist(x,y)=\distE(\varphi(x),\varphi(y))$ 
for all $x,y\in X$. Notice that we do not require $\varphi$ to be injective, that is, several points of $(X,\dist)$ may be mapped to the same point of $\mathbb{R}^d$.
Throughout the paper, whenever we mention an embedding, we mean an isometric embedding. Moreover, when we use the term $d$-embedding, we are referring to embedding into $\mathbb{R}^{d}$.  A $d$-embeddable  
  distance space is {\em strongly $d$-embeddable} if it is not $(d-1)$-embeddable. We use $X^{(2)}$ to denote the set of unordered pairs of two distinct elements of $X$. As convention, we assume that the empty set of points is $d$-embeddable 
% in $\mathbb{R}^d$ 
for every $d$.


Let $\Xcal=(X,\dist)$ be a distance space where $X=\{x_1,\ldots,x_n\}$, and let $\dist_{i,j}=\dist(x_i,x_j)$ for all $i,j\in\{1,\ldots,n\}$. Then $\Xcal$ is equivalently defined by the \emph{distance matrix}  

\[
D(\rho)=\left(
 \begin{matrix}
0 & \dist_{1,2}^2 & \dist_{1,3}^2 & \dots & \dist_{1,n}^2 \\
\dist_{2,1}^2 & 0 & \dist_{2,3}^2 & \dots & \dist_{2,n}^2 \\
\dist_{3,1}^2 & \dist_{3,2}^2 & 0 & \dots & \dist_{3,n}^2 \\
\vdots & \vdots & \vdots & \ddots & \vdots \\
\dist_{n,1}^2 & \dist_{n,2}^2 & \dist_{n,3}^2 & \dots & 0 \\
\end{matrix} \right)
\]

We drop the explicit reference to $\rho$ when it is clear from the context and instead of $D(\rho)$, simply write $D$.
Suppose that $\Xcal$ is embeddable into $\mathbb{R}^d$. The ordered set 
$P=(p_1,\ldots,p_n)$ of points in $\mathbb{R}^d$ is said to be a \emph{realization} of $\Xcal$ if there is an embedding $\varphi \colon X\to \mathbb{R}^d$ such that $\varphi(x_i)=p_i$ for all $i\in\{1,\ldots,n\}$.
We use the well-known property (see e.g.~\cite{dokmanic2015euclidean}) that a realization is unique up to 
 \emph{rigid transformations} of $\mathbb{R}^d$, that is, distance-preserving transformations of Euclidean space (rotations, reflections, translations).

\begin{proposition}[\cite{dokmanic2015euclidean}]\label{prop:unique}
Let $(p_1,\ldots,p_n)$ and $(q_1,\ldots,q_n)$ be ordered set of points in $\mathbb{R}^d$. Then $\|p_i-p_j\|_2=\|q_i-q_j\|_2$ for all $i,j\in\{1,\ldots,n\}$ if and only if there is a rigid transformation of $\mathbb{R}^d$ mapping $p_i$ to $q_i$ for all $i\in\{1,\ldots,n\}$. 
\end{proposition}

A realization can be constructed (if it exists) in polynomial time.

\begin{proposition}[\cite{AlencarBLL15,SipplS85}]\label{prop:realization}
Given a distance space $\Xcal=(X,\dist)$ with $n$ points and a positive integer $d$, in $\Oh(n^3)$ time, it can be decided whether $\Xcal$ can be embedded into $\mathbb{R}^d$ and, if such an embedding exists, then a realization can be constructed in this running time.    
\end{proposition}
\newcommand{\mathbbr}[1]{\mathbb{R}^{#1}}


\begin{definition}[Metric basis]
    \label{def:metricBasis}
    Let $(X,\dist)$ be a $d$-embeddable distance space. A set $Y\subseteq X$ is a \emph{metric basis} if, given an isometric embedding $\varphi$ of $(Y,\dist)$ into $\mathbb{R}^d$, there is a unique way to extend $\varphi$ to an isometric embedding of $(X,\dist)$. Equivalently, if a 
realization of $(Y,\dist)$ is fixed then the embedding of any point of~$X\setminus Y$ in a $d$-embedding of $(X,\dist)$ 
% $\mathbbr{d}$ 
is unique.  
\end{definition}




We will use the well-known characteristic of strong embeddability of a distance space into a Euclidean space. 
For $r+1$ points $x_0,x_1, \dots, x_r$ of distance space $(X, \dist)$
the \emph{Cayley-Menger determinant} is the determinant of the matrix obtained from the distance matrix by prepending a row and a column whose first element is zero and the other elements are one. Formally, let $\dist_{i,j}=\dist(x_i,x_j)$, $i,j\in \{0,\dots, r\}$. 
Then the Cayley–Menger determinant is  
\[
CM ( x_0,x_1, \dots, x_r) =  \det\left( \begin{matrix}
0 & 1 & 1 & 1 & \dots & 1 \\
1 & 0 & \dist_{0,1}^2 & \dist_{0,2}^2 & \dots & \dist_{0,r}^2 \\
1 & \dist_{0,1}^2 & 0 & \dist_{1,2}^2 & \dots & \dist_{1,r}^2 \\
1 & \dist_{0,2}^2 & \dist_{1,2}^2 & 0 & \dots & \dist_{2,r}^2 \\
\vdots & \vdots & \vdots & \vdots & \ddots & \vdots \\
1 & \dist_{0,r}^2 & \dist_{1,r}^2 & \dist_{2,r}^2 & \dots & 0 \\
\end{matrix} \right)
\]



\begin{proposition}[{\cite[Chapter~IV]{blumenthal1970theory}}]\label{thm:Blumental}
A distance space $\Xcal= (X, \rho)$ with $n$ points is strongly 
% embeddable into $\mathbb{R}^d$ 
$d$-embeddable if and only if there exist $d+1$ points, say $X_d = \{ x_0, \ldots, x_d \}$, such that:
\begin{enumerate}
\item  $(-1)^{j+1}CM ( x_0,x_1, \dots, x_j)>0$ for $1\leq j\leq d$, and 
\item for any $x, y \in X\setminus X_d$,
\[CM ( x_0,x_1, \dots, x_d,x) =CM ( x_0,x_1, \dots, x_d,y)=CM ( x_0,x_1, \dots, x_d,x,y)=0.\] 
\end{enumerate}
Equivalently (see, for example,  \cite{SidiropoulosWW17}), 
$\Xcal$ is strongly 
% embeddable into $\mathbb{R}^d$  
$d$-embeddable if and only if there is a set of $d+1$ points $X_d=\{x_0,\ldots,x_d\}$ such that 
% $(X_d, \rho)$ is strongly embeddable into $\mathbb{R}^d$ and 
$(\{x_0,\ldots,x_j\},\dist)$ is strongly $j$-embeddable 
% into $\mathbb{R}^j$  
for all $j\in\{1,\ldots, d\}$, and
for every $x,y\in X\setminus X_d$, $(X_d\cup\{x\}\cup \{y\})$ is $d$-embeddable.
% into  $\mathbb{R}^d$.
\end{proposition}


Thus, the embedding of the distance space $ \Xcal=(X, \rho)$ into $\mathbb{R}^d$ is essentially characterized by $d+1$ ``anchor'' points of $X$. Note that in a realization of $\Xcal$ that is strongly $d$-embeddable,  the anchor points correspond to a set of $d+1$ points in general position in $\mathbb{R}^d$. 


Following~\cite{blumenthal1970theory}, we define sets of {\em independent points}.

\begin{definition}\label{def:independent}
Let $(X,\dist)$ be a %$d$-embeddable 
distance space. For a nonnegative integer $r$, %$$r\leq d$, 
we say that $Y\subseteq X$ of size $r+1$ is \emph{independent} if $(Y,\dist)$ is strongly $r$-embeddable.      
\end{definition}
Then our  ``anchors'' are independent sets of size $d+1$. We use the following fact that the family of independent sets has matroid-like properties (implicit in~\cite[Chapter~IV]{blumenthal1970theory}).





\begin{proposition}[{\cite[Chapter~IV]{blumenthal1970theory}}]\label{prop:matroid}
Let $(X,\dist)$ be a strongly $d$-embeddable distance space. Then
\begin{itemize}
\item any single-element set is independent,
\item if $Y \subseteq X$ is independent, then any~$\emptyset \subset Z \subseteq Y$ is independent,
\item if $Y,Z \subseteq X$ are independent and $|Y|>|Z|$ then there is a~$y\in Y\setminus Z$ such that $Z\cup\{y\}$ is independent.
\end{itemize}
Furthermore, the maximum size of an independent set is $d+1$ and any independent set~$Y$ of size $d+1$ is a metric basis.
 \end{proposition}



In particular, \Cref{prop:matroid} immediately implies the following statement.

\begin{lemma}\label{equivalence}
     Let $\Xcal=(X,\dist)$ be a distance space. For every $Z\subseteq X$, if $Z$ is independent  
     and  for every $x,y\in X\setminus Z$, $(Z\cup\{x,y\})$ is $(|Z|-1)$-embeddable, 
     then $\Xcal$ is strongly $(|Z|-1)$-embeddable.
\end{lemma}


We also have the following  consequence of \Cref{thm:Blumental}.



\begin{lemma}\deferProof{}\label{lem:incrementDimension}
    Suppose $(X,\rho)$ is a $d$-embeddable distance space, $Y\subset X$ is independent and $x\in X\setminus Y$. Then, $(Y\cup\{x\},\rho)$ is $|Y|$-embeddable.
    \end{lemma}


\begin{proof}
    By definition, since $Y$ is independent, it follows that $(Y,\rho)$ is strongly $(|Y|-1)$-embeddable. Since $(X,\rho)$ is  $d$-embeddable, so is $(Y\cup\{x\},\rho)$. 
    Let $d'\leq d$ be such that $(Y\cup\{x\},\rho)$ is {\em strongly} $d'$-embeddable.   By  \Cref{thm:Blumental}, there exists a set $X_{d'}$ of $d'+1$ points in $Y\cup \{x\}$  such that  $(X_{d'},\rho)$ is strongly $d'$-embeddable. Since $X_{d'}\subseteq Y\cup \{x\}$, it follows that $d'+1\leq |Y|+1\implies d'\leq |Y|$. Hence, $(Y\cup\{x\},\rho)$ is $|Y|$-embeddable.
\end{proof}



To compress the weights in our compression algorithm in~\Cref{sec:kern}, we use the standard technique (see~\cite{EtscheidKMR17}) based on the algorithm of Frank and Tardos~\cite{FrankT87}.

\begin{proposition}[\cite{FrankT87}]\label{prop:FT}
There is an algorithm that, given a vector $w\in\mathbb{Q}^r$ and 
an integer~$N$, in (strongly) polynomial time finds a vector $\overline{w}\in\mathbb{Z}^r$ with $\|\overline{w}\|_{\infty}\leq 2^{4r^3}N^{r(r+2)}$ such that $\mathsf{sign}(w\cdot b)=\mathsf{sign}(\overline{w}\cdot b)$ for all vectors $b\in \mathbb{Z}^r$ with $\|b\|_1\leq N-1$.
\end{proposition}



\section{Compression for \WEEO}\label{sec:kern}
In this section, we show that, given an instance of \WEEO, one can in polynomial time construct an equivalent instance where the number of points is upper-bounded by a polynomial of $k = \koutl+\kmod$ and $d$ and, moreover, the encoding of the weights is also polynomial in these parameters.
\longversion{The main result of this section is the following theorem.}
\begin{theorem}\label{thm:kernel}
There is a polynomial-time algorithm that, given an instance \linebreak $(\Xcal=(X,\dist),\woutl,\wmod,W,\koutl,\kmod,d)$ of \WEEO, either solves the problem or 
constructs an equivalent instance $(\Xcal'=(X',\dist),\woutl',\wmod',W',\koutl',\kmod',d)$ such that $X'\subseteq X$, and for $k=\koutl+\kmod$, it holds that $|X'|=\Oh((kd)^2)$, $W'=2^{\Oh((kd)^{12})}$, $\woutl'(x)=2^{\Oh((kd)^{12})}$ for $x\in X'$, 
and $\wmod'(x,y)=2^{\Oh((kd)^{12})}$ for all $\{x,y\}\in X'^{(2)}$.
\end{theorem}

We remark that \Cref{thm:kernel} does not provide a kernelization algorithm according to the standard definition~\cite{cygan2015parameterized} as the size of the output instance is not upper-bounded by a function of the parameter---the distances between the points remain the same as in the input instance.   Moreover, since {\WEEO} is a decision problem, the word `solve' in the statement of \Cref{thm:kernel} technically only refers to deciding correctly whether the instance is a yes-instance. However, if the instance is determined to be a yes-instance, then our algorithm can also output a solution that witnesses this, i.e., the outlier set and modified new distance values (if any).  This additional feature of our compression algorithm will be used later in our FPT algorithm for {\WEEO}. 

The proof of \Cref{thm:kernel} is conducted in three steps: \begin{enumerate}\item  First, we design a polynomial-time $(d+3)$-approximation algorithm (\Cref{subsect=bootstrapping}). This algorithm allows us, given an instance of the problem,  either find a set of at most $(d+3)k$
points $A$ such that $(X\setminus A,\dist)$ is $d$-embeddable or conclude that we have a no-instance. \item In the first case, we iteratively construct a sequence of metric bases $Y_1,\ldots,Y_\ell$ for $(Z,\dist)$ using~\Cref{prop:matroid}, where initially $Z:=X\setminus A$ and in each iteration, we delete the points of the constructed basis from $Z$. If 
$X\setminus A$ is sufficiently large, then there is a subsequence of bases of the same size with at least $2(\koutl+2\kmod)+1$ elements. We select the first subsequence with this property. The crucial property exploited by our algorithm is that this subsequence uniquely defines embeddings of the majority of the points assuming that we have a yes-instance of the problem. We use this to give a series of reduction rules that identify points in $A$ that should be outliers in any solution and irrelevant points of $X\setminus A$ that could be deleted. 
\longversion{Thus, in polynomial time, we reduce the number of points to $\Oh((kd)^2)$.} 
\item Finally, by making use of \Cref{prop:FT}, we reduce the weights. 
\end{enumerate}

\subsection{Bootstrapping the Compression through an Approximation}\label{subsect=bootstrapping}

For a distance space $\Xcal=(X,\dist)$, a {\em $d$-outlier set} is a set $A$ of points such that $(X\setminus A,\dist)$ is $d$-embeddable. \longversion{Note that when we delete points from $X$, the function $\dist$ is implicitly restricted to $X\setminus A$.~}In unweighted {\EEO} (which we call {\UEEO}), the function $\woutl$ assigns unit weight to every point. 
Sidiropoulos et al.~\cite{SidiropoulosWW17} observed that this problem 
% the {\em unweighted} variant of \EEO
admits a simple greedy \((d+3)\)-approximation running in \(n^{\Oh(d)}\). 
\longversion{This observation is based on the following fact from distance geometry. 
Following Blumenthal \cite{blumenthal1970theory}, the \emph{order of congruence} for a \(d\)-dimensional space refers to the minimum number of points required such that their pairwise distances uniquely determine their geometric configuration (up to rigid transformations like translation, rotation, and reflection). 
By the result of Menger \cite{Menger1928}, for a \(d\)-dimensional Euclidean space \(\mathbb{R}^d\), the order of congruence is 
$n = d + 2$. 
This implies that any distance space admits an embedding into $\mathbbr{d}$ if and only if every subset of $d+3$ points admits such an embedding \cite{blumenthal1970theory}.  
Hence, one could enumerate every subset of $d+3$ points, identify a subset that cannot be embedded into  $\mathbbr{d}$ (if it exists), remove the points in this set and recurse.
}
We show that this algorithm can be sped up to run in \(n^{\Oh(1)}\) time, i.e., independent of $d$ in the exponent.
% by 
To do so, we give a polynomial-time subroutine that produces a small hitting set for all minimal solutions. This subroutine will later be used as the first step of our compression algorithm for {\WEEO}. Moreover, it will also be used to obtain an FPT algorithm for {\EEO} in Section \ref{sec:outlierFPT}.


\begin{lemma}\label{lem:blackBoxObstruction}
There is a polynomial-time algorithm that, given a distance space $\Xcal=(X,\dist)$ and an integer $d\geq 1$, outputs a set of points $\hat A$ of size at most $(d+3)$
such that if $\Xcal$ is not $d$-embeddable, then $\hat A$ intersects every inclusionwise minimal $d$-outlier set of $\Xcal$.
\end{lemma}



\begin{proof}
Assume that the distance space $\Xcal=(X,\dist)$ does not admit a $d$-embedding. Note that, in particular, this means that $|X|\geq 3$. We then do the following. 
% run the following subroutine.


\begin{mybox}
\begin{enumerate}\item Set $A:=\{p\}$ for an arbitrary point $p\in X$.


\item While 

$|A|\leq d$, do the following:
\begin{enumerate}
 \item If there is a point $x\in X\setminus A$ such that $(A\cup \{x\},\dist)$ is not $|A|$-embeddable,  then set $\hat A:=A\cup\{x\}$ and return $\hat A$. 


\item If there is a point $x\in X\setminus A$ such that $A\cup\{x\}$ is independent, then set $A:=A\cup\{x\}$ and continue the loop, else exit the loop.
\end{enumerate}
\item If there are two distinct points $x,y\in X\setminus A$ such that $(A\cup \{x,y\},\dist)$ is not $(|A|-1)$-embeddable, then $\hat A:=A\cup\{x,y\}$ and return $\hat A$.
\end{enumerate}
\end{mybox}

Clearly, the algorithm runs in polynomial time. Since the while loop has at most $d$ iterations, the set $A$ when the loop is exited has size at most $d+1$ and so, the returned set~$\hat A$ has size at most $d+3$. 
% 
\longversion{

Let us now argue that the algorithm is correct. 

Suppose that the set $\hat A$ is returned in Line 2(a). Since the loop invariant is that $A$ is independent, it follows that if $(\hat A,\dist)$ is $d$-embeddable, it must be $|A|$-embeddable (by \Cref{lem:incrementDimension}), which is not the case by construction. Since embeddability of a distance space into $\mathbb{R}^d$ is closed under deletion of points, we have that $(\hat A,\dist)$ is not $d$-embeddable
and therefore, $\hat A$ must intersect every minimal $d$-outlier set of $\Xcal$.


Now, assume that $\hat A$ is not returned in Line 2(a). 
When we exit the while loop, $A$ is independent. Moreover, either $|A|=d+1$ or for every point $x\in X\setminus A$, $(A\cup \{x\},\dist)$ is 
$|A|$-embeddable but not strongly $|A|$-embeddable  
and so, it is strongly $(|A|-1)$-embeddable. Furthermore, recall that $(X,\dist)$ is not $d$-embeddable. Then, it is also not $(|A|-1)$-embeddable since $A$ has size at most $d+1$.  
So, by \Cref{equivalence}, there exist points $x$ and $y$ that satisfy the check in Line 3 and so, the set $\hat A$ will be returned in this line.


Consider a minimal $d$-outlier set $O$ of $\Xcal$. It is sufficient to argue that if $\hat A$ is disjoint from $O$, then $(X\setminus O,\dist)$ is  $(|A|-1)$-embeddable. This would be a contradiction to our construction of $\hat A$ and \Cref{equivalence}. Suppose that $\hat A$ is disjoint from $O$ and $(X\setminus O,\dist)$ is not $(|A|-1)$-embeddable. Then, it must be the case that $(X\setminus O,\dist)$ is strongly $d'$-embeddable for some $|A|\leq d'\leq d$ and  we would have extended the set $A$ to a larger independent set in Line 2(b) (by  \Cref{prop:matroid}). 
}
\end{proof}



We can now use \Cref{lem:blackBoxObstruction} as a subroutine in the greedy approximation for the minimization variant of {\em unweighted} {\EEO}. 



\begin{lemma}\deferProof{}\label{lem:greedy}
There is a polynomial-time algorithm that, given a distance space $\Xcal=(X,\dist)$ and an integer $d\geq 1$, outputs a set of points $A$ of size at most $(d+3)\cdot \opt$ such that $(X\setminus A,\dist)$ is embeddable into $\mathbb{R}^d$ where $\opt$ is the size of a smallest $d$-outlier set. 
\end{lemma}



\longversion{
\begin{proof}
Using \Cref{lem:blackBoxObstruction}, we iteratively construct disjoint sets $A_1,A_2,\ldots$ of at most $d+3$ points each such that each set should contain at least one outlier, that is, a point of any feasible solution to the instance and finally output the union of these sets.
Precisely, set $A_0=\emptyset$ and for every $i>0$, to compute $A_i$, we delete $A_1,\dots, A_{i-1}$ from $X$ and invoke \Cref{lem:blackBoxObstruction} on the remaining points. Because each set $A_i$ ($i>0$) contains at least one outlier and has size at most $d+3$, we obtain that the algorithm outputs a set of vertices $A$ of size at most $(d+3)\cdot \opt$ such that $(X\setminus A,\dist)$ is embeddable into $\mathbb{R}^d$. Because embeddability can be checked in polynomial time by~\Cref{prop:realization} and the algorithm of \Cref{lem:blackBoxObstruction} runs in polynomial time, we conclude that the overall running time of the algorithm is polynomial. This completes the proof. 
\end{proof}
}

\subsection{Compression}\label{subseccompression}

We are now ready to give the compression algorithm for {\WEEO}. 



\begin{proof}[Proof of \Cref{thm:kernel}]
Let $(\Xcal=(X,\dist),\woutl,\wmod,W,\koutl,\kmod,d)$ be an instance of \WEEO. First, we preprocess the instance to reduce the number of points and then we explain how to reassign the weights.

Notice that if $(\Xcal,\woutl,\wmod,W,\koutl,\kmod,d)$ is a yes-instance, then it is possible to delete ${k=\koutl+\kmod}$ points to obtain a distance space embeddable in $\mathbb{R}^d$. 
In the first step of our algorithm, we call the algorithm from \Cref{lem:greedy} for the instance $(\Xcal,k,d)$ of \EEO{} {\em without} weights. 
This algorithm outputs a set of points $A$ of size at most $(d+3)\cdot \opt$ such that $(X\setminus A,\dist)$ is embeddable into $\mathbb{R}^d$ where $\opt$ is the minimum number of outliers. If $|A|>(d+3)k$ then we conclude that $(\Xcal,\woutl,\wmod,W,\koutl,\kmod,d)$ is a no-instance of \WEEO and stop. From now on, we assume that~$|A|\leq (d+3)(\koutl+\kmod)$. 

Let $Y=X\setminus A$.
We first show that if $Y$ has bounded size, then we can return the original instance of the problem and stop.

\begin{reduction}\label{red:small}
If $|Y|\leq 2(\koutl+2\kmod)(d+1)^2$ then return  $(\Xcal,\woutl,\wmod,W,\koutl,\kmod,d)$\longversion{ and stop}. \end{reduction}

We can apply this rule because if $|Y|\leq 2(\koutl+2\kmod)(d+1)^2$ then $|X|=|Y|+|A|\leq 
2(\koutl+2\kmod)(d+1)^2+(\koutl+\kmod)(d+3)\leq 5(\koutl+\kmod)(d+3)^2 = \Oh((kd)^2)$.
From now on, we assume that $|Y|>2(\koutl+2\kmod)(d+1)^2$.

Because $A$ is a feasible solution to \EEO, $(Y,\dist)$ can be embedded into $\mathbb{R}^d$. In the subsequent steps, we may delete some points in $A$ and reduce the parameter $\koutl$.  This may result in a trivial instance which we solve by applying the following rule whenever possible.

\begin{reduction}\label{rule:stop}
If $\koutl<0$ then return a no-answer and stop. If $\koutl\geq 0$ and $A=\emptyset$ then return a yes-answer and stop. 
\end{reduction}

We greedily partition $Y$ into sets $Y_1,\ldots,Y_\ell$ of size at most $d+1$ such that each~$Y_i$ is an inclusion-maximal independent set of points of $Y\setminus\bigcup_{j=1}^{i-1}Y_j$, that is, $Y_i$ is an inclusion-maximal subset such that $(Y_i,\dist)$ is strongly $(|Y_i|-1)$-embeddable. %into~$\mathbb{R}^{|Y_i|-1}$.

Assume that $i\geq 1$ and the sets $Y_1,\ldots,Y_{i-1}$ are already constructed. We set ${Z:=Y\setminus \bigcup_{j=1}^{i-1}Y_j}$. If $Z=\emptyset$, then the partition is constructed. 
If $Z\neq\emptyset$, then we do the following:
\begin{enumerate}
    \item To initiate the construction of $Y_i$, we set $Y_i=\{x\}$ for an arbitrary point $x\in Z$ and set $h=1$.
\item While there is a point $y\in Z\setminus Y_i$ such that 
$Y_i\cup\{y\}$ is independent, 
%$(Y_i\cup\{y\},\dist)$ is strongly embeddable into $\mathbb{R}^{h+1}$, 
set $Y_i:=Y_i\cup\{y\}$ and $h:=h+1$.
\end{enumerate}
Because $Y$ is $d$-embeddable, $Z$ is strongly $t$-embeddable for some $t\leq d$ and contains an independent set of size $t$ by \Cref{thm:Blumental}. By~\Cref{prop:matroid}, the described procedure will construct a set $Y_i$ of size $t+1\leq d+1$ such that $(Y_i,\dist)$ is strongly $t$-embeddable.
% into $\mathbb{R}^t$. 
Notice that by~\Cref{prop:matroid}, $Y_i$ is a metric basis for $(Z,\dist)$.



