%    \item \textbf{Second Algorithm (\sf{Alg-2}):} Given an independent set $Z$ of size at most $d+1$ (initially $Z = \emptyset$), we aim for a solution disjoint from $Z$. If an element $z$ increases $Z$’s embedding dimension, we branch by either deleting $z$ (reducing $k$) or adding $z$ to $Z$. If no such $z$ exists, we identify two elements, $z_1$ and $z_2$, where at least one belongs to the solution, and branch on each while reducing $k$. This algorithm runs in $2^{k+d} \cdot n^{O(1)}$.
%\end{enumerate}
