\item For $i=1$ to $d+2$ do as follows. 
\begin{enumerate}
\item Create an instance of the {\sc Vertex Cover} problem on graph $G_{\sf comp}^i$, where $V(G_{\sf comp}^i)= {\cal C}_{\sf comp} ^i$, and there is an edge between two elements $x,y \in {\cal C}_{\sf comp} ^i$  if they are an incompatible pair. 
Let $O_i$ denote a minimum sized vertex cover of $G_{\sf comp}$. 
\item Using a known factor-$2$ approximation for {\sc Vertex Cover}, obtain a set 
 $Q_i$ such that $|Q_i|\leq 2 |O_i|$. 
\item $A_i:= Q_i \cup {\cal C}^{i}_{\sf incomp}\cup {\cal C}^{i}_{\sf def}$.
\end{enumerate}
\item Compute $ i^{\star} = \arg\min_{i \in [d+2]} |A_i|$. 
\item Return $A_{i^{\star}}$. 
\end{enumerate}
 \end{mybox}



\begin{claim}\deferProof{}\label{claim:approxAnalysis} Let $\ell \in [d+1]$ be the least integer such that  for all $j<\ell$, it holds that  $$|{\cal C}_{\sf incomp}^j \cap S_{\sf opt}| <  \frac{|{\cal C}_{\sf incomp}^j|}{2}. $$
Then, $A_\ell$ is a factor-2 approximation with probability at least $\frac{1}{2^{\ell}}$.
\end{claim}

\longversion{
\begin{proof}



We  have two cases for $\ell$ depending on whether or not the inequality in the premise of the claim 
holds also at $\ell$. \\ 

\noindent
{\bf Case 1:}   $$|{\cal C}_{\sf incomp}^\ell \cap S_{\sf opt}| <   \frac{|{\cal C}_{\sf incomp}^\ell|}{2}. $$

In this case, $\ell$ must be $d+1$.  By Claim~\ref{claim:approxAlgo}, the probability that $U_{d+1} \subseteq X^\star$ and  $U_{d+1}$ is an independent set of size $d+1$ is at least $\frac{1}{2^{d+1}}$. 


By construction (see {\sf Alg-3}), ${\cal C}_{\sf comp}^{d+2}$ and ${\cal C}_{\sf def}^{d+2}$ partition the set $X\setminus U_{d+1}$ (since at $i=d+2$, $d$-embeddability is the same as $(i-2)$-embeddability). 
% By \Cref{clm:prepare}~(3), we have that $U_{d+1}$ is an independent set of size $d+1$.
Moreover, from \Cref{clm:prepare}~(2), $S_{\sf opt}$ contains ${\cal C}^{d+2}_{\sf def}$, which is also contained in $A_{d+2}$ by definition. This implies that the size of $A_{d+2}\setminus {\cal C}^{d+2}_{\sf def}$ is $|Q_{d+2}|    \leq  2|O_{d+2}|$. Hence, we conclude that $|A_{d+2}| \leq  2 |S_{\sf opt}|$. 

\medskip
\noindent
{\bf Case 2:}  $$|{\cal C}_{\sf incomp}^\ell \cap S_{\sf opt}| \geq   \frac{|{\cal C}_{\sf incomp}^\ell|}{2}. $$

  By Claim~\ref{claim:approxAlgo}, the probability that $U_{\ell-1} \subseteq X^\star$ and  $U_{\ell-1}$ is an independent set of size $\ell-1$ is at least $\frac{1}{2^{\ell-1}}\geq \frac{1}{2^{d+1}}$. 

% $\ell< d+1$. In this case, we have: 

%  $$|{\cal C}_{\sf incomp}^\ell \cap S_{\sf opt}| \geq   \frac{|{\cal C}_{\sf incomp}^j|}{2}. $$

Consider the approximate solution $A_\ell$ we constructed. Observe that $S_{\sf opt} \cap {\cal C}_{\sf comp}^\ell $ is a vertex cover of $G_{\sf comp}^\ell$. Moreover, from \Cref{clm:prepare}~(2), $S_{\sf opt}$ contains ${\cal C}^{\ell}_{\sf def}$, which is also contained in $A_\ell$ by definition.

This implies that the size of $A_\ell\setminus {\cal C}^{\ell}_{\sf def}$ is:
\begin{eqnarray*}
|Q_\ell  \cup {\cal C}_{\sf incomp}|   & \leq & 2|O_\ell| + 2 |{\cal C}_{\sf incomp}^\ell \cap S_{\sf opt}|   \\
& \leq & 2 | S_{\sf opt} \cap {\cal C}_{\sf comp}^\ell| + 2 |{\cal C}_{\sf incomp}^\ell \cap S_{\sf opt}| \\
& = & 2 |S_{\sf opt}\setminus {\cal C}^{\ell}_{\sf def}| \text{ (Since ${\cal C}_{\sf comp}^\ell \cap {\cal C}_{\sf incomp}^\ell = \emptyset$)}
\end{eqnarray*}

Hence, we conclude that $|A_\ell| \leq  2 |S_{\sf opt}|$.  
% Since we return a minimum size solution among 
% approximate solutions \( A_i \), each corresponding to \( U_i \), we are guaranteed that $|A|\leq |A_\ell| \leq  2 |S_{\sf opt}| $. 
\end{proof}
}

Since we compute \( i^{\star} = \arg\min_{i \in [d+2]} |A_i| \) and return $A_{i^{\star}}$,  by \Cref{claim:approxAnalysis} we are guaranteed that $|A_{i^{\star}}| \leq  2 |S_{\sf opt}| $ with probability at least $\frac{1}{2^{d+1}}$. 



% \smallskip
% \noindent 
% {\bf Probability Analysis.} The probability that we return a factor-$2$ approximate solution is lower bounded by the probability that $U_{\ell-1} \subseteq X^\star$ and  $U_{\ell-1}$ is an independent set of size $\ell-1$. By Claim~\ref{claim:approxAlgo} this happens with probability at least $\frac{1}{2^{\ell-1}}$. Thus, the algorithm returns a factor $2$-approximate solution with probability at least  $\frac{1}{2^{\ell-1}}$. 

\smallskip
\noindent 
{\bf Running Time Analysis.} \longversion{ Clearly, the algorithm runs in polynomial time. } We have already argued that we succeed with probability $\frac{1}{2^{d+1}}$.  Thus, we can boost the success probability by independently running our polynomial-time algorithm $2^{d+1}$ times and returning the minimum size solution among these runs. Thus, the probability that the algorithm fails in all of the independent runs is upper bounded by 
%\shortversion{$(1-\frac{1}{2^{d+1}})^{2^{d+1}} \leq 1- \frac{1}{e}$.}
\[\left(1-\frac{1}{2^{d+1}}\right)^{2^{d+1}} \leq 1- \frac{1}{e}.\]
Thus the algorithm succeeds with probability $1-(1/e) \geq 1/2$. 

Moreover, the total running time is upper bounded by $2^{d} n^{\Oh(1)}$. 
\end{proof}









