\begin{figure}[t]
\includegraphics[height=4cm]{SpeedByStudy.pdf}
\includegraphics[height=4cm]{SpeedBySite.pdf}
\caption{Boxplots on the distributions for $\boldsymbol{Speed}$ by study and site--- diamonds indicate the mean values.}\label{fig:speed}
\vspace{-0.5cm}
