\section{Preliminaries, Model and Problem Statement}
\label{sec: pre_mod_stat_of_prob}

\vspace{-0.15cm}
\subsection{Notations}
\vspace{-0.2cm}
We denote the sets of real numbers, positive real numbers, rational numbers, integers, non-negative integers and positive integers by $\mR$, $\mRdplus$, $\mQ$, $\mZ$, $\mN$ and $\mNplus$, respectively. \Glspl{rv} (resp., deterministic values) are denoted by uppercase letters, e.g., $X$ (resp., lowercase letters, e.g., $x$). Random processes and functions are denoted by stating the time variable in brackets, using round brackets for \gls{ct} and square brackets for \gls{dt}, e.g., $X(t)$, $t \in \mR$, is a \gls{ct} random process, and $x[i]$, $i \in \mZ$ is a \gls{dt} deterministic function. 
%in \gls{ct} (resp., \gls{dt}) are denoted by lowercase letters with round (resp., square) brackets, e.g., $x(t)$, $t \in \mR$ (resp., $x[i]$, $i \in \mZ$). 
Matrices are denoted by sans serif uppercase letters, e.g., $\mmat{A}$, and $(\mmat{A})_{u, v}$, $u, v \in \mN$, denotes its element in the $u$-th row and the $v$-th column. The transpose of a matrix $\mmat{A}$ is denoted by $\mmat{A}^{T}$. For a square matrix $\mmat{B}$, $\det(\mmat{B})$ and $\tr\{\mmat{B}\}$ denote its determinant and its trace, respectively. $\mmat{B} \succ 0$ denotes it is positive definite. Boldface uppercase (resp., lowercase) letters denote column random (resp., deterministic) vectors, e.g., $\mvec{X}$ (resp., $\mvec{x}$). $\zerovec^{k}$ denotes a column all-zero vector of length $k$. %For a column random vector $\mvec{X}$, $\mmvec{\mvec{X}}$ and $\macrmat{\mvec{X}}$ denote its mean vector and its autocorrelation matrix, respectively. 
$\mvec{X} \sim \mGd(\mmvec{\mvec{X}}, \macvmat{\mvec{X}})$ denotes a real Gaussian column random vector $\mvec{X}$ with a mean vector $\mmvec{\mvec{X}}$ and an autocovariance matrix $\macvmat{\mvec{X}}$. $\mE\{\cdot\}$, $\mVar\{\cdot\}$, $|\cdot|$, $\lfloor \cdot \rfloor$, $\lceil \cdot \rceil$, $\log(\cdot)$, $\Pr(\cdot)$, and $p_{X}(\cdot)$ denote the expectation, the variance, the magnitude, the floor function, the ceiling function, the base-$2$ logarithm, the probability and the \gls{pdf} of a continuous \gls{rv} $X$, respectively. We define $a^{+} \triangleq \max\{0, a\}$ and $j = \sqrt{-1}$. 
%For a sequence of real functions $\{f_{n}\}$, $n \in \mN$, and a real function $f$, $\ulim_{n \to \infty} f_{n} = f$ denotes that the sequence $\{f_{n}\}$ uniformly converges to $f$. 
The differential entropy and the mutual information are denoted by $h(X)$ and $I(X; Y)$, respectively, where $X$ and $Y$ are real \glspl{rv}.

\vspace{-0.05cm}
\subsection{Wide-Sense Cyclostationary Processes}


We next review several definitions relating to \gls{wscs} processes, beginning with the formal definition of such processes:

\begin{definition}[\gls{wscs} processes {\cite[Def.~17.1]{giannakis1999}, \cite[Sec.~3.2]{gardner2006}}]
    A real \gls{ct} (resp., \gls{dt}) random process $X(t)$, $t \in \mR$ (resp., $X[i]$, $i \in \mZ$) is \emph{\gls{wscs}} if both its mean $m_{X}(t) \triangleq \mE\{X(t)\}$ (resp., $m_{X}[i] \triangleq \mE\{X[i]\}$) and its \gls{af} $c_{X}(t, \lambda) \triangleq \mE\{X(t) \cdot X(t + \lambda)\}$ (resp., $c_{X}[i, \Delta] \triangleq \mE\{X[i] \cdot X[i + \Delta]\}$) are periodic in time $t$ (resp., $i$) with some period $T_{c} \in \mRdplus$ (resp., $N_{c} \in \mN^{+}$) for any lag $\lambda \in \mR$ (resp., $\Delta \in \mZ$), i.e., $c_{X}(t, \lambda) = c_{X}(t + T_{c}, \lambda)$ (resp., $c_{X}[i, \Delta] = c_{X}[i + N_{c}, \Delta]$).
\end{definition}

%\gls{dt} \gls{wsacs} processes are defined following the definition of 
Next, we define \gls{dt} almost periodic functions as follows:

\begin{definition}[\gls{dt} almost periodic functions {\cite{bohr2018}, \cite[Def.~11]{guan2013}}]
\label{def:almost_periodic_function}
    A real, \gls{dt} deterministic function $f[i]$, $i \in \mZ$, is said to be \emph{almost periodic}, if for any $\epsilon \in \mRdplus$, there exists an associated number $l_{\epsilon} \in \mNplus$ such that for any $\alpha \in \mZ$, there exists $\Delta \in [\alpha, \alpha + l_{\epsilon})$, such that $\sup_{i \in \mZ} |f(i + \Delta) - f(i)| < \epsilon$.
\end{definition}

With Def.~\ref{def:almost_periodic_function} we can define \gls{dt} \gls{wsacs} processes as follows:

\begin{definition}[\gls{dt} \gls{wsacs} processes {\cite[Def.~17.2]{giannakis1999}, \cite[Sec.~3.2.2]{gardner2006}}]
    A real \gls{dt} random process $X[i]$, $i \in \mZ$, is called  \emph{\gls{wsacs}} if both its mean $m_{X}[i]$ and its \gls{af} $c_{X}[i, \Delta]$ are \emph{almost periodic} in time $i$ for any lag $\Delta \in \mZ$.
\end{definition}

\vspace{-0.05cm}

\subsection{Rate-Distortion Theory}
Consider first the definition of a lossy source code, stated as follows:

\begin{definition}[Lossy source code {\cite[Sec.~10.2]{cover2006}, \cite[Sec.~3.6]{el_gamal2011}}]
    A \emph{lossy source code} $(m, l)$, where $m$ is the size of the \emph{message set} and $l$ is the \emph{blocklength}, consists of: An \emph{encoder} $f_{l}(\cdot)$, that maps a block of $l$ source symbols $\{x[i]\}_{i = 0}^{l - 1} \equiv \xvecl$, over corresponding alphabets $\{\mset{X}_{i}\}_{i = 0}^{l - 1} \equiv \Xsetl$, into an index selected from a message set of size $m$, i.e., $f_{l}(\cdot): \Xsetl \mapsto \{0, 1, \cdots, m - 1\}$; and a \emph{decoder} $g_{l}(\cdot)$, that assigns a block of $l$ reconstruction symbols $\{\mr{x}[i]\}_{i = 0}^{l - 1} \equiv \xrvecl$, over corresponding alphabets $\{\mrset{X}_{i}\}_{i = 0}^{l - 1} \equiv \rXsetl$, to each received index, i.e., $g_{l}(\cdot): \{0, 1, \cdots, m - 1\} \mapsto \rXsetl$, where  $\frac{1}{l} \log m \triangleq R$ is called the {\em code rate}.
\end{definition}

The mismatch between the source symbol $x$ and its reconstruction $\mr{x}$ is measured using a \emph{distortion function} $d(x, \mr{x})$; the distortion between a block of $l$ source symbols 
%$\{x[i]\}_{i = 0}^{l - 1} \equiv \xvecl$ 
and its block reconstruction 
%$\{\mr{x}[i]\}_{i = 0}^{l - 1} \equiv \xrvecl$ 
is defined as $\maa{d}(\xvecl, \xrvecl) \triangleq \frac{1}{l} \sum_{i = 0}^{l - 1} d\big(x[i], \mr{x}[i]\big)$. 
When considering compression of sources with continuous alphabets, a commonly used distortion metric is the \emph{squared-error} defined as $d_{se}(x, \mr{x}) \triangleq (x - \mr{x})^2$. An \emph{achievable} rate-distortion pair is defined as follows:

\begin{definition}[Achievable rate-distortion pair {\cite[Sec.~10.2]{cover2006}, \cite[Sec.~3.6]{el_gamal2011}}]
\label{def: achi_rate_dist_pair}
    For a given distortion constraint $D$, if there exists a sequence of $(2^{lR}, l)$ lossy source code  for which
        \vspace{-0.05cm}
    \begin{equation*}
        \limsup_{l \to \infty} \mE\Bigg\{\maa{d}\bigg(\Xvecl, g_{l}\Bigl(f_{l}\big(\Xvecl\big)\Big)\bigg)\Bigg\} \leq D,
        \vspace{-0.05cm}
    \end{equation*}
    then the rate-distortion pair $(R, D)$ is said to be \emph{achievable}.
\end{definition}

Finally, the \gls{rdf} is defined as follows:

\begin{definition}[\gls{rdf} {\cite[Sec.~IV-A]{berger1998}, 
%\cite[Sec.~10.2]{cover2006}, 
\cite[Sec.~3.6]{el_gamal2011}}]
\label{def: rdf}
    Given a distortion constraint $D$, the \gls{rdf} $R(D)$ is the infimum of all code rates $R$ for which the rate-distortion pair $(R, D)$ is achievable.
\end{definition}

\subsection{Problem Formulation}
\label{sec: prob_form_mod}
Consider a \emph{zero-mean} \gls{ct} \gls{wscs} Gaussian source process $X_{c}(t)$, $t \in \mR$, with an \gls{af} $c_{X_{c}}(t, \lambda)$
%\triangleq \mE\{X_{c}(t) \cdot X_{c}(t + \lambda)\}$, 
where $\lambda \in \mR$ denotes the lag. $c_{X_{c}}(t, \lambda)$ is \emph{uniformly continuous} and \emph{bounded} in $t, \lambda \in \mR$, 
%and (i.e., $\exists \gamma \in \mRdplus$, s.t. $|c_{X_{c}}(t, \lambda)| \leq \gamma$, $\forall t, \lambda \in \mR$) \cite[Sec.~3.2.1]{gardner2006}, 
and has a period of $T_{c} \in \mRdplus$ in $t$: $c_{X_{c}}(t, \lambda) = c_{X_{c}}(t + T_{c}, \lambda)$, $|c_{X_{c}}(t, \lambda)| \leq \gamma\in\mR$, $\forall t, \lambda \in \mR$. The random process $X_{c}(t)$ is a \emph{finite-memory} process with a maximal autocorrelation length $\lambda_{c} \in \mRdplus$, i.e., $c_{X_{c}}(t, \lambda) = 0$, $\forall |\lambda| > \lambda_{c}$. $X_{c}(t)$ is uniformly sampled with the sampling interval $T_{s}(\epsilon) \triangleq \frac{T_{c}}{p + \epsilon}$, where $p \in \mNplus$ and $\epsilon \in [0, 1)$. The sampled process is $\Xepphi[i] \triangleq X_{c}\bigl(i \cdot T_{s}(\epsilon) + \phi_{s}\bigl)$, where $i \in \mN$ and $\phi_{s} \in [0, T_c)$ denotes the \emph{initial sampling phase}. The sampling interval satisfies $T_{s}(\epsilon) %\triangleq \frac{T_{c}}{p + \epsilon} 
< \lambda_{c}$ which implies that $c_{\Xepphi}[i, \Delta] = 0$, $\forall |\Delta| \geq \Big\lceil \frac{(p + 1) \cdot \lambda_{c}}{T_{c}}\Big\rceil \triangleq \tau_{c} < \infty$. Thus,  $\Xepphi[i]$ is a \emph{finite-memory} process with a maximal autocorrelation length $\tau_{c}$.

The statistics of $\Xepphi[i]$ depend on the ratio between $T_{s}(\epsilon)$ and $T_{c}$: When $\epsilon \in \mQ$, i.e., $\exists u, v \in \mNplus$, s.t. $\epsilon = \frac{u}{v}$, then $\Xepphi[i]$ is a \gls{wscs} process with a period of statistics $N_{c} = p \cdot v + u \triangleq p_{u, v}$. This is referred to as \emph{synchronous sampling}; when $\epsilon \notin \mQ$, 
%implying that $\epsilon$ cannot be expressed as the ratio of two positive integers, 
the sampled process is a \gls{wsacs} process. This is referred to as \emph{asynchronous sampling}.
In this work, a {\em finite and bounded delay between the processing} of subsequently sampled sequences is allowed. 
%which brings two changes: First, all sequences are statistically independent, as the delay is longer than the maximal autocorrelation length of $X_{c}(t)$; second, 
This delay facilitates the synchronization of the initial sampling phase of every sequence to the optimal phase within $[0, T_{c})$, in the sense of minimizing the overall compression rate. This setup differs from our previous work \cite{tan2024}, in which processing delay was not allowed. 

\subsection{Relevant Information-Spectrum Definitions}
%We introduce related notions about information-spectrum framework, beginning with the definition of 
In this work we use the limit superior in probability, which is defined next:

\begin{definition}[Limit superior in probability {\cite[Def.~1.3.1]{han2010}}]
\label{def: limsup_in_prob}
    For a sequence of real \glspl{rv} $\{X_{i}\}_{i = 0}^{\infty}$, its \emph{limit superior in probability} is defined as
    \begin{equation}
        \limsupp_{i \to \infty} {X_{i}} \triangleq \inf\Big\{\alpha \in \mR | \lim_{i \to \infty} \Pr\{X_{i} > \alpha\} = 0\Big\} \triangleq \alpha_{0}.
    \end{equation}
\end{definition}
    \vspace{-0.3cm}


The spectral sup-mutual information rate is now defined as follows:

\begin{definition}[Spectral sup-mutual information rate {\cite[Def.~3.5.2]{han2010}}]
    The \emph{spectral sup-mutual information rate} of two sequences of real continuous \glspl{rv}, $\{X[i]\}_{i = 0}^{l - 1} \equiv \Xvecl$ and $\{Y[i]\}_{i = 0}^{l - 1} \equiv \Yvecl$, is defined as
    \begin{equation*}
        \ssmir(\Xvecinf, \Yvecinf) \triangleq \limsupp_{l \to \infty} \frac{1}{l} \log \frac{p_{\Yvecl | \Xvecl} (\Yvecl | \Xvecl)}{p_{\Yvecl}(\Yvecl)}.
    \end{equation*}
\end{definition}
    \vspace{-0.2cm}

In our proof of the main result we use an \gls{rdf} characterization for arbitrary \gls{dt} processes subject to a uniform integrability condition on the loss function. Uniform integrability is defined as follows:

% \begin{definition}[Uniform integrability {\cite[Def.~6.16]{klenke2014}}]
    % For a sequence of real continuous \glspl{rv} $\{X_{i}\}_{i = 0}^{\infty}$, if it holds that $\lim_{u \to \infty} \sup_{i \geq 0} \int_{x: |x|\geq u} f_{X_i}(x) |x| \mtxt{d} x = 0$, then the sequence $\{X_{i}\}_{i=0}^{\infty}$ is said to be \emph{uniformly integrable}.
% \end{definition}

\begin{definition}[Uniform integrability {\cite[Eqn.~(25.10)]{Bill86probabilitymeasure}}]
    A sequence of real  \glspl{rv} $\{X_{i}\}_{i = 0}^{\infty}$, with a common probability measure $P$  is said to be \emph{uniformly integrable} if $\lim_{u \to \infty} \sup_{i \geq 0} \int_{|X_i|\geq u} |X_i| \mtxt{d} P = 0$. %, then the sequence $\{X_{i}\}_{i=0}^{\infty}$ 
\end{definition}

Using the definitions above, it follows that with \emph{fixed-length coding} and with the \emph{average distortion criterion}, the \gls{rdf} for compressing an arbitrary \gls{dt} process is stated as follows:

\begin{theorem}[The \gls{rdf} for an arbitrary \gls{dt} process {\cite[Thm.~5.5.1]{han2010}}]
\label{thm: rdf_arb_dt_proc}
    Consider an arbitrary, real-valued \gls{dt} process $X[i]$, $i \in \mN$. Let $\{X[i]\}_{i = 0}^{l - 1} \equiv \Xvecl$ and $\{\mr{X}_{i}\}_{i = 0}^{l - 1}\equiv \rXvecl$ denote the blocks of $l$ source symbols 
    and of $l$ reconstruction symbols, respectively, and let  %between $\Xvecl$ and $\rXvecl$ by 
    $F_{\Xvecl, \rXvecl}$ denote their joint \gls{cdf}. If 
    there exists a \emph{deterministic reference word} $\{r_{i}\}_{i = 0}^{l - 1} \equiv \rvecl$, such that the sequence $\{\maa{d}(\Xvecl, \rvecl)\}_{l = 1}^{\infty}$ is \emph{uniformly integrable}, then 
    the \gls{rdf} for compressing $X[i]$ is
    \begin{equation}
    \label{eqn: rdf_arb_dt_sou_proc}
        R(D) = \inf_{\substack{F_{\Xvecinf, \rXvecinf}: \\ \limsup_{l \to \infty} \mE\{\maa{d}(\Xvecl, \rXvecl)\} \leq D}} \ssmir\big(\Xvecinf, \rXvecinf\big).
    \end{equation}
        \vspace{-0.45cm}
\end{theorem}

Recalling the Gaussianity of $X_{c}(t)$ and the boundedness of $c_{X}(t, \lambda)$, in Lemma~\ref{lem:Unif_Integ}, 
we establish the uniform integrability of the distortion for the considered scenario, which 
facilitates the use of Thm.~\ref{thm: rdf_arb_dt_proc} in our analysis:

\begin{lemma}
    \label{lem:Unif_Integ}
    Consider a sequence of $l$ real Gaussian \glspl{rv} $\{X_{i}\}_{i = 0}^{l - 1} \equiv \Xvecl$, for which there exists an upper bound for variances of all its elements (i.e., $\exists \alpha < \infty$, s.t. $\mVar\{X_{i}\} \leq \alpha$ for $0 \leq i \leq l - 1$). Then, the sequence of \gls{mse} distortion values between $\Xvecl$ and the all-zero sequence $\zerovec^{l}$ w.r.t. $l$, denoted by $\big\{\maa{d}_{se}(\Xvecl, \zerovec^{l})\big\}_{l = 1}^{\infty}$, is uniformly integrable.
\end{lemma}

\begin{proof}
    The proof is detailed in Appendix~\ref{sec: pf_lem_uni_intg_app}.
    % The proof is omitted due to space limitations. Please refer to \cite{RDF_WSACS_Full_Ver} for the details.
\end{proof}

