As detailed in Sec.~\ref{sec: prob_form_mod}, when $\epsilon \in \mQ$, $\Xepphi[i]$ is a \gls{wscs} process, whose \gls{rdf} was derived in \cite[Thm.~1]{kipnis2018}. Let $\epsilon_{n} \triangleq \frac{\lfloor n \cdot \epsilon \rfloor}{n}$, $n \in \mNplus$, and let $T_{s}(\epsilon_{n}) \triangleq \frac{T_{c}}{p + \epsilon_{n}}$ denote the sampling interval. As $\epsilon_{n}\in\mQ$,  sampling is synchronous and the sampled process $\Xepnphi[i] \triangleq X_{c}\big(i \cdot T_{s}(\epsilon_{n}) + \phi_{s}\big) = X_{c}\big(\frac{i \cdot T_{c}}{p + \epsilon_{n}} + \phi_{s}\big)$ is a \gls{wscs} process
%. As $\epsilon \in [0, 1)$, implying that $\epsilon_{n} \triangleq \frac{\lfloor n \cdot \epsilon \rfloor}{n} \leq 1$, we obtain 
with a maximal correlation length upper bounded by 
$\tau_{c} \triangleq \big\lceil \frac{(p + 1) \cdot \lambda_{c}}{T_{c}} \big\rceil \geq \big\lceil \frac{(p + \epsilon_{n}) \cdot \lambda_{c}}{T_{c}} \big\rceil$. 
%This follows that $\Xepnphi[i]$ is a \emph{finite-memory} process with the maximal autocorrelation length $\tau_{c}$.

Consider a $p_{n}$-dimensional \gls{dt} stationary process $\mvec{X}_{\epsilon_{n}, \phi_{s}}^{p_{n}}[i]$, $i \in\mN$, obtained from $\Xepnphi[i]$ by setting its $m$-th subprocess to $\big(\Xvecepnphipn[i]\big)_{m} = \Xepnphi[i \cdot N_{c} + m]$, $m = 0, 1, \cdots, p_{n} - 1$. The autocorrelation matrix of $\mvec{X}_{\epsilon_{n}, \phi_{s}}^{p_{n}}[i]$ is
    \vspace{-0.2cm}
\begin{equation}
    \label{eqn:WSCS_RDF1}
    \CXvecepnphipn[\Delta] \triangleq \mE\bigg\{\Xvecepnphipn[i] \cdot \Big(\Xvecepnphipn[i + \Delta]\Big)^{T}\bigg\},
    % \label{eqn:WSCS_RDF1}
\end{equation}
and its \gls{psd} matrix is
\begin{equation}
    \label{eqn:WSCS_RDF2}
    \SXvecepnphipn(f) \triangleq \sum_{\Delta \in \mZ} \CXvecepnphipn[\Delta] \cdot e^{-j 2 \pi f \Delta},
        \vspace{-0.1cm}
\end{equation}
% \end{subequations}
for $-\frac{1}{2} \leq f \leq \frac{1}{2}$. We denote the eigenvalues of $\SXvecepnphipn(f)$ in descending order by $\lamepnphimpn(f)$, $0 \leq m \leq p_{n} - 1$. By \cite[Thm.~1]{kipnis2018}, 
%denoting $\theta$ as the reverse waterfilling threshold, 
the \gls{rdf} for $\Xepnphi[i]$ for a distortion constraint $D$ is
\begin{equation}
\label{eqn:WSCS_RDF}
    R_{\epsilon_{n}}^{\phi_{s}}(D) = \frac{1}{2 p_{n}} \sum_{m = 0}^{p_{n} - 1} \int_{f = -\frac{1}{2}}^{\frac{1}{2}} \!\!\Bigg(\!\log\bigg(\frac{\lamepnphimpn(f)}{\theta}\bigg)\Bigg)^{+} \!\mtxt{d} f,
        \vspace{-0.1cm}
\end{equation}
where $\theta$ is selected such that
\begin{equation}
    % \begin{gather}
    D = \frac{1}{p_{n}} \sum_{m = 0}^{p_{n} - 1} \int_{f = -\frac{1}{2}}^{\frac{1}{2}} \min\Big\{\lamepnphimpn(f), \theta\Big\} \mtxt{d} f.
    % \end{gather}
\end{equation}

As the \gls{rdf} $R_{\epsilon_{n}}^{\phi_{s}}(D)$ depends on $\phi_{s} \in [0, T_{c}\}$, we define
\begin{equation}
\label{eqn:WSCS_RDF_opt}
    R_{\epsilon_{n}}(D) \triangleq \min_{\phi_{s} \in [0, T_{c})} R_{\epsilon_{n}}^{\phi_{s}}(D). 
\end{equation}

In the scenario considered in this work it is assumed that delay of up to $\tau_{c} \cdot T_{s}(\epsilon) + T_{c}$ in \gls{ct} is allowed between subsequently sampled sequences. Then, the \gls{rdf} for $\Xepnphi[i]$ can be obtained as follows:

\begin{theorem}
\label{thm: main_thm}
    Consider the scenario in Sec.~\ref{sec: prob_form_mod}. When a delay of up to $\tau_{c} \cdot T_{s}(\epsilon) + T_{c}$ in \gls{ct} between consecutive sampled sequences is allowed. If the \gls{af} of $X_{c}(t)$ satisfies
    \begin{equation}
    \label{eqn: sdd}
        \min_{0 \leq t < T_{c}} \Bigg\{\! c_{X_{c}}(t, 0) - 2 \cdot \tau_{c} \cdot\! \max_{|\lambda| > \frac{T_{c}}{p + 1}}\! \Big\{\big|c_{X_{c}}(t, \lambda)\big|\Big\}\!\Bigg\}\! \geq\! \gamma_{c} \! > 0,
    \end{equation}
    given a distortion constraint $D \leq \gamma_{c}$, the \gls{rdf} for $\Xepnphi[i]$ is
    \begin{equation}
        \label{eqn:WSACS_RDF}
        R_{\epsilon}(D) = \limsup_{n \to \infty} R_{\epsilon_{n}}(D).
    \end{equation}
\end{theorem}

\begin{proof}
    The proof is detailed in Appendix~\ref{sec: pf_main_thm}.
\end{proof}



