			Z^T,\cdots,Z^T
		\end{matrix} \right] \left[\begin{matrix}
			\alpha_1B^{(1)}&\cdots&O\\
			\vdots&\ddots&\vdots\\
			O&\cdots&\alpha_LB^{(L)}
