Intriguing by \autoref{low rank approximation}, we can find the $r_1+\cdots+r_L$-order low-rank approximation
\begin{align*}
	\hat{\Theta}=\left[\begin{matrix}
		H^{(1)}&\cdots&O\\
		\vdots&\ddots&\vdots\\
		O&\cdots&H^{(L)}
	\end{matrix}\right]
	\left[\begin{matrix}
		\Lambda_{r_1}^{(1)}&\cdots&O\\
		\vdots&\ddots&\vdots\\
		O&\cdots&\Lambda_{r_L}^{(L)}
	\end{matrix}\right]
	\left[\begin{matrix}
		H^{(1)T}&\cdots&O\\
		\vdots&\ddots&\vdots\\
		O&\cdots&H^{(L)T}
	\end{matrix}\right].
\end{align*}
Denote \begin{align*}
	\Lambda_{\tau}=\left[\begin{matrix}
		\Lambda_{r_1}^{(1)}&\cdots&O\\
		\vdots&\ddots&\vdots\\
		O&\cdots&\Lambda_{r_L}^{(L)}
	\end{matrix}\right],
\end{align*}
where $\tau=r_1+\cdots+r_L$ and $r_l=rank\left(\Lambda_{r_l}^{(l)} \right). $ Since the eigenvalue diagonal matrix $\Lambda_\tau$ is composed of positive eigenvalue, it can be represented as $\Lambda_\tau=\Sigma_\tau\Sigma_\tau$, where $\Sigma_\tau$ can be formulated as a block matrix:\\
\begin{align*}
    \Sigma_\tau=\left[\begin{matrix}
        \Sigma_{r_1}^{(1)}&\cdots&O\\
        \vdots&\ddots&\vdots\\
        O&\cdots&\Sigma_{r_L}^{(L)}
    \end{matrix}\right].
\end{align*}



Let $\Phi=\left[\begin{matrix}
	H^{(1)}&\cdots&O\\
	\vdots&\ddots&\vdots\\
	O&\cdots&H^{(L)}
\end{matrix}\right]\Sigma_\tau\in\mathbb{R}^{NL\times\tau}$ , thus $\hat{\Theta}=\Phi\Phi^T$ and \begin{align*}
    \Phi=\left[\begin{matrix}
	H^{(1)}\Sigma_{r_1}^{(1)}&\cdots&O\\
	\vdots&\ddots&\vdots\\
	O&\cdots&H^{(L)}\Sigma_{r_L}^{(L)}
\end{matrix}\right]=\left[\begin{matrix}
	\Phi_1&\cdots&O\\
	\vdots&\ddots&\vdots\\
	O&\cdots&\Phi_L
\end{matrix}\right],
\end{align*} where $\Phi_l=H^{(l)}\Sigma_{r_l}^{(l)}\in\mathbb{R}^{N\times r_l}$ is the representation matrix of $B^{(l)}$ since $\hat{B}^{(l)}=H^{(l)}\Sigma_{r_l}^{(l)}\Sigma_{r_l}^{(l)T}H^{(l)T}\\=H^{(l)}\Lambda_{r_l}^{(l)}H^{(l)T}$. The multi-objective optimization problem \eqref{single obective maximization} can be converted into low-rank approximation of $\Theta$:
\begin{align*}
	&\arg\max\limits_{\substack{Tr(Z^TZ)=1\\ \alpha_1+\cdots+\alpha_L=1\\ \alpha_1>0,\cdots,\alpha_L>0}} \alpha_1Q^{(1)}+\alpha_2Q^{(2)}+\cdots+\alpha_LQ^{(L)}\\
	=&\arg\min\limits_{\substack{\hat{\Theta}\in\mathbb{R}^{NL\times NL}\\
			r(\hat{\Theta})\le \tau}}\left\|\Theta-\hat{\Theta}\right\|_{F}\\
	=&\arg\min\limits_{\substack{\Phi\in\mathbb{R}^{NL\times\tau}\\
			r(\hat{\Phi})\le \tau}}\left\|\Theta-\Phi\Phi^T\right\|_{F}.
\end{align*}
The proof of \autoref{optimal low rank reconstruction} is then completed.
\end{proof}


\begin{proof}[Proof of \autoref{optimal low rank reconstruction2}]
%\paragraph{The Proof of \autoref{optimal low rank reconstruction2}:}
From \autoref{optimal low rank reconstruction}, we know that the matrix $\Theta$ can be approximated by $\hat{\Theta}=\Phi\Phi^T$.
Let 
\begin{align*}
	M=\alpha_1B^{(1)}+\alpha_2B^{(2)}+\cdots+\alpha_LB^{(L)}=\left[\begin{matrix}
		\sqrt{\alpha_1}\bm{I}_N&\cdots&\sqrt{\alpha_L}\bm{I}_N
	\end{matrix}\right]\Theta
	\left[\begin{matrix}
		\sqrt{\alpha_1}\bm{I}_N\\
		\vdots\\
		\sqrt{\alpha_L}\bm{I}_N
	\end{matrix}\right]\in\mathbb{R}^{N\times N}.
\end{align*}
The $\tau$ order rank approximation of M is:
\begin{align*}
	\hat{M}=&\left[\begin{matrix}
		\sqrt{\alpha_1}\bm{I}_N&\cdots&\sqrt{\alpha_L}\bm{I}_N
	\end{matrix}\right]\hat{\Theta}
	\left[\begin{matrix}
		\sqrt{\alpha_1}\bm{I}_N\\
		\vdots\\
		\sqrt{\alpha_L}\bm{I}_N
	\end{matrix}\right]\\
	=&\left[\begin{matrix}
		\sqrt{\alpha_1}\bm{I}_N&\cdots&\sqrt{\alpha_L}\bm{I}_N
	\end{matrix}\right]
	\left[\begin{matrix}
		H^{(1)}&\cdots&O\\
		\vdots&\ddots&\vdots\\
		O&\cdots&H^{(L)}
	\end{matrix}\right]
	\Lambda_{\tau}
	\left[\begin{matrix}
		H^{(1)T}&\cdots&O\\
		\vdots&\ddots&\vdots\\
		O&\cdots&H^{(L)T}
	\end{matrix}\right]
	\left[\begin{matrix}
		\sqrt{\alpha_1}\bm{I}_N\\
		\vdots\\
		\sqrt{\alpha_L}\bm{I}_N
	\end{matrix}\right]\\
	=&\left[\begin{matrix}
		\sqrt{\alpha_1}H^{(1)}&\cdots&\sqrt{\alpha_L}H^{(L)}
	\end{matrix}\right]\Lambda_{\tau}
	\left[\begin{matrix}
		\sqrt{\alpha_1}H^{(1)T}\\
		\vdots\\
		\sqrt{\alpha_L}H^{(L)T}
	\end{matrix}\right].
\end{align*}
Let $\tilde{H}^{(l)}=\sqrt{\alpha_l}H^{(l)}$, then \begin{align*}
    \hat{M}=\left[\begin{matrix}
	\tilde{H}^{(1)}&\cdots&\tilde{H}^{(L)}
\end{matrix}\right]\Lambda_{\tau}
\left[\begin{matrix}
	\tilde{H}^{(1)T}\\
	\vdots\\
	\tilde{H}^{(L)T}
\end{matrix}\right],
\end{align*} where $\tau=r_1+\cdots+r_L$ and $r_l=rank\left(\Lambda_{r_l}^{(l)} \right). $ Since the eigenvalue diagonal matrix $\Lambda_\tau$ is composed of positive eigenvalue, it can be represented as $\Lambda_\tau=\Sigma_\tau\Sigma_\tau$.

Let $\Gamma=\left[\begin{matrix}
	\tilde{H}^{(1)}&\cdots&\tilde{H}^{(L)}
\end{matrix}\right]\Sigma_\tau\in\mathbb{R}^{N\times\tau}$, thus $\hat{M}=\Gamma\Gamma^T$. And the representation matrix $\Gamma$ can be formulated by $\Phi_l$: $\Gamma=\left[\begin{matrix}
\sqrt{\alpha_1}\Phi_1&\sqrt{\alpha_2}\Phi_2&\cdots&\sqrt{\alpha_L}\Phi_L
    \end{matrix}\right]$. The multi-objective optimization problem \eqref{single obective maximization} can be converted into low-rank approximation of $\Theta$ or $M$:
\begin{align*}
	&\arg\max\limits_{\substack{Tr(Z^TZ)=N\\ \alpha_1+\cdots+\alpha_L=1\\ \alpha_1>0,\cdots,\alpha_L>0}} \alpha_1Q^{(1)}+\alpha_2Q^{(2)}+\cdots+\alpha_LQ^{(L)}\\
	=&\arg\min\limits_{\substack{\hat{M}\in\mathbb{R}^{N\times N}\\
			r(\hat{M})\le \tau}}\left\|M-\hat{M}\right\|_{F}\\
	=&
    \arg\min\limits_{\substack{\Gamma\in\mathbb{R}^{N\times\tau}\\
			r(\Gamma)\le \tau}}\left\|M-\Gamma\Gamma^T\right\|_{F}.
\end{align*}
The proof of \autoref{optimal low rank reconstruction2} is then completed.
\end{proof}

\section{Proposed Methods} \label{section: Proposed Method}
\subsection{Independent Graph Embedding Algorithm for Multi-layer Network Community Detection}\label{subsection:Identity Graph Tensor Representation Features}
Graph auto-encoder (GAE) was applied to reconstruct the modularity matrix. % since 2022 \cite{qiu2022vgaer}.  
In this part, we develop a novel GAE-based multi-layer network community detection algorithm.
The graph representation vectors containing community information obtained from the encoder are subsequently applied to reconstruct the modularity tensor.

Based on the modularity tensor optimization problem \eqref{main problem}, we first develop an independent graph embedding-based  modularity tensor reconstruction algorithm (IGE-MTR). Input modularity tensor $B=\left[B^{(1)},\cdots,B^{(L)}\right]$ composed of $L$ layers symmetry modularity matrix and multi-layer adjacent tensor $A=\left[A^1,\cdots,A^L\right]$ into  $L$ layers graph convolutional encoder. The $m$-th graph convolution is formulated as $GCN_m^1\left(A^m,B^{(m)} \right)=\sigma\left(A^mB^{(m)}W_1^m \right),\quad 1\le m\le L $, where $\sigma(\cdot)$ is activation function. Since modularity matrices are always sparse, we choose $\tanh(\cdot)$ as the activation function. 

The encoder consists of two sets of graph convolutional layers, each of which comprises $L$ graph convolution layers and operates feature aggregation and transformation for input matrices $B^{(m)}$ and $A^m$, and outputs L graph representation matrices. A feature fusion operation is performed before being fed into the second graph convolutional module. The outputs of the first graph convolutional module $h_0^1=\tanh(A^1B^{(1)}W_0^1),\cdots,h_0^L=\tanh(A^LB^{(L)}W_0^L)$ are concatenated as $h=concat(h_0^1,\cdots,h_0^L)$. Then input the aggregation feature $h$ into the second set of feature feature fusion operation $GCN_m^2\left(A^m, h \right)=\sigma\left(A^mhW_1^m \right) $. \autoref{fig:Identity Graph Representation Features} exhibits our proposed IGE-MTR algorithm.

\begin{figure}[H]
	\centering
	\begin{minipage}[b]{0.9\textwidth}
		\includegraphics[width=\textwidth]{IGE-MTR.jpg}
		\caption{Multi-layer network community detection (IGE-MTR)}
		\label{fig:Identity Graph Representation Features}
	\end{minipage}
\end{figure}

 The modularity reconstruction effect is evaluated by the sum of the F-norm. From \autoref{optimal low rank reconstruction}
\begin{align*}
    \left\|\Theta-\hat{\Theta}\right\|_F^2=&Tr\left(\sum\limits_{l=1}^{L}\left(B^{(l)}-\hat{B}^{(l)}\right)\left(B^{(l)}-\hat{B}^{(l)}\right)^T\right)\\
    =&\sum\limits_{l=1}^{L}Tr\left(\left(B^{(l)}-\hat{B}^{(l)}\right)\left(B^{(l)}-\hat{B}^{(l)}\right)^T\right)\\
    =&\sum\limits_{l=1}^{L}\left\|B-\hat{B}\right\|_F^2,
\end{align*} we set the loss function $L\left(B,\hat{B} \right)=\sum\limits_{l=1}^{L}\left\|\hat{B}^{(l)}-B^{(l)}\right\|_F^2=\sum\limits_{l=1}^{L}\sum\limits_{i=1}^{N}\sum\limits_{j=1}^{N}\left(\hat{b}_{ij}^{(l)}-b_{ij}^{(l)} \right)^2.$


\subsection{Mixed Graph Embedding Algorithm for Multi-layer Network Community Detection}

We propose a mixed graph embedding-based modularity reconstruction algorithm (MGE-MTR), which incorporates a feature fusion operation into the encoder output. This contrasts with the independent feature approach proposed in the IGE-MTR algorithm described in \autoref{subsection:Identity Graph Tensor Representation Features}.
%Adding a feature fusion operation to the encoder output, we proposed mixed graph embedding-based modularity reconstruction algorithm (MGE-MTR), unlike the independent features of IGE-MTR algorithm in 
To be precise, we concatenate the output of the second graph convolutional module $h^{(1)}=GCN_1^2\left(A^1hW_1^1\right)$,$\cdots$,$h^{(L)}=GCN_L^2\left(A^LhW_2^L\right)$ into $N\times(rL)$ dimensional graph representation matrices: $H=concat\left( h^{(1)},h^{(2)},\cdots,h^{(L)}\right)$.

\autoref{optimal low rank reconstruction2} provide the theoretical insurance for converting problem \eqref{single obective maximization} into finding the optimal reconstruction of matrix $M=\alpha_1B^{(1)}+\alpha_2B^{(2)}+\cdots+\alpha_LB^{(L)}$. We try to construct each layer of modularity tensor through a single graph representation matrix $H$.

Similarly, we evaluate the effectiveness of modularity reconstruction through the Frobenius-norm distance between matrix $M$ and the reconstruction matrix $\hat{M}$: $\left\|M-\sigma\left(H\cdot H^T \right) \right\|_F^2$. Intrigued by inequation \eqref{MGRF}, minimization of reconstruction distance $\hat{M}$: $\left\|M-\sigma\left(H\cdot H^T \right) \right\|_F^2$ can be relaxed into the sum of all layers Frobenius-distance $\left\|B^{(m)}-\sigma\left(H\cdot H^T \right) \right\|_F^2,\;\forall m,\;1\le m\le L.$ 

