\section{Lemmas}
%\subsection{Lemmas}	
\begin{lemma}\label{[Eckart and Young Theorem]}
	(Eckart and Young Theorem \cite{eckart1936approximation}) For a real matrix $A\in\mathbb{R}^{m\times n}\;(n\ge m)$. Suppose the singular value decomposition of $A$ is $A=U\Sigma V^T$. The optimal solution of the following minimization problem \eqref{best r rank approximation} 
	\begin{align}
		\arg\min\limits_{\substack{{\hat{A}\in\mathbb{R}^{m\times n}}\\ {rank(\hat{A})\le r}}}
		\left\|A-\hat{A}\right\|_F
	\end{align}\label{best r rank approximation}
	is called the best r rank approximation of $A$, which is formulated as $\hat{A}_k=\sum\limits_{i=1}^{r}\sigma_i u_i v_i^T$. And 
	\begin{align*}
		\left\|A-\hat{A}_k\right\|_F=\sqrt{\sigma_{r+1}^2+\cdots+\sigma_{n}^2}.
	\end{align*}

\end{lemma}



\begin{lemma}\label{low rank approximation}
	[Low Rank Approximation] The modularity maximization problem \eqref{modularity maximization problem} in single layer network 
	\begin{align}
		\max\limits_{Tr(Z^TZ)=N}Tr\left(Z^TBZ \right)
	\end{align}\label{modularity maximization problem}
	is equivalent to $r$th-order low-rank reconstruction of modularity degree matrix $B$. Moreover, the $r$th-order low-rank reconstruction can be formulated as $\hat{B}_r=\Psi^T\Psi$, where $\Psi=H\Lambda$, $\Sigma_r=\Lambda^T\Lambda$ and $B=[H,P]\Sigma[H,P]^T.$
\end{lemma}


\begin{proof}[Proof of \autoref{[Eckart and Young Theorem]}]
	The singular value decomposition of $A$ is $A=U\Sigma V^T$.
	\begin{align*}
		&\left\|A\right\|_{F}=\left\|U\Sigma V^T\right\|_{F}=\sqrt{Tr(V\Sigma^TU^TU\Sigma V^T)}=\sqrt{Tr(V\Sigma^T\Sigma V^T)}\\
		=&\sqrt{Tr(\Sigma^T\Sigma V^TV)}=\sqrt{Tr(\Sigma^T\Sigma)}=\sqrt{\sigma_1^2+\cdots+\sigma_n^2}.
	\end{align*}
	Thus 
	\begin{align*}
		\left\|A-\hat{A}_r\right\|_{F}=\sqrt{\sigma_{r+1}^2+\cdots+\sigma_n^2}.
	\end{align*}
    The proof is then finished.
\end{proof}

\begin{proof}[Proof of \autoref{low rank approximation}]
	We use the eigenvalue decomposition: $B=\left[\begin{matrix}
		H&P
	\end{matrix}\right]\left[\begin{matrix}
		\Sigma_r&O\\
		O&\Sigma_{n-r}
	\end{matrix}\right]\left[\begin{matrix}
		H^T\\P^T
	\end{matrix}\right]$,
	where $\Sigma_r$ is diagonal matrix composed of the top $r$-th eigenvalue.
	Consequently, the optimal $r$-rank approximation of modularity matrix B is $\hat{B}_r=H\Sigma_r H^T$. 
	From \autoref{[Eckart and Young Theorem]}, we know that the $r$-th largest eigenvalue of modularity tensor $B$. Thus, part of block matrix $\Sigma_\tau$ is positive-definite. 
	Let $\Sigma_r=\Lambda\Lambda^T$, then $\hat{B}_r=H\Lambda\Lambda^TH^T=(H\Lambda)(H\Lambda)^T.$

    The proof is then finished.
\end{proof}


\section{Computation of Influential Factors and Analysis}\label{Appendix: Influential Factors}
In this section, we formulate the details of iteration process for influential factors computation. 
\begin{algorithm}[H] 
	\caption{Computation of Influential Factors} 
	\label{alg:Framwork} 
	\begin{algorithmic}[1] %这个1 表示从第一行开始显示行号，不写就不会显示行号
		\STATE Initialize the parameters by degree centrality.\\
		$DC=[DC(1),DC(2),\cdots,DC(N)]^T,$\\
		$EC^{(0)}=DC,\;\lambda=0.85.$
		\STATE Calculate the normalization adjacent matrix in each layer $\tilde{A}^{(l)}=D+A$, where $D=diag\left( \sum_{j}a_{1j},\cdots,\sum_{j}a_{Nj}\right).$\\$\tilde{A}=\tilde{A}^{(1)}\cup\tilde{A}^{(2)}\cup\cdots\cup\tilde{A}^{(L)}$\\
		$M=\tilde{D}^{-1}\tilde{A}$

		\STATE Iteration:\\
		While $\left|EC^{(\alpha+1)}-EC^{(\alpha)}\right|>\epsilon\quad\&\quad\alpha<epoch:$\\
		$\qquad EC^{(\alpha+1)}=\lambda\cdot M\cdot EC^{(\alpha)}+(1-\lambda)EC^{(\alpha)}$\\
		$\qquad\alpha=\alpha+1$
	\end{algorithmic}
\end{algorithm}

To verify this algorithm, we test the top 100 of high influential users and visualize its maximum associated users. The maximum associated users is the cardinal number of maximum neighbour vertex: $\left|N_{max}(i)\right|=\left|\cup_{l=1}^{L}N(l,i)\right|$. 
