        \caption{Illustration of the two-parameter microstructure defined by $f_{geom}$ and $f_{sharp}$ with two values of $\alpha \in [0,0.1]$ and three values of $\bar{\eta} \in[0,0.4,0.8]$.}
        \label{fig:twoTermGeometry}
    \end{figure*}

    The macroscale material properties, such as bulk $\kappa$ and shear $\mu$ modulus, are determined using homogenization theory \cite{Guedes1990a, sigmund1994a}. The yield strength is determined following Andersen et al. \cite{Andersen2021a,Andersen2022}. First the microscale stresses are found using
    %
    \begin{equation}
        \bm{\sigma}_e = \mathbf{C}_e (\mathbf{I}-\mathbf{B}_e \mathbf{X}_e) \bar{\bm{\varepsilon}}
    \end{equation}
    %
    where $\mathbf{C}_e$ is the microscale constitutive matrix for the base material. $\mathbf{I}$ is the identity matrix, $\mathbf{B}_e$ is the strain-displacement matrix. The element test field obtained from homogenization are arranged in $\mathbf{X}_e = [\chi_e^1,\chi_e^2,\chi_e^3]$ and $\bar{\bm{\varepsilon}}$ is the homogenized macroscale strain  obtained from the macroscale stress $\bar{\bm{\sigma}}$ using the homogenized constitutive relation
    %
    \begin{equation}
        \bar{\bm{\varepsilon}} = \mathbf{C}_e^{H^{-1}} \bar{\bm{\sigma}}
    \end{equation}
    %
    where $\mathbf{C}_e^{H}$ is the homogenized constitutive matrix. The macroscale stresses are evaluated at states ranging from $\bar{\bm{\sigma}} = [-1,1,0]$ via $\bar{\bm{\sigma}} = [-1,-1,0]$, $\bar{\bm{\sigma}} = [1,-1,0]$, $\bar{\bm{\sigma}} = [1,1,0]$ and back to $\bar{\bm{\sigma}} = [-1,1,0]$, (see \cref{fig:yieldHomogenization:1}). Furthermore, the unit cell is evaluated at seven different orientations in the interval $\theta = \interval{\SI{0}{\degree}}{\SI{30}{\degree}}$ to capture the worst-case scenario. The maximum von Mises stress in the unit cell $\sigma_{vm,max}$ is calculated at each state and used to determine the yield strength $\sigma_y$ of the multiscale material. This is done through the relation
    %
    \begin{equation}
        \sigma_y = \tilde{\sigma}_y \sigma_0 = \min_{\bar{\bm{\sigma}},\theta}\left(\frac{\bar{\sigma}_{vm}(\bar{\bm{\sigma}},\theta)}{\sigma_{vm,max}(\bar{\bm{\sigma}},\theta)}\right) \sigma_0,
    \end{equation} 
    %
    where $\tilde{\sigma}_y$ is the local yield strength factor of the multiscale material relating the base material yield strength $\sigma_0$ to the microscale yield strength $\sigma_y$. The local yield strength factor is determined by the minimum ratio between $\sigma_{vm,max}$ and the macroscale von Mises stress $\bar{\sigma}_{vm}$ to generate a conservative inscribed von Mises yield surface as illustrated in \cref{fig:yieldHomogenization:2} for the arbitrary parameters $\alpha=-0.02$ and $\bar{\eta}= 0.1$. For this configuration the yield strength factor is $\tilde{\sigma}_y = 0.0447$.
