    \subsection{Stress-based Yield Load Factor}\label{sec:method:optProb:yieldConstraint}
    The formulation of the multiscale YLF leverages the unified approach for stress-based optimization \cite{Giraldo-Londono2020}. Using the microscale yield strength definition from \cref{sec:method:microGeometry}, the yield failure surface is defined using the von Mises failure criterion. This conservative criterion effectively uses the inscribed von Mises failure surface, as seen in \cref{fig:yieldHomogenization:2}.

    The yield failure criterion is formulated by calculating an equivalent stress, which for the von Mises failure criterion reduces to
    %
    \begin{equation}\label{eq:FailureSurface}
        \sigma_{eq}(\rho_e^m,\bar{\tilde{x}}_e) = \frac{ 1}{\sigma_{lim}(\bar{\tilde{{x}}}_e)} \sqrt{3 J_2(\rho_e^m,\bar{\tilde{x}}_e)} ,
    \end{equation}
    %
    where $J_2(\rho_e^m,\bar{\tilde{x}}_e)$ represents the second invariant of the deviatoric stress tensor $\bm{s}(\rho_e^m,\bar{\tilde{x}}_e)$ defined as
    %
    \begin{equation}
        \bm{s}(\rho_e^m,\bar{\tilde{x}}_e) = \bm{\sigma}(\rho_e^m,\bar{\tilde{x}}_e) - \dfrac{I_1(\rho_e^m,\bar{\tilde{x}}_e)}{3}\mathbf{I}.
    \end{equation} 
    %
    where $\mathbf{I}$ is the identity matrix and $I_1(\rho_e^m,\bar{\tilde{x}}_e)$ is the first invariant of the Cauchy stress tensor calculated as
    %
    \begin{equation}
        \bm{\sigma}(\rho_e^m,\bar{\tilde{x}}_e) = 
        \mathbf{C}^H(\bar{\tilde{x}}_e) \mathbf{B} \mathbf{u}_0(\rho_e^m),
    \end{equation}
    %
    where $\mathbf{C}^H(\bar{\tilde{x}}_e)$ comes from the homogenization-based material properties interpolated by \cref{eq:shearFit} and \cref{eq:bulkFit}. $\mathbf{B}$ is the strain-displacement matrix, and $\mathbf{u}_0(\rho_e^m)$ is the reference displacement from the linear-elastic state problem in \cref{eq:lineaElastic}. This formulation of the Cauchy stresses, where the density field $\bar{\tilde{x}}_e$ is used to interpolate the material properties, effectively means that stresses in void regions are unphysical but correct in regions where multiscale material is allowed by the indicator field. By using this approach, the indicator field is used to treat the singularity problem \cite{Le2010} using $\varepsilon$-relaxation of the stresses \cite{Guo1997, Duysinx1998, DaSilva2019}. The relaxation is
    %
    \begin{equation}\label{eq:epsilonRelaxation}
        f_{\sigma}(\bar{\tilde{s}}_e) = \dfrac{\bar{\tilde{s}}_e}{\varepsilon (1-\bar{\tilde{s}}_e)+\bar{\tilde{s}}_e},
    \end{equation}
    %
    where $\varepsilon$ is the relaxation parameter. By multiplying \cref{eq:epsilonRelaxation} with the equivalent stresses $\sigma_{eq}(\bm{\rho}^m,\bar{\tilde{\bm{x}}})$, the relaxed stresses are obtained
    %
    \begin{equation}
        \sigma_{rel}(\bm{\rho}^m,\bar{\tilde{\bm{x}}},\bar{\tilde{\bm{s}}}^m) = f_{\sigma}(\bar{\tilde{\bm{s}}}^m) \sigma_{eq}(\bm{\rho}^m,\bar{\tilde{\bm{x}}}).
    \end{equation}

    All the yield stress constraint are aggregated using the $p$-norm defined as
    %
    \begin{equation}\label{eq:pNorm}
      \begin{split}
        \max_{\forall e}(\sigma_{rel}({\rho}^m_e,\bar{\tilde{{x}}}_e,\bar{\tilde{{s}}}_e^m)) \approx& \ \left(\sum_e \sigma_{rel}({\rho}_e^m,\bar{\tilde{{x}}}_e,\bar{\tilde{{s}}}_e^m)^p \right)^{\frac{1}{p}} \\ =& \ \sigma_{PN}(\bm{\rho}^m,\bar{\tilde{\bm{x}}},\bar{\tilde{\bm{s}}}^m),
      \end{split}
    \end{equation}
    %
    where $p \rightarrow \infty$ approaches $\max_{\forall e}(\sigma_{rel}({\rho}^m_e,\bar{\tilde{{x}}}_e,\bar{\tilde{{s}}}_e^m))$. For a better approximation of the actual max value, a correction $c$ following \cite{Le2010} is applied to $\sigma_{PN}$ to obtain the final YLF ($\lambda_{Y}$) definition
    %
    \begin{equation}\label{eq:YLF}
        \lambda_{Y}(\bm{\rho}^m,\bar{\tilde{\bm{x}}},\bar{\tilde{\bm{s}}}^m) = 
        \dfrac{1}{c \sigma_{PN}(\bm{\rho}^m,\bar{\tilde{\bm{x}}},\bar{\tilde{\bm{s}}}^m)}.
    \end{equation}
    %
    The YLF can be used either as an objective or as a constraint. When used as an objective, where $g_y^{obj}$ is minimized to maximize the YLF, it is defined as
    %
    \begin{equation}\label{eq:yieldObejctive}
        g_y^{obj}(\bm{\rho}^m,\bar{\tilde{\bm{x}}},\bar{\tilde{\bm{s}}}^m) = \dfrac{1}{\lambda_{Y}(\bm{\rho}^m,\bar{\tilde{\bm{x}}},\bar{\tilde{\bm{s}}}^m)} = 
        c \sigma_{PN}(\bm{\rho}^m,\bar{\tilde{\bm{x}}},\bar{\tilde{\bm{s}}}^m).
    \end{equation}
    %
    When used as a constraint, \cref{eq:yieldObejctive} is rearranged such that the yield stress constraint is defined as
    %
    \begin{equation}\label{eq:yieldConstraint0}
        \begin{split}
        g_y^{const}(\bm{\rho}^m,\bar{\tilde{\bm{x}}},\bar{\tilde{\bm{s}}}^m) &=  
        \log \left(
            c \sigma_{PN}(\bm{\rho}^m,\bar{\tilde{\bm{x}}},\bar{\tilde{\bm{s}}}^m) \lambda_Y^* \right) \leq 0,
        \end{split}
    \end{equation}
    %
    where $\lambda_Y^*$ is the predefined target YLF or safety factor against yielding. The logarithm is employed to normalize the constraint. The constraint can be formulated such that the YLF is related to the global Buckling Load Factor (BLF), which i defined as $\lambda_B(\gamma_i(\bm{\rho}^m)) = 1/J^{KS}(\gamma_i(\bm{\rho}^m))$. Here $J^{KS}(\gamma_i(\bm{\rho}^m))$ is the KS aggregated eigenvalues scaling the stresses according to the critical BLF to ensure yield strength up to the buckling limit. The definition of $J^{KS}(\gamma_i(\bm{\rho}^m))$ can be found in \cite{Christensen2023}. This modification yields a constraint defined as
    %
    \begin{equation}\label{eq:yieldConstraint}
        \begin{split}
        g_y^{const}(\bm{\rho}^m,\bar{\tilde{\bm{x}}},\bar{\tilde{\bm{s}}}^m,& \gamma_i(\bm{\rho}^m)) = \\ &\log \left(
        \dfrac{c \sigma_{PN}(\bm{\rho}^m,\bar{\tilde{\bm{x}}},\bar{\tilde{\bm{s}}}^m)}{J^{KS}(\gamma_i(\bm{\rho}^m))}  \right) \leq 0.
        \end{split}
    \end{equation}
    %
    % where $J^{KS}(\gamma_i(\bm{\rho}^m))$ is the KS aggregated eigenvalues scaling the stresses according to the critical BLF to ensure yield strength up to the buckling limit. The definition of $J^{KS}(\gamma_i(\bm{\rho}^m))$ can be found in \cite{Christensen2023}.

