\section{Background}\label{sec:background}
We recall here the main definitions and results on quasiseparable and Green matrices that will be used later. Details and proofs can be found in \cite{BE23} and \cite{EGH1}. Note that throughout this paper we use MATLAB notation to denote submatrices, that is, $A(i:j,k:\ell)$ denotes the submatrix of $A$ defined by row indices from $i$ to $j$ and column indices from $k$ to $\ell$.

\begin{definition}
Let $r, N$ be integers such that $N>r>0$.

An $N\times N$ scalar matrix $A=\{A(i,j)\}_{i,j=1}^N$ is called {\em a lower
band matrix of order $r$}  if $A(i,j)=0$ for $i-j>r$.

A matrix $B$ is called {\em a lower Green matrix of order $r$} if
\be\label{natu}
{\rm rank}\,B(k:N,1:k+r-1)\le r,\quad k=1,2,\dots,N-r.
\end{equation}


A matrix $D$ is called {\em an upper Green matrix of order $r$} if
\be\label{natuu}
{\rm rank}\,D(1:k+r-1,k:N)\le r,\quad k=1,2,\dots,N-r.
\end{equation}
\end{definition}

Banded and Green matrices are deeply connected: a well-known result by Asplund \cite{Asplund59} states that the class of invertible lower Green matrices of order $r$
coincides with the class of inverses of invertible lower band
matrices of the same order $r$.

In this work we will employ a particular quasiseparable representation for Green matrices, which we summarize below; see \cite{EGH1} and \cite{BE23} for details.
Let $F=\{F'(i,j)\}_{i,j=1}^K$ be a block matrix
with entries of sizes $m_i\times n_j$. Throughout this paper, we use the prime $'$ symbol to emphasize the fact that we are referring to a block partition of a matrix: for instance, $F(1,1)$ denotes the (scalar) entry of $F$ in position $(1,1)$, whereas $F'(1,1)$ denotes the block of $F$ in position $(1,1)$, which has size $m_1\times n_1$. 

Recall that, if $F$ has a lower quasiseparable structure (i.e., submatrices in the strictly lower triangular part of $F$ have low rank), the strictly lower
triangular part of $F$ admits the quasiseparable representation
\be\label{qrprl}
F'(i,j)=p(i)a_{ij}^{>} q(j),\;1\le j<i\le K,
\end{equation}
where $p(i),\;i=1,\dots,K,\;q(j),\;j=1,\dots,K-1,\;
a(k),\;k=2,\dots,K-1$ are matrices of (small) sizes $m_i\times r_{i-1},r_i\times n_j,
r_k\times r_{k-1}$, respectively. Here we denote $a_{ij}^{>}=a(i-1)\cdots a(j+1)$, with the convention that 
$a_{ij}^{>}$ is the identity matrix if $j\geq i-1$.

In the {\em Green representation} that will be used in this paper, we treat an $N\times N$ scalar matrix as a block matrix of size $(N-r+2)\times
(N-r+2)$. The sizes of the blocks are chosen as
\be\label{msh}
\begin{gathered}
m_0=0,\;m_1=m_2=\dots=m_{N-r}=1,\;m_{N-r+1}=r;\\
n_0=r;\;n_1=n_2=\dots=n_{N-r}=1,\;n_{N-r+1}=0.
\end{gathered}
\end{equation}
Note that indices here start from zero.
A lower band matrix of order $r$ can be seen as a block matrix
with $n_i\times m_j,\;i,j=0,1,\dots,N-r+1$ entries and therefore turns out to be block upper
triangular. A lower Green matrix of order $r$ is seen as a block one with
entries of sizes $m_i\times n_j,\;i,j=0,1,\dots,N-r+1$.

It can be shown that a lower Green matrix $B$ of order $r$ can be written in block form as
\begin{equation}\label{eq:greenrep}
B'(i,j)=p(i)a^>_{ij}q(j),\quad 0\le j<i\le N-r+1
\end{equation}
with matrices $p(i),\;i=1,\dots,N-r+1$ of sizes $m_i\times r$,
$q(j),\;j=0,\dots,N-r$ of sizes $r\times n_j$ and $a(k),\;k=1,\dots,N-r$
of sizes $r\times r$. Without loss of generality we
will assume $q(0)=I_r$. 


Thus the block lower triangular part of a lower Green matrix of order $r$, that is, the part of the matrix where scalar indices $(i,j)$ are such that $j-i\le r$, is completely defined by the parameters
$p(i),q(i),a(i),\;i=1,\dots,N-r,\;p(N-r+1)$.
For instance an $(r+4)\times(r+4)$ matrix $B$ has the form
\begin{gather*}
B'=\\
\left(\ba{ccccc}p(1)&\ast&\ast&\ast&\ast\\
p(2)a(1)&p(2)q(1)&\ast&\ast&\ast\\
p(3)a(2)a(1)&p(3)a(2)q(1)&p(3)q(2)&\ast&\ast\\
p(4)\cdots a(1)&p(4)a(3)a(2)q(1)&p(4)a(3)q(2)&p(4)q(3)&\ast\\
p(5)\cdots a(1)&p(5)a(4)a(3)a(2)q(1)&p(5)a(4)a(3)q(2)&
p(5)a(4)q(3)&p(5)q(4)\ea\right).
\end{gather*}
In particular, note that the first column is a block column of width $r$ and the last row is a block row of height $r$, whereas the remaining entries are scalar.

The elements $p(i),q(i),a(i),\;i=1,\dots,N-r,\;p(N-r+1)$, where
$p(i)\;(i=1,\dots,N-r)$ are $r$-dimensional rows and $p(N-r+1)$ is an
$r\times r$ matrix, $q(i)$ are $r$-dimensional
columns and $a(i)$ are $r\times r$ matrices,
are said to be {\it lower Green generators} of the matrix $B$. Conversely, if the representation (\ref{eq:greenrep})
holds, then $B$ is a lower Green matrix of order $r$.

\begin{remark}\label{rem:green2scalar}
Let us write explicitly the conversion from the Green block representation \eqref{eq:greenrep} of $B$ to the usual scalar representation of the triangular part of $B$, which is indexed from $1$ to $N$. For $1\leq i\leq j\leq N$ we have
\begin{equation}\label{eq:green2scalar}
B(i,j)=\left\{\begin{array}{l}
\left[p(i)a_{i,0}^>\right](j)\qquad {\rm if }\; 1\leq i\leq N-r,\; 1\leq j\leq r,\\
p(i)a_{i,j-r}^> q(j-r) \qquad {\rm if }\; 1\leq i\leq N-r,\; r+1\leq j\leq N,\\
\left[p(N-r+1)a_{N-r+1,j-r}^>q(j-r)\right](i-N+r) \\ \hspace{2cm} {\rm if }\; N-r+1\leq i\leq N,\; r+1\leq j\leq N.
\end{array}\right.
\end{equation}
%In fact, in our Green representation we may also avoid the use of $r\times r$ generator $p(N-r+1)$ and introduce 
%row vectors $p(i)$ for $i=N-r+1,\ldots,N$, so that $p(N-r+\ell)$ coincides with row $\ell$ of matrix $p(N-r+1)$, for $\ell=1,\ldots,r$. If we adopt this modified definition (as we will do in the next section) we can drop the last line of \eqref{eq:green2scalar} and take $1\leq i\leq N$ in the second line. %Another option to encode the last block row is to define extra generators $p(i)$, $a(i)$, $i=N-r+1,\ldots,N-1$ of respective sizes $1\times r_i$, $r_i\times r_{i+1}$ where $r_i = N-i$.
\end{remark}


Let us now recall some results from \cite{BE23} that will be useful in the 
development of our decay bounds. The following theorem provides a structured LU 
factorization of a lower banded matrix.

\begin{theorem}\label{ICF1}
Let $A=\{A(i,j)\}_{i,j=1}^N$ be a strongly regular lower band matrix of order $r$.

Then $A$ admits the factorization
\be\label{irn15}
A=LR,
\end{equation}
where $L$ is a unit lower triangular matrix and $R$ is an upper triangular 
matrix. The inverse $L^{-1}$ of the lower triangular factor $L$ may be 
represented as the product
\be\label{un}
L^{-1}=\tilde L_{N-r+1}\tilde L_{N-r}\cdots\tilde L_2\tilde L_1
\end{equation}
with
\be\label{un1}
\tilde L_k=I_{k-1}\oplus L_k\oplus I_{N-k-r},\; k=1,\dots,N-r,\quad
\tilde L_{N-r+1}=I_{N-r}\oplus L_{N-r+1},
\end{equation}
and $(r+1)\times(r+1)$ lower triangular matrices
$L_k,\;k=1,\dots,N-r$ and $r\times r$ lower triangular matrix $L_{N-r+1}$.
Moreover, the lower triangular matrices $L_k$ as well as the upper triangular
entries of the matrix $R$ are obtained as follows.

1. Set
\be\label{lry0}
Y_0=A(1:r,1:N),\quad\gamma_1=Y_0(1,1).
\end{equation}

2. For $k=1,\dots,N-r$ perform the following.
Set 
\be\label{irks}
\gamma_k=Y_{k-1}(k,k),\; X_k=Y_{k-1}(k,k+1:N)
\end{equation}
and compute
\be\label{lnk}
f_k=\left(\ba{c}Y_{k-1}(k+1:k+r-1,k)\\A(k+r,k)\ea\right)\frac1{\gamma_k}.
\end{equation}
Set
\be\label{ol}
Z_k=\left[\ba{c}Y_{k-1}(k+1:k+r-1,k+1:N)\\A(k+r,k+1:N)\ea\right]
\end{equation}
and compute
\be\label{olz}
Y_k=-f_k\cdot X_k+Z_k.
\end{equation}
Set
\be\label{natas}
L_k=\left(\ba{cc}1&0\\-f_k&I_r\ea\right).
\end{equation}
Set
\be\label{olia}
R(k,k)=\gamma_k,\quad R(k,k+1:N)=X_k.
\end{equation}


3. For $k=N-r+1,\dots,N-1$ perform the following.

Set $\gamma_k=Y_{k-1}(k,k),\; X_k=Y_{k-1}(k,k+1:N)$ and compute
\be\label{lnk3}
f_k=Y_{k-1}(k+1:N,k+1)\frac1{\gamma_k}.
\end{equation}
Set
\be\label{ol3}
Z_k=Y_{k-1}(k+1:N,k+1:N)
\end{equation}
and compute
\be\label{olz3}
Y_k=-f_k\cdot X_k+Z_k.
\end{equation}
Set
$$
L_k=\left(\ba{cc}1&0\\-f_k&I_r\ea\right).
$$
Set
\be\label{olia3}
R(k,k)=\gamma_k,\quad R(k,k+1:N)=X_k.
\end{equation}


4. Set $\gamma_N=Y_{N-1},\;R(N,N)=\gamma_N$.
\end{theorem}

Quasiseparable generators for the lower triangular factor can be extracted from
 the matrices $L_k$ as follows.

\begin{lemma}\label{AA}
The matrix $L^{-1}$ in (\ref{un}), (\ref{un1}) is a lower Green - upper
band of order $r$ matrix with lower Green generators $p_L(i),q_L(i),a_L(i)\;
i=1,\dots,N-r$ and diagonal entries $d_L(k)\;(k=1,\dots,N-r)$ obtained from the
partitions
\be\label{iof5}
L^{-1}_k=\left[\ba{cc}p_L(k)&d_L(k)\\a_L(k)&q_L(k)\end{array}\right],\quad
k=1,\dots,N-r
\end{equation}
and by setting
\be\label{iof5r}
p_L(N-r+1)=L_{N-r+1}.
\end{equation}
\end{lemma}

Building on Theorem \ref{ICF1} and Lemma \ref{AA}, we can now compute 
quasiseparable generators for the lower triangular part of the inverse of a 
lower banded matrix.

\begin{theorem}\label{UF1}
Let $A$ be a strongly regular lower band matrix of order $r$.

Then lower Green generators $p(i),q(i),a(i)\;(i=1,\dots,N-r)$,
$P_{N-r+1}$ of the matrix $A^{-1}$ are obtained as follows.

1. Using the algorithm from Theorem \ref{ICF1} compute the lower triangular
 matrices
$L_k\;(k=1,\dots,$
$N-1)$ of orders $r_k=r$ for $k=1,\dots,N-r$ and
$r_k=N-k+1$ for $k=N-r+1,\dots,N-1$,
as well as diagonal entries and subrows
\be\label{tre}
\gamma_k=R(k,k),\;k=1,\dots,N,\quad X_k=R(k,k+1:N),\;k=1,\dots,N-1
\end{equation}
of the lower triangular matrix $R$.
Determine the lower Green generators $p_L(i),q_L(i)$,
$a_L(i)\;(i=1,\dots,N-r)$ of the 
lower Green-upper band matrix $L^{-1}$ via partitions (\ref{iof5}) and the
matrices $p_L(i),a_L(i)\;(i=N-r+1,\dots,N-1)$ of sizes $1\times r_i,
r_i\times r_{i+1}$ from the partitions
\be\label{iof5.}
L_i=\left[\ba{c}p_L(i)\\a_L(i)\end{array}\right],\quad
i=N-r+1,\dots,N-1.
\end{equation}

2. Compute the lower Green generators of the matrix $A^{-1}$ as follows.

2.1. Compute the lower Green generator $P_{N-r+1}$ as follows.
Set
\be\label{rn}
p(N)=P_N=\frac1{\gamma_N},
\end{equation}
and for $k=N-1,\dots N-r+1$ compute
\be\label{mishln}
p(k)=\frac1{\gamma_k}(p_L(k)-X_kP_{k+1}a_L(k))
\end{equation}
\be\label{mashln}
P_k=\left(\ba{c}p(k)\\P_{k+1}a_L(k)\ea\right).
\end{equation}


2.2. Compute the lower Green generators $p(k),q(k),a(k)$ as follows.

2.2.1. Set
\be\label{masl}
q(k)=q_L(k),\;a(k)=a_L(k),\;k=1,\dots,N-r.
\end{equation}

2.2.2. For $k=N-r,\dots 1$ compute
\be\label{mishl}
p(k)=\frac1{\gamma_k}(p_L(k)-X_kP_{k+1}a(k))
\end{equation}
\be\label{mashl}
P_k=\left(\ba{c}p(k)\\P_{k+1}a(k)\ea\right).
\end{equation}
\end{theorem}

\begin{remark}
The generator $P_{N-r+1}$ from step 2.1 of Theorem \ref{UF1} can also be computed as $P_{N-r+1}=R(N-r+1:N,N-r+1:N)^{-1}L_{N-r+1}$.
\end{remark}

\section{LU-based decay bounds: the main result}\label{sec:main}
\setcounter{equation}{0}

Let us now introduce the main result of this paper, that is, estimates for entries of the inverses of (possibly one-sided) band matrices in terms of the matrix elements. 
The main hypothesis here is a diagonal dominance condition, which is easy to check on a given matrix. 

\begin{theorem}\label{TTR}
Let $A=\{A(i,j)\}_{i,j=1}^N$ be an invertible lower-banded matrix of order $r$. 
Assume that $A$ satisfies the following strong dominance condition 
\begin{equation}\label{gl1}
\mu|A(k,k)|\geq \sum_{i=1}^{k-1}|A(i,k)|+\sum_{i=k+1}^{k+r}|A(i,k)|,\;
k=1,2,\dots,N
\end{equation}
with $0<\mu<1$.

Then for the Green block representation of $A^{-1}$ it holds
\begin{equation}\label{mrn}
|(A^{-1})'(i,j)|\le M\gamma^{i-j-r},\quad i - j > r
\end{equation}
with $\gamma=\mu^{1/r}$ and $M=\frac{1+\mu^2}{(1-\mu)(1-\mu^2)\min_i|A(i,i)|}.$
\end{theorem}

The proof of Theorem \ref{TTR} will be presented in the next section. 

Note that \eqref{mrn} is given in terms of the Green blocks of $A^{-1}$. For practical purposes it may be more useful to reframe this result in terms of the usual scalar representation. 

\begin{theorem}\label{thm:bound}
Let $A$, $\mu$, $\gamma$, $M$ be as in Theorem \ref{TTR}. Then for $i\geq j$ it holds
\begin{equation}\label{simplebound}
|(A^{-1})(i,j)|\le M\gamma^{i-j}.
\end{equation}
\end{theorem}

\begin{proof}
Consider at first the case $i=j$. Using Corollary \ref{cor:varah} in Section \ref{sec:proof} we have
$$
|(A^{-1})(i,i)|\leq\|A^{-1}\|_1<\frac{1}{(1-\mu)\min_k|A(k,k)|}<M.
$$
Let us now discuss the case $i>j$. Define the augmented matrix
$$
\mathcal{A}=I_r\oplus A\oplus I_r\in\mathbb{R}^{\tilde{N}\times\tilde{N}},
$$
with $\tilde{N}=N+2r$. Note that $\mathcal{A}$ satisfies hypothesis \eqref{gl1} with the same value of $\mu$ as $A$. Combining \eqref{mrn} applied to $\mathcal{A}$ with Remark \ref{rem:green2scalar} we can write
\begin{equation}\label{mrns}
|(\mathcal{A}^{-1})(i,j)|\le \left\{\begin{array}{l}
M\gamma^{i-r},\qquad r+1\leq i\leq \tilde{N}, 1\leq j\leq r\\
M\gamma^{i-j},\qquad r+1\leq j<i\leq \tilde{N}-r\\
M\gamma^{\tilde{N}-r+1-j},\qquad \tilde{N}-r+1\leq i\leq \tilde{N}, r+1\leq j \leq \tilde{N}-r.\\
\end{array}\right.
\end{equation}
The thesis follows from the second line in \eqref{mrns}.
\end{proof}

