\mu|A(k,k)|\geq \sum_{i=k-r}^{k-1}|A(i,k)|+\sum_{i=k+1}^{k+r}|A(i,k)|.
$$
\end{remark}

\section{Proof of LU-based decay bounds}\label{sec:proof} 
Let us start with two technical lemmas.

\begin{lemma}\label{lemma:fk}
Under the hypotheses of Theorem \ref{TTR}, it holds 
\be\label{larr}
\|f_k\|_1\le\mu<1,\quad k=1,\dots,N-r
\end{equation}
\end{lemma}

\begin{proof}
Consider the first step of the algorithm from Theorem \ref{ICF1}.
Note that the hypothesis (\ref{gl1}) implies
\be\label{simplegl1}
\mu|A(k,k)|\ge \sum_{i=1}^{k-1}|A(i,k)|+\sum_{i=k+1}^{k+r}|A(i,k)|,\;
k=1,2,\dots,N-r.
\end{equation}
This yields for $k=1$ 
$$
\mu|A(1,1)|\ge \|A(2:r+1,1)\|_1,
$$ 
which implies $\|f_1\|_1\le\mu$. As a result of the first step we obtain the 
matrix 
$$
{\mathcal A}_1=\tilde L_1A=\left(\ba{cc}\gamma_1&H_1\\0&A_1\ea\right),
$$
where $H_1=A(1,2:N)$ and the $(N-1)\times(N-1)$ matrix $A_1$ is the Schur complement
\be\label{ire1}
A_1=A(2:N,2:N)-f_1H_1.
\end{equation}
Next we apply the same procedure to $A_1$, which is lower banded of order $r$, and so on. In order to prove the lemma, it suffices to prove that the matrix $A_1=\{A_1(i,j)\}_{i,j=2}^N$ 
satisfies the diagonal dominance conditions (\ref{simplegl1}), i.e.
\be\label{iroc}
\mu|A_1(k,k)|\ge \sum_{i=2}^{k-1}|A_1(i,k)|+\sum_{i=k+1}^{k+r}|A_1(i,k)|,\;
k=2,\dots,N-r.
\end{equation}
Using (\ref{ire1}) we have
\be\label{qyr}
A_1(k,k)=A(k,k)-f_1(k)A(1,k),\;k=2,\dots,N-r
\end{equation}
and
\be\label{qyrj}
A_1(i,k)=A(i,k)-f_1(i)A(1,k),\;k=2,\dots,N-r,\;i=2,\dots,N-r,\;i\neq k.
\end{equation}
Using (\ref{qyr}) and (\ref{qyrj}) we obtain the inequalities
\be\label{gyr}
|A_1(k,k)|\ge|A(k,k)|-|f_1(k)||A(1,k)|,\;k=2,\dots,N-r
\end{equation}
and
\be\label{gyrj}
|A_1(i,k)|\le|A(i,k)|+|f_1(i)||A(1,k)|,\;
k=2,\dots,N-r,\;i=2,\dots,N-r,\;i\neq k.
\end{equation}
Summing the inequalities in (\ref{gyrj}) over index $i$ we get
\begin{gather*}
\sum_{i=2}^{k-1}|A_1(i,k)|+\sum_{i=k+1}^{k+r}|A_1(i,k)|\le\\
\sum_{i=2}^{k-1}|A(i,k)|+\sum_{i=k+1}^{k+r}|A(i,k)|+
\left(\sum_{i=2}^{k-1}|f_1(i)|+\sum_{i=k+1}^{k+r}|f_1(i)|\right)|A(1,k)|\le\\
\sum_{i=1}^{k-1}|A(i,k)|+\sum_{i=k+1}^{k+r}|A(i,k)|+\|f_1\|_1|A(1,k)|-|A(1,k)|-
|f_1(k)||A(1,k)|.
\end{gather*}
Using (\ref{gl1}) and (\ref{gyr}) and the inequality
$$
-1+\|f_1\|_1-|f_1(k)|\le-\mu|f_1(k)|
$$
we have
$$
\sum_{i=2}^{k-1}|A_1(i,k)|+\sum_{i=k+1}^{k+r}|A_1(i,k)|\le
\mu|A(k,k)|-\mu|f_1(k)||A(1,k))|\le\mu|A_1(k,k)|, 
$$
therefore (\ref{iroc}) holds.
\end{proof}

\begin{remark}\label{rem:schurdominant}
It is well-known that Schur complements of diagonally dominant matrices inherit the diagonal dominance property. Note that the proof of Lemma \ref{lemma:fk} also shows the corresponding result for the notion of strong diagonal dominance defined in \eqref{simplegl1}: if a matrix is diagonally dominant in the sense of \eqref{simplegl1}, for some value of $0<\mu<1$, then its Schur complements also satisfy \eqref{simplegl1} for the same value of $\mu$. 
\end{remark}

\begin{lemma}\label{lemma:gammak}
Let $A\in\mathbb{R}^{N\times N}$ be a matrix such that
\begin{equation}
\mu |A(k,k)|> \sum_{i\neq k} |A(i,k)|,\qquad k=1,\ldots,N \label{eq:hplemma}
\end{equation}
for $\mu\in (0,1)$. Since $A$ is (column) strictly diagonally dominant,
it admits an LU decomposition $A=LR$, with the usual convention that
$L$ has diagonal elements equal to 1. Then it holds
$$
|R(k,k)|\geq (1-\mu^2) |A(k,k)| ,\qquad k=1,\ldots,N.
$$ 
\end{lemma}

\begin{proof}
The thesis is obviously true for $k=1$, since $R(1,1)=A(1,1)$. Let then $k\geq 2$. It is well known from the 
theory of LU decomposition \cite{Gantmacher} that the $k$-th diagonal entry of the upper triangular factor $R$
can be written as
\begin{equation}
R(k,k)=\frac{{\rm det}\, A(1:k,1:k)}{{\rm det}\, A(1:k-1,1:k-1)}. \label{eq:detquotient}
\end{equation}
For ease of notation, denote the $k\times k$ matrix $A(1:k,1:k)$ as $\tilde{A}$.

The following argument is adapted from the proof of Theorem 1 in \cite{Price51}. 
Consider the problem of finding
$x_1, \ldots, x_{k-1}\in\mathbb{R}$ such that
\begin{equation}
[x_1,\, \dots\, , x_{k-1} ,\, 1]\, \tilde{A}(1:k, 1:k-1) = [0 ,\, \dots \, , 0].\label{eq:auxsystem}
\end{equation}
This amounts to solving a linear system with strictly diagonally dominant matrix $\tilde{A}(1:k-1, 1:k-1)^T$, therefore the solution exists and is unique. Moreover, it holds $|x_j|\leq \mu$, $j=1,\ldots, k-1$. Indeed, let $\ell\in \{1,\dots,k-1\}$ be such that $|x_{\ell}|=\max \{|x_1|,\ldots,|x_{k-1}|\}$ and
suppose by contradiction that $|x_{\ell}|> \mu$. The $\ell$-th equation in \eqref{eq:auxsystem} takes the form   
$$
\sum_{i=1}^{k-1} x_i \tilde{A}(i,\ell) + \tilde{A}(k,\ell)=0,
$$
which we can rewrite as
$$
-\tilde{A}(\ell,\ell) x_{\ell} = \tilde{A}(k,\ell) + \sum_{\substack{i=1 \\ i\neq\ell}}^{k-1} x_i \tilde{A}(i,\ell).
$$
Taking absolute values we have 
$$
|\tilde{A}(\ell,\ell)|\, |x_{\ell}| \leq |\tilde{A}(k,\ell)| + \sum_{\substack{i=1 \\ i\neq\ell}}^{k-1}|x_i|\, |\tilde{A}(i,\ell)| 
$$
and dividing by $|x_{\ell}|$ we obtain
$$
|\tilde{A}(\ell,\ell)| \leq \frac{|\tilde{A}(k,\ell)|}{|x_{\ell}|} + \sum_{\substack{i=1 \\ i\neq\ell}}^{k-1} |\tilde{A}(i,\ell)| \frac{|x_i|}{|x_{\ell}|}
< \frac{1}{\mu} |\tilde{A}(k,\ell)| + \sum_{\substack{i=1 \\ i\neq\ell}}^{k-1} |\tilde{A}(i,\ell)|
$$
which contradicts \eqref{eq:hplemma}.

Now, let $\hat{A}$ the matrix obtained from $\tilde{A}$ by replacing the last row with $\tilde{A}(k,:)+\sum_{i=1}^{k-1}x_i\tilde{A}(i,:)$. Note that all the entries of the last row of $\hat{A}$ are zero, except for the last one.
Therefore we have
\begin{eqnarray*}
&&{\rm det}\, \tilde{A} = {\rm det}\, \hat{A} = \hat{A}(k,k)\, {\rm det}\, \tilde{A}(1:k-1,1:k-1)=\\
&&=\left(\tilde{A}(k,k)+\sum_{i=1}^{k-1}x_i\tilde{A}(i,k)\right) {\rm det}\, \tilde{A}(1:k-1,1:k-1)
\end{eqnarray*}
and therefore, using $|x_i|\leq \mu$ and \eqref{eq:hplemma}:
\begin{eqnarray*}
|{\rm det}\, \tilde{A}|&\geq& \left(|\tilde{A}(k,k)|-\Big|\sum_{i=1}^{k-1}x_i\tilde{A}(i,k)\Big|\right) {\rm det}\, \tilde{A}(1:k-1,1:k-1)\\
&\geq& \left(|\tilde{A}(k,k)|-\mu\sum_{i=1}^{k-1}|\tilde{A}(i,k)|\right) {\rm det}\, \tilde{A}(1:k-1,1:k-1)\\
&\geq& (1-\mu^2) \,|\tilde{A}(k,k)|\, {\rm det}\, \tilde{A}(1:k-1,1:k-1).\label{eq:detmu}
\end{eqnarray*}
By substituting this inequality in \eqref{eq:detquotient} we obtain the thesis.

\end{proof}

We will also need the following result on Green generators for inverses of partially factorized matrices.

\begin{proposition}\label{prop:pfact}
Let $A=\{A(i,j)\}_{i,j=1}^N$ be a strongly regular lower band matrix of order $r$ and let $ A = L^{(\ell)} A^{(\ell)} $ be its partial LU decomposition obtained after $\ell$ steps of Gaussian elimination, with $1\leq \ell \leq N-r$. Denote as $p(i),q(i),a(i)\;(i=1,\dots,N-r)$,
$P_{N-r+1}$ the Green generators of $A^{-1}$ computed as in Theorem \ref{UF1}.

Let $\tilde{A}^{(\ell)}=A^{(\ell)}(\ell+1:N,\ell+1:N)$ and $B^{(\ell)}=(\tilde{A}^{(\ell)})^{-1}$. Then the Green generators for  $B^{(\ell)}$ computed by applying Theorem \ref{UF1} to $\tilde{A}^{(\ell)}$ are $p(i+\ell),q(i+\ell),a(i+\ell)\;(i=1,\dots,N-\ell-r)$, $P_{N-r+1}$.

\end{proposition}

\begin{proof}
Let $A=LR$ be the LU decomposition of $A$ and let the matrices $L_k$ be defined as in Theorem \ref{ICF1}. Analogously, let $\tilde{A}^{(\ell)}=L^{(\ell)}R^{(\ell)}$ be the LU decomposition of $\tilde{A}^{(\ell)}$ and let the matrices $L_k^{(\ell)}$ be defined as in Theorem \ref{ICF1}. Clearly it holds $L_k^{(\ell)}=L_{k+\ell}$, since the steps of the LU factorization of $\tilde{A}^{(\ell)}$ coincide with the last $N-r-\ell$ steps of the LU factorization of $A$. For the same reason, it holds 
\begin{equation}\label{eq:sameR}
R^{(\ell)}=R(\ell+1:N,\ell+1:N). 
\end{equation}
By Lemma \ref{AA}, the lower Green generators of $(L^{(\ell)})^{-1}$ are a subset of the lower Green generators of $L^{-1}$, that is,
\begin{equation}\label{eq:Lgen}
p_L^{(\ell)}(k)=p_L(k+\ell),\qquad 
q_L^{(\ell)}(k)=q_L(k+\ell),\qquad 
a_L^{(\ell)}(k)=a_L(k+\ell),
\end{equation}
for $k=1,\ldots,N-r-\ell$.

Now let us apply Theorem \ref{UF1} to $A$ and to $\tilde{A}^{(\ell)}$ and compare the Green generators for $A^{-1}$ and for $B^{(\ell)}$. From \eqref{masl} we immediately have $p^{(\ell)}(k)=p(k+\ell)$, $q^{(\ell)}(k)=q(k+\ell)$ and $a^{(\ell)}(k)=a(k+\ell)$, for $k=1,\ldots,N-r-\ell$. Then from \eqref{mishln} and \eqref{mishl} we obtain 
\begin{eqnarray*}
&&p^{(\ell)}(k)=\frac1{\gamma^{(\ell)}_k}(p^{(\ell)}_L(k)-X^{(\ell)}_k P^{(\ell)}_{k+1}a^{(\ell)}(k))=\\
&& = \frac1{\gamma_{k+\ell}}(p_L(k+\ell)-X_{k+\ell} P_{k+\ell+1}a(k+\ell))= p(k+\ell),
\end{eqnarray*}
where the relations $\gamma^{(\ell)}_k=\gamma_{k+\ell}$ and $X^{(\ell)}_k = X_{k+\ell}$ are a consequence of \eqref{eq:sameR}. 
\end{proof}

Inverses of strictly diagonally dominant matrices can be bounded in norm, in terms of a parameter that quantifies the amount of diagonal dominance. Indeed, recall the following result from \cite{Varah75}:
\begin{theorem}\label{thm:varah}
Let $A\in\mathbb{R}^{N\times N}$ be diagonally dominant by columns and set
$$
\beta=\min_k \left(|A(k,k)|-\sum_{j\neq k}|A(j,k)|\right).
$$
Then it holds
$$
\|A^{-1}\|_1\leq\frac{1}{\beta}.
$$
\end{theorem}

From Theorem \ref{thm:varah} we deduce the following result, which will be useful in the proof of Theorem \ref{TTR}.

\begin{cor}\label{cor:varah}
Let $A=\{A(i,j)\}_{i,j=1}^N$ satisfy the condition \eqref{gl1}. Then it holds
$$
\|A^{-1}\|_1\leq\frac{1}{(1-\mu)\min_i |A(i,i)|}.
$$
\end{cor}
\begin{proof}
Let us apply Theorem \ref{thm:varah}. In our case we have 
$$
|A(k,k)|-\sum_{j\neq k}|A(j,k)|>(1-\mu)|A(k,k)|
$$
for $k=1,\ldots,N$ and therefore
$$
\beta=\min_k \left(|A(k,k)|-\sum_{j\neq k}|A(j,k)|\right)>(1-\mu)\min_k|A(k,k)|,
$$
from which we deduce
$$
\|A^{-1}\|_1\leq\frac{1}{\beta}<\frac{1}{(1-\mu)\min_k|A(k,k)|}.
$$
\end{proof}




We are now ready to prove Theorem \ref{TTR}.

\vspace{20pt}

{\bf Proof of Theorem \ref{TTR}.}
From Theorem \ref{UF1} and Remark \ref{rem:green2scalar} we have for the Green block form of $A^{-1}$:
$$
(A^{-1})'(i,j)=p(i)a^>_{ij}q(j),\qquad 1\leq i\leq N,\quad 0\le j\le N-r
$$
with the lower Green generators $a(k),q(k)$ obtained from the lower triangular
matrix $L^{-1}$ via
$$
q(k)=q_L(k),\;a(k)=a_L(k),\;k=1,\dots,N-r
$$
and $p(i)$ obtained in Step 2 of the algorithm in Theorem \ref{UF1}.
We will prove that the generators $p(i)$ are bounded, i.e.,
\begin{equation}\label{lrlo}
\|p(i)\|_{\infty}\leq M,\quad  i=1,2,\dots N,
\end{equation}
where $M=\frac{1}{(1-\mu)\min_i |A_{i,i}|}$,
and the vectors $a^>_{ij}q(j)$ satisfy the estimates
\begin{equation}\label{lrlos}
\|a^>_{ij}q(j)\|_1\leq\gamma^{i-j-r},\quad i\geq j+r
\end{equation}
for $0<\gamma=\mu^{1/r}<1$. This will yield the thesis.

Unless otherwise noted, in this proof all vector and matrix norms are understood to be the vector 1-norm and the corresponding induced matrix norm. 

Note that from Lemma \ref{AA} we obtain the lower Green generators of the matrix 
$L^{-1}$ via the formulas (\ref{natas}) with the partitions (\ref{iof5}). Moreover, Lemma
\ref{lemma:fk} ensures $\|f_k\|_1\le\mu<1$. 

{\bf Part 1}: let us prove (\ref{lrlos}). At first we derive an auxiliary
relation. Set 
\be\label{larkr}
F_m=I_r,\quad F_i=a(i)a(i-1)\cdots a(m+1),\;i=m+1,\dots,m+r.
\end{equation}
From (\ref{natas}) we can write 
\be\label{itr}
a_L(k)=a(k)=-f_k e_1^T+J
\end{equation}
where $e_1=[1,0,\ldots,0]^T\in\mathbb{R}^r$ and $J$ is the $r\times r$ Jordan block 
$$
J=\left(\ba{cccccc}
0&1&0&\dots&0&0\\
0&0&1&\dots&0&0\\
\vdots&\vdots&\vdots&\vdots&\vdots&\vdots\\
0&0&0&\dots&0&1\\0&0&0&\dots&0&0\ea\right).
$$
Note that \eqref{itr} implies $\|a(k)\|\leq 1$.

Set 
\be\label{olg}
V_i=J^{i-m},\;i=m,\dots,m+r.
\end{equation}
It is clear that $V_m=I_r,\;V_{i+1}=JV_i,\;i=m,\dots,m+r-1,\;V_{m+r}=0$.
Next we set $\Gamma_i=F_i-V_i,\;i=m,\dots,m+r$, i.e.
\be\label{lariss}
F_i=\Gamma_i+V_i,\quad i=m,m+1,\dots,m+r.
\end{equation}
Moreover we have $F_{i+1}=a(i+1)F_i$ and using (\ref{itr}) and (\ref{lariss}) we
get
\be\label{irg}
F_{i+1}=(-f_{i+1}e_1^T+J)(\Gamma_i+V_i)=
-f_{i+1}e_1^T\Gamma_i+J\Gamma_i-f_{i+1}e_1^T\Gamma_i+V_{i+1},\;i=m,\dots,m+r-1.
\end{equation}
We have obviously $\Gamma_m=F_m-V_m=0$ and moreover (\ref{irg}) and 
(\ref{lariss}) imply
\be\label{irut}
\Gamma_{i+1}=-f_{i+1}e_1^T\Gamma_i+J\Gamma_i-f_{i+1}e_1^TV_i,\;i=m,\dots,m+r.
\end{equation}
Hence for any $r$-dimensional column vector $g=[g(1),\dots,g(r)]^T$ we get
\be\label{alk}
\Gamma_{i+1}g=-f_{i+1}e_1^T(\Gamma_ig)+J\Gamma_ig-f_{i+1}e_1^TV_ig.
\end{equation}
We prove by induction that
\begin{equation}
\|\Gamma_ig\|\le\mu(|g(1)|+\dots+|g(i-m)|),\;i=m,\dots,m+r.\label{alu1}
\end{equation}
For $i=m$ since $\Gamma_m=0$ the statement is clear. Assume that for some $i$ 
with $m\le i\le m+r-1$ the relation (\ref{alu}) holds. Using (\ref{alk}) we get
$$
\|\Gamma_{i+1}g\|\le\|f_{i+1}\|\, |e^T_1(\Gamma_ig)+\|J(\Gamma_ig)\|+
\|f_{i+1}\|\, |g(i-m+1)|.
$$
Using the inequalities $\|f_{i+1}||\le \mu<1$ we get
$$
\|\Gamma_{i+1}g\|\le |e^T_1(\Gamma_ig)|+\|J(\Gamma_ig)\|+\mu|g(i-m+1)|.
$$
For any $r$-dimensional column vector $h$ the equality 
$$
|e_1^Th|+\|Jh\|=\|h\|
$$
holds and using (\ref{alu1}) we conclude that 
$$
\|\Gamma_{i+1}g\|\le\mu(|g(1)|+\dots+|g(i-m)|+|g(i-m+1)|).
$$
Taking $i=m+r$ in (\ref{alu1}) we get $\|\Gamma_{m+r}\|\le\mu$. 


Moreover the equality (\ref{olg}) 
with $i=m+r$ implies $V_{m+r}=0$ and therefore $F_{m+r}=\Gamma_{m+r}$ and we 
conclude that
\be\label{lij}
\|F_{m+r}\|\le\mu.
\end{equation}

In accordance with (\ref{lrlos}) consider 
the products $a_{ij}^>,\;i-j\geq r$. Recall that $a_{ij}^>$ is defined as the product of $i-j-1$ factors.  We use the representation $i-j-1=rt+l$, where the 
positive integer $t$ is the quotient of $i-j-1$ divided by $r$, and $l$ with $0\le l<r$ is the reminder. We have
$$
a^>_{ij}=a(i-1)\cdots a(j+1)=a(i-1)\cdots a(i-l)a(rt+j)\cdots a(j+1),
$$
where  
the product $a(i-1)\cdots a(i-l)$ is assumed to be $1$ if $l=0$.
From the inequalities $\|a(k)\|\le1$ applied with $k=i-l,\dots,i-1$ and from (\ref{lij}) we get
$$
\|a_{ij}^>\|\le \|a(rt+j)\cdots a(j+1)\|\le\mu^t.
$$
Using the equality $t=(i-j)/r-(l+1)/r$ and setting 
$\gamma=\mu^{1/r}$ we conclude that
\be\label{alu}
\|a_{ij}^>\|\le \gamma^{i-j-r}.
\end{equation}
From 
\eqref{natas}, \eqref{iof5} and \eqref{masl} 
we deduce $\|q(k)\|=1$,
whichi concludes the proof of \eqref{lrlos}.


{\bf Part 2}: 
Consider at first the case $i=1$. From the Green representation of $A^{-1}$ we have 
$p(1,:)=A^{-1}(1,1:r)$. But Corollary \ref{cor:varah} implies 
$$|A^{-1}(j,k)|\leq \frac{1}{(1-\mu)\min_i |A_{i,i}|}<M$$ for all indices $j,k=1,\ldots,N$. Therefore it holds
$$\|p(1,:)\|_{\infty}\leq M.$$

Now suppose $i>1$ and consider the partial LU decomposition 
$$ A = L^{(i)} A^{(i)} $$
obtained after $i-1$ steps of Gaussian elimination as in Theorem \ref{ICF1}. Note that the matrix $A^{(i)}(i:N,i:N)\in\mathbb{R}^{(N-i+1)\times (N-i+1)}$ inherits from $A$ the diagonal dominance property \eqref{gl1}, as proved in Lemma \ref{lemma:fk}; see also Remark \ref{rem:schurdominant}.

Let $\tilde{A}^{(i)}=A^{(i)}(i:N,i:N)$ and $B^{(i)}=(\tilde{A}^{(i)})^{-1}$. From Proposition \ref{prop:pfact} we have $p(i,:)=B^{(i)}(1,1:r)$. The definition of matrix 1-norm implies that the $1$-norm of any given matrix is larger than or equal to the absolute value of any entry in the matrix; in particular it holds $|B^{(i)}(h,k)|\leq \|B^{(i)}\|_1$ for any index pair $(h,k)$ and therefore $\|B^{(i)}(1,1:r)\|_{\infty}\leq \|B^{(i)}\|_1$. Then Corollary \ref{cor:varah} applied to $\tilde{A}^{(i)}$ yields  
\begin{equation}\label{eq:firstestimate}
\|p(i,:)\|_{\infty}\leq\frac{1}{(1-\mu)\min_j|\tilde{A}^{(i)}(j,j)|}.
\end{equation}
In order to give an estimate for $\tilde{A}^{(i)}(j,j)$, observe that the upper triangular factor in the LU factorization of $\tilde{A}^{(i)}(j,j)$ coincides with $R(i:N,i:N)$, where $R$ is the upper triangular factor in the LU factorization of $A$. From Lemma \ref{lemma:gammak} and from the diagonal dominance property of $\tilde{A}^{(i)}$ we have
$$
(1+\mu^2)|\tilde{A}^{(i)}(j,j)|\geq |R(i+j-1,i+j-1)|\geq (1-\mu^2)|A(i+j-1,i+j-1)|,
$$
and therefore
\begin{equation}\label{eq:diagbound}
\tilde{A}^{(i)}(j,j)|\geq \frac{1-\mu^2}{1+\mu^2}|A(i+j-1,i+j-1)|.
\end{equation}
From \eqref{eq:firstestimate} and \eqref{eq:diagbound} we deduce 
$$\|p(i,:)\|_{\infty}\leq\frac{1+\mu^2}{(1-\mu)(1-\mu^2)\min_k|A(k,k)|},$$
which concludes the proof.


$\hfill\Box$

